RPM_GeographyHintsFR={
{quest=465,objective="Allez voir Darien Gautier",step="En cherchant le capitaine Janève, j'ai croisé Darien Gautier. Il est blessé. Il me faut lui parler afin de découvrir ce qui s'est passé.",text="à la rive de la rivière à l'ouest de camp Tamrith.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=465,objective="Allez voir Darien Gautier",step="J'ai trouvé Darien. Il me faut l'informer de ce qui s'est passé dans la grotte de Reezal-Jul.",text="à la rive nord de grotte de Noirsort.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=465,objective="Allez voir Darien Gautier 1",step="J'ai trouvé Darien. Il me faut l'informer de ce qui s'est passé dans la grotte de Reezal-Jul.",text="à la rive nord de grotte de Noirsort.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=465,objective="Cherchez le capitaine Janève",step="D'après les gardes de la maison Tamrith, le capitaine Janève est parti en direction de la rivière, à l'ouest. Peut-être s'est-elle lancée sur la trace de Reezal-Jul. Il me faut la rejoindre.",text="sur le champ de bataille.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=465,objective="Cherchez le capitaine Janève",step="La comtesse Tamrith m'a demandé de l'aider à soigner les soldats blessés pendant que je les interroge au sujet de ce qui est arrivé au capitaine Janève lors de l'attaque des vampires au camp.",text="sur le champ de bataille.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=465,objective="Parlez à countess Eselde Tamrith",step="Countess Eselde Tamrith est revenue de la grotte. Je dois lui parler.",text="sur la rive de la rivière au nord de grotte de Noirsort.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=465,objective="Parlez à countess Eselde Tamrith",step="J'ai rejoint Darien et les autres à l'extérieur de la grotte. À présent, il me faut parler à Countess Eselde Tamrith.",text="sur la rive de la rivière au nord de grotte de Noirsort.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=465,objective="Parlez à countess Eselde Tamrith",step="J'ai rejoint Darien et les autres à l'extérieur de la grotte. À présent, il me faut parler à la comtesse Éselde Tamrith.",text="sur la rive de la rivière au nord de grotte de Noirsort.",source="Immersive Quests FR local : objectif et étape explicites"},
