{quest=465,objective="Parlez avec la comtesse Éselde Tamrith 4",step="J'ai rejoint Darien et les autres à l'extérieur de la grotte. À présent, il me faut parler à la comtesse Éselde Tamrith.",text="sur la rive de la rivière au nord de grotte de Noirsort.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=467,objective="Parlez au duc Nathaniel",step="J'ai dit au duc Nathaniel que j'avais tué le Présage de peur. J'ai pris ma décision concernant sieur Hugues. Il faut que je parle à nouveau au duc Nathaniel pour savoir ce qu'il en pense.",text="à propos de ses pensées sur le destin de sieur Hugues'.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=467,objective="Parlez au duc Nathaniel",step="Je vais parler au duc Nathaniel des événements du rêve de sieur Hugues.",text="à l'extérieur du rêve de sieur Hugues.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=523,objective="Parlez au maire",step="D'étranges créatures ont envahi Crêtombre et il semble que la montagne se soit en partie effondrée sur le village. Il me faut trouver le maire. Elle se réfugie peut-être dans l'une des habitations.",text="dans sa maison, au cœur de Crêtombre.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=523,objective="Parlez au maire",step="J'ai détruit l'abomination de Reezal-Jul. À présent, il me faut parler à l'esprit du maire Gette.",text="à l'intérieur de la crypte à la limite ouest de la colonie, où la paix peut prendre la place qui lui revient une fois de plus.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=575,objective="Parlez au haut-roi Émeric",step="Je devrais aller à la salle du trône parler au haut-roi Émeric.",text="à la salle du trône.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=575,objective="Parlez au haut-roi Émeric",step="Je me suis réveillé dans la chambre du roi. Je devais lui parler.",text="dans sa chambre en château d'Haltevoie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=575,objective="Parlez au haut-roi Émeric",step="Je me suis réveillée dans la chambre du roi. Je devais lui parler.",text="dans sa chambre en château d'Haltevoie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=575,objective="Parlez au haut-roi Émeric",step="Le roi Émeric est devant la guillotine, entouré de citoyens déchaînés. Si je lui parle, je réussirai peut-être à le réveiller.",text="dans son cauchemar.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=737,objective="Parlez à sieur Edmond",step="J'ai fais sonner le cor de la garnison, revendiquant ainsi le fort du Brandon pour sieur Edmond et ses chevaliers. La bataille est terminée, mais sieur Edmond a été gravement blessé au combat. Je ferais mieux d'aller le voir à l'entrée du grand hall pour savoir comment il va.",text="à l'extérieur de la grande salle sur la partie ouest de fort du Brandon.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=737,objective="Parlez à sieur Edmond",step="J'ai fait sonner le cor du grand hall du fort du Brandon. Sieur Edmond a lancé l'assaut. Je dois quitter le hall et le retrouver.",text="à l'intérieur de la Grande Salle de la fort du Brandon.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=974,objective="Parlez au duc Sébastien",step="Quand j'ai détruit les cristaux, l'enchantement qui retenait le duc s'est dissipé. À présent, le duc veut me parler.",text="au sommet du phare Métaye-la-Vieille.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=974,objective="Parlez avec le duc Sébastien",step="Quand j'ai détruit les cristaux, l'enchantement qui retenait le duc s'est dissipé. À présent, le duc veut me parler.",text="au sommet du phare Métaye-la-Vieille.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1294,objective="Trouvez le livre de sorts",step="Dithis Romori m'a dit que son frère avait emporté le livre dans une petite cour à l'est pour le lire.",text="dans la cour à côté de la guilde des Mages, juste derrière la banque d’Uveran.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=1527,objective="Parlez au milicien Charlic",step="Je dois décider si le baron Sorick doit être abandonné à la foule ou livré au garde.",text="à la périphérie Haltevoie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1527,objective="Parlez au milicien Charlic",step="Lorsque le baron Sorick s'est enfui, les paysans au rez-de-chaussée se sont emparés de lui. Il est à leur merci. Je ferais mieux d'en parler au milicien Charlic.",text="à la périphérie Haltevoie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1536,objective="Parlez à sœur Safia",step="J'ai éteint tous les feux à proximité de l'abbaye du Paria. Sœur Safia m'attend à la lisière nord-ouest des champs.",text="sur la route près des champs en feu et détruit la maison d'hôtes, au nord-ouest de l'abbaye",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1536,objective="Parlez à sœur Safia",step="Un moine m'a demandé de foncer à l'abbaye du Paria sur colline derrière lui, en me disant que je devais m'adresser à sœur Safia. Je peux peut-être l'aider, ainsi que les autres moines.",text="sur la route près des champs en feu et détruit la maison d'hôtes, au nord-ouest de l'abbaye",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1541,objective="Parlez à Durak",step="J'ai récupéré la clef de la prison de Durak. Il faut que je retourne voir Durak dans l'abbaye du Paria.",text="à la chapelle.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1541,objective="Parlez à Durak",step="Je suis entré dans le rêve de Durak. Si j'arrive à le retrouver, je lui demanderai comment faire pour le libérer.",text="à la chapelle de l'abbaye du Paria.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1541,objective="Parlez à Durak",step="Lorsque Durak a émergé de son rêve, je me suis réveillé aussi. Il m'avait demandé de lui parler une fois que nous serions tous les deux réveillés. Il souhaite m'en dire plus sur ce qui s'est passé.",text="à la chapelle de l'abbaye du Paria.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1568,objective="Rapportez le totem mâchepierre",step="Il faut que je ramène le totem tribal des Mâchepierres des gobelins dans leur caverne au nord de la vigie de Cumbrie.",text="aux tunnels au sud-ouest du campement des gobelins Mâchepierres, à l'ouest de vigie de Cumbrie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1568,objective="Rapportez le totem mâchepierre",step="Le capitaine de la garde Ernard m'a demandé de ramener le totem tribal aux gobelins mâchepierres. Il a suggéré que je m'adresse à un érudit nommé Nellic Sterone avant de rentrer dans le camp des mâchepierres.",text="au camp de gobelin à l'ouest de vigie de Cumbrie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1799,objective="Parlez à Glarikha",step="La servante de la reine a dissipé mes derniers doutes. Le duc Renchant compte livrer la ville aux Impériaux. J'ai trouvé des ordres impériaux dans ce sens à bord du Reine de la Bjoulsae. Je devrais retrouver Glarikha sur les quais.",text="probablement dans l’entrepôt près du navire, dans le port de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=1799,objective="Parlez à la reine Arzhela",step="La servante m'a demandé de rapporter mes conclusions à la reine Arzhela, à la chapelle de saint Pélin.",text="à la chapelle de saint Pélin, au sud de l’auberge et au nord de la Porte renforcée.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=1802,objective="Parlez au héraut Kixathi",step="J'ai choisi d'aider les Sourciers primordiaux à empêcher que la Néréide parvienne à ses fins. Je devrais demander au héraut Kixathi comment procéder.",text="au pied de la tour de Longueveille, en bas de l’escalier, du côté nord-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=1804,objective="Parlez à la voix d'Hermaeus Mora",step="Après avoir vaincu la Néréide, un être intimidant est apparu derrière l'autel antique. C'est une représentation du prince Daedra Hermaeus Mora. Je devrais écouter ce qu'il veut me dire.",text="au sanctuaire à l'extrême est des ruines souterraines où vous avez vaincu le Neréide, Lorélia.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1804,objective="Parlez au héraut Kixathi",step="J'ai brûlé les vivres des disciples pour causer une diversion, afin que le héraut Kixathi puisse se rendre incognito aux quartiers privés de la Néréide. Je devrais la retrouver près de la porte, au niveau supérieur de la caverne de la Néréide.",text="à côté de la porte, au niveau supérieur de la caverne de la Néréide.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=1804,objective="Parlez au héraut Kixathi",step="La Néréide affirme qu'elle a déjà créé la pierre d'eau, et l'a liée à sa propre essence. Elle dit qu'elle va se rendre à l'autel où elle inondera les ruines pour nous tuer tous. Je devrais prévenir le héraut Kixathi.",text="à l’extérieur du sanctuaire, dans l’ombre près de la porte.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=1834,objective="Parlez à la wyresse Rashan",step="Après avoir parlé aux esprits corbeaux dans le domaine de la nature, la wyresse Rashan et moi savons comment franchir les protections d'Uéla, et nous avons trouvé la porte de son repaire dans la tour de l'île. Je devrais discuter avec Rashan !",text="à l'entrée de la tour.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1834,objective="Parlez à la wyresse Rashan",step="J'ai tué la harfreuse Uéla et libéré les corbeaux qu'elle avait asservis. Maintenant, je dois rapporter son cœur à la wyresse Rashan, au pied de la tour.",text="sur la route au sud du pont de pierre qui mène au cœur de la crique des Choucas.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=1834,objective="Parlez à la wyresse Rashan",step="Les wyresses sont méfiantes, mais elles ont accepté mon aide. La wyresse Rashan devrait bientôt rentrer de sa reconnaissance au camp des Crevassais. Je dois lui annoncer que nous allons détruire les totems qui rejettent la magie du Wyrd.",text="près de la route au nord-est de oratoire du Cure-dents à trolls.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1835,objective="Détruisez l'autel de transformation",step="Le dernier spriggan se rétablit, mais bien d'autres ont trouvé la mort. Pour les venger, la wyresse Shannia m'a demandé de détruire l'autel de transformation et de tuer le sorcier qui transforme le spriggans en suturés.",text="sur une île au sud de crique des Choucas, accessible en traversant un pont terrestre.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1835,objective="Détruisez l'autel de transformation",step="Pour venger tous les spriggans qui sont morts, la wyresse Shannia m'a demandé de détruire l'autel de transformation et de tuer le sorcier qui transformait les spriggans en suturés.",text="sur une île au sud de crique des Choucas, accessible en traversant un pont terrestre.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1835,objective="Parlez à la wyresse Shannia",step="Il ne reste qu'un seul spriggan dans la région, et la wyresse Shannia dit qu'elle est empoisonnée, et va se transformer en suturé si l'on ne fait rien.",text="dans les ruines du lac, au sud-est de la crique des Choucas.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=1835,objective="Parlez à la wyresse Shannia",step="J'ai appliqué le cataplasme de duramen pur et le dernier spriggan semble se remettre. Je devrais demander à la wyresse Shannia si je peux faire autre chose.",text="dans les ruines du sud-est crique des Choucas.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=1835,objective="Parlez à la wyresse Shannia",step="J'ai détruit l'autel de transformation et vaincu le sorcier responsable de l'apparition des suturés. Je dois rejoindre la wyresse Shannia et la prévenir.",text="dans les ruines du lac, au sud-est de la crique des Choucas.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2017,objective="Parlez à Ufa la vipère rouge",step="Dhakir m'a expliqué que les Impériaux comptent exécuter la grandéya de la Gloire d'Hallin, et m'a donné une clef qui pourrait ouvrir ses fers. Lorsque j'ai apporté cette clef à Yarah, Ufa est apparu. Je devrais lui parler.",text="à l'extérieur sur le balcon inférieur de Sublime élixir.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2018,objective="Parlez à Ufa la vipère rouge",step="J'ai allumé les tours de garde, et les habitants de la Gloire d'Hallin sont à présent prêts. Ufa aussi est là. Je devrais lui demander comment il compte procéder.",text="au sommet de l'escalier près de l'entrée de palais de la Grandéya.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2047,objective="Parlez au maître Muzgu",step="L'esprit Daedrique est vaincu. La menace est endiguée.\n\nJe dois parler à Muzgu pour savoir ce qu'il faut faire à présent.",text="à la grotte en gouffre lunaire.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2047,objective="Parlez au maître Muzgu",step="Le cultiste est piégé dans le cercle rituel. Muzgu pourra m'indiquer ce que je dois faire ensuite.",text="sur ce qu'il faut faire ensuite.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2068,objective="Parlez au sergent Stégine",step="J'ai rapporté les œufs de dreughs dans leurs nids et tué les créatures ayant envahi Flanc-dreugh. Cela devrait dissuader leurs congénères de lancer une autre attaque. Le sergent Stégine est toujours à son poste. Je devrais aller l'informer de la réussite de ma mission.",text="sur la route principale qui part de Flanc-dreugh vers l’ouest, juste à l’extérieur des remparts de Haltevoie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2068,objective="Parlez au sergent Stégine",step="Un garde paniqué de Haltevoie m'a informé que le sergent Stégine se trouve à Flanc-dreugh où il défend les citoyens contre une attaque de dreughs.",text="à l'extérieur de la maison d'Arbogasque dans le Dreughre, un fermier juste à l'extérieur des murs nord-ouest de Haltevoie en Havre-tempête.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2068,objective="Parlez au sergent Stégine",step="Un garde paniqué de Haltevoie m'a informée que le sergent Stégine se trouve à Flanc-dreugh où il défend les citoyens contre une attaque de dreughs.",text="à l'extérieur de la maison d'Arbogasque dans le Dreughre, un fermier juste à l'extérieur des murs nord-ouest de Haltevoie en Havre-tempête.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2146,objective="Parlez au roi Fahara'jad",step="J'ai vaincu la Main de Gloire dans l'armurerie, mais certains de ses agents ont pris l'escampe avec les parades des Anseïs. Je dois en informer le roi.",text="à l’entrée de la cave, à l’est du palais de Sentinelle.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2222,objective="Parlez à l'Anseï Maja",step="En reforgeant la lame de la parade, j'ai restauré le pouvoir de l'Anseï Maja, lui permettant ainsi de vaincre l'esprit malin qu'Alasan était devenu. À présent, je dois parler à l'Anseï Maja.",text="dans son sanctuaire au centre de la ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2222,objective="Parlez à l'Anseï Maja",step="J'ai détruit la parade et interrompu le rituel d'Alasan. L'Anseï Maja est apparue. Je devrais lui parler.",text="au sommet du phare dans la ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2222,objective="Parlez au prince Azah",step="En reforgeant la lame de la parade, j'ai restauré le pouvoir de l'Anseï Maja, lui permettant ainsi de vaincre l'esprit malin qu'Alasan était devenu. À présent, je dois remettre la parade réparée au prince Azah pour qu'il la mette en lieu sûr.",text="dans le sud-ouest de la ville, à côté du navire en construction.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2222,objective="Parlez au prince Azah",step="En reforgeant la lame de la parade, j'ai restauré le pouvoir de l'Anseï Maja, lui permettant ainsi de vaincre l'esprit malin qu'Alasan était devenu. J'ai confié la parade de l'Anseï réparée au prince Azah pour qu'il la mette en lieu sûr. À présent, je dois à nouveau parler au prince.",text="dans le sud-ouest de la ville, à côté du navire en construction.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2251,objective="Parlez au juge Istah",step="J'ai trouvé un message dans la maison du bailli Fakimal attestant sa culpabilité dans les meurtres des disparus. Le message suggère également qu'il agissait sur les ordres d'un supérieur. Je dois retourner voir le juge Istah.",text="au centre-ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2251,objective="Parlez au juge Istah",step="J'ai trouvé un message dans la maison du bailli Fakimal prouvant qu'il a tué les disparus sur les ordres d'un supérieur. Le juge Istah a été mis au pilori. Je dois lui parler.",text="dans les stocks au centre-ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2251,objective="Parlez au juge Istah",step="Le juge Istah m'attend devant la salle du Jugement. Il souhaite s'entretenir avec moi.",text="devant la salle du Jugement.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2364,objective="Parlez à Léja at-Lehiel",step="J'ai trouvé Léja at-Lehiel dans un nid de harpie, à quelque distance de Kozanset. Je devrais lui parler pour m'assurer qu'elle va bien.",text="dans la grotte non marquée à l'est de Kozanset.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2364,objective="Parlez à léja at-Lehiel",step="Je suis entré dans la maison de Léja at-Lehiel. Elle m'a demandé de l'y retrouver pour discuter en privé de l'affaire des harpies qui sévissent en ville.",text="dans sa maison.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2364,objective="Parlez à Léja at-Lehiel",step="Je suis entrée dans la maison de Léja at-Lehiel. Elle m'a demandé de l'y retrouver pour discuter en privé de l'affaire des harpies qui sévissent en ville.",text="dans sa maison.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2364,objective="Parlez à Léja at-Lehiel",step="La femme en question est la fille du magistrat, Léja at-Lehiel. Elle affirme que les mercenaires de la Côte d'or escroquent les villageois et aggravent peut-être le problème des harpies. Elle m'a demandé de l'aider.",text="dans sa maison.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2364,objective="Parlez à léja at-Lehiel 1",step="J'ai trouvé Léja at-Lehiel dans un nid de harpie, à quelque distance de Kozanset. Je devrais lui parler pour m'assurer qu'elle va bien.",text="dans la grotte non marquée à l'est de Kozanset.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2364,objective="Parlez à Léja at-Lehiel 2",step="Léja at-Lehiel est arrivée sur le balcon du poste de garde, et elle semble se réjouir que les harpies aient oublié leurs griefs à l'encontre de la ville. Je devrais lui demander comment elle envisage l'avenir de Kozanset.",text="sur le balcon de la maison à l'ouest de la guilde des guerriers.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2364,objective="Parlez au magistrat Andrin at-Lehiel",step="À mon arrivée à son domicile, Léja at-Lehiel était absente et son père m'attendais de pied ferme. Je devrais lui parler pour savoir ce qui se passe.",text="à Leja chez Lehiel.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2364,objective="Parlez au magistrat Andrin at-Lehiel",step="En entrant dans l'hôtel de ville, j'ai interrompu un vif échange entre une certaine Daneem et le magistrat Andrin at-Lehiel.\r\n\r\nJe devrais lui demander de quoi il retourne.",text="à l'intérieur du hôtel de ville, voisin Auberge de l'eau douce.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2364,objective="Parlez au magistrat Andrin at-Lehiel 1",step="À mon arrivée à son domicile, Léja at-Lehiel était absente et son père m'attendais de pied ferme. Je devrais lui parler pour savoir ce qui se passe.",text="à Leja chez Lehiel.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2364,objective="Parlez avec le magistrat Andrin at-Lehiel",step="À mon arrivée à son domicile, Léja at-Lehiel était absente et son père m'attendais de pied ferme. Je devrais lui parler pour savoir ce qui se passe.",text="à Leja chez Lehiel.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2364,objective="Parlez avec le magistrat Andrin at-Lehiel",step="En entrant dans l'hôtel de ville, j'ai interrompu un vif échange entre une certaine Daneem et le magistrat Andrin at-Lehiel.\n\nJe devrais lui demander de quoi il retourne.",text="à l'intérieur du hôtel de ville, voisin Auberge de l'eau douce.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2364,objective="Parlez avec le magistrat Andrin at-Lehiel 1",step="À mon arrivée à son domicile, Léja at-Lehiel était absente et son père m'attendais de pied ferme. Je devrais lui parler pour savoir ce qui se passe.",text="à Leja chez Lehiel.",source="Immersive Quests FR local : objectif et étape explicites"},
