{quest=2364,objective="Parlez avec Léja at-Lehiel 2",step="Léja at-Lehiel est arrivée sur le balcon du poste de garde, et elle semble se réjouir que les harpies aient oublié leurs griefs à l'encontre de la ville. Je devrais lui demander comment elle envisage l'avenir de Kozanset.",text="sur le balcon de la maison à l'ouest de la guilde des guerriers.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2450,objective="Parlez à Miranda",step="J'ai donné le remède. Je dois parler à Miranda.",text="à l'intérieur du manoir en plateau de Farangel.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2481,objective="Parlez à S'rashi",step="Je dois parler à S'rashi au sujet de la dette du capitaine.",text="à son bureau à l'étage de l’auberge de la Lie embrumée.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2537,objective="Parlez au roi Aphren",step="La princesse Mira a compris l'importance de recevoir l'épée de son père. Elle est venue lui parler pour la première fois depuis des siècles. Je dois parler à l'esprit du roi pour lui faire mes adieux.",text="à sa crypte en tombe d'Aphren à l'extrémité ouest d'Aphren cale.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2556,objective="Parlez au milicien Pascal",step="J'ai trouvé le manifeste du bateau, le Bonté de Tava. Je pourrais le donner au milicien Pascal pour prouver les déclarations du capitaine. Il entendra peut-être raison, à présent.",text="à l'extérieur des docks de village de Koeglin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2556,objective="Parlez au milicien Pascal",step="Je dois retourner au milicien Pascal à l'ouest des quais. Comme il a parlé avec le messager Cordier, il devrait se rendre compte que dame Dabienne n'est pas de mèche avec les esclavagistes.",text="à l'ouest de l'entrepôt du dock en village de Koeglin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2556,objective="Parlez avec le milicien Pascal",step="J'ai trouvé le manifeste du bateau, le Bonté de Tava. Je pourrais le donner au milicien Pascal pour prouver les déclarations du capitaine. Il entendra peut-être raison, à présent.",text="à l'extérieur des docks de village de Koeglin.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2556,objective="Parlez avec le milicien Pascal",step="Je dois retourner au milicien Pascal à l'ouest des quais. Comme il a parlé avec le messager Cordier, il devrait se rendre compte que dame Dabienne n'est pas de mèche avec les esclavagistes.",text="à l'ouest de l'entrepôt du dock en village de Koeglin.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=2561,objective="Parlez à Ganise",step="Guillaume et Ganise sont revenus à la ferme. Je dois leur parler.",text="à la ferme des Nurin, avec son père.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2561,objective="Parlez à Ganise",step="Je dois dire à Ganise que sa mère Rosalie lui donne rendez-vous chez elles. Ganise cherche parmi les décombres, dans la maison située à l'extrême ouest de la ferme des Nurin.",text="dans les décombres de la maison située à l’extrême ouest de la ferme des Nurin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2998,objective="Parlez au roi Fahara'jad",step="Je dois parler au roi Fahara'jad dans l'armurerie hermétique.",text="dans l’armurerie hermétique. L’entrée des cryptes est à l’est du palais, du côté sud-est de Sentinelle.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=2998,objective="Parlez au roi Fahara'jad",step="Le roi Fahara'jad a prononcé un éloquent discours afin de me remercier d'avoir restitué les parades des Anseïs. Je devrais lui parler pour savoir si je peux faire autre chose pour lui.",text="dans les caveaux étanches.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3000,objective="Parlez au capitaine Arésin",step="On cherche à assassiner le roi Casimir ! Les cerveaux du complot se font appeler Verrik et Angof. Verrik se cache dans le port, et s'apprête à frapper. Je dois apporter ces renseignements au capitaine Arésin au plus vite.",text="à la base des escaliers menant à château de Daguefilante.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3006,objective="Parlez au roi Casimir",step="Verrik est mort et le roi Casimir ne risque plus rien. Je devrais parler au roi Casimir.",text="à l’étage du château de Daguefilante.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3009,objective="Parlez à la wyresse Hélène",step="Bernard Rédain et sa famille se sont échappés de la scierie. Il m'a suggéré de parler aux sœurs du Wyrd pour les aider.",text="au sud-ouest du moulin à scierie de Deleyn, situé à l'est de Daguefilante.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3009,objective="Parlez à la wyresse Hélène",step="J'ai rassemblé ce que voulait la wyresse. Hélène dois protéger les villageois. Je devrais le lui dire.",text="à l’extérieur du moulin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3018,objective="Parlez à Gloria Fausta",step="Le duc de Camlorn est mort. Je n'ai pas eu le choix, il s'est transformé en loup-garou. Je devrais discuter de la mort du duc avec Gloria Fausta.",text="à l'extérieur de la résidence du duc en Métaye-la-Vieille.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3018,objective="Parlez à Gloria Fausta",step="Le loup-garou nous a appris que le duc de Camlorn a été capturé et transformé en loup-garou. Je devrais en discuter avec Gloria.",text="dans la grotte au nord-est des quais de Métaye-la-Vieille.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3018,objective="Parlez à Gloria Fausta",step="Le rituel a révélé le rôle d'Angof dans la résurrection de Falorch. Je devrais parler de ce que nous avons vu à Gloria Fausta.",text="dans la grotte au nord-est des quais de Métaye-la-Vieille.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3018,objective="Parlez à gloria Fausta 1",step="Le duc de Camlorn est mort. Je n'ai pas eu le choix, il s'est transformé en loup-garou. Je devrais discuter de la mort du duc avec Gloria Fausta.",text="à l'extérieur de la résidence du duc en Métaye-la-Vieille.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3018,objective="Parlez au duc Sébastien",step="Nous ne pouvons pas laisser Gloria se sacrifier pour sauver le duc. Je devrais retourner à Métaye-la-Vieille et affronter le duc avant qu'il se transforme en loup-garou.",text="devant sa résidence.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3018,objective="Parlez avec Gloria Fausta",step="Le duc de Camlorn est mort. Je n'ai pas eu le choix, il s'est transformé en loup-garou. Je devrais discuter de la mort du duc avec Gloria Fausta.",text="à l'extérieur de la résidence du duc en Métaye-la-Vieille.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3018,objective="Parlez avec Gloria Fausta",step="Le loup-garou nous a appris que le duc de Camlorn a été capturé et transformé en loup-garou. Je devrais en discuter avec Gloria.",text="dans la grotte au nord-est des quais de Métaye-la-Vieille.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3018,objective="Parlez avec Gloria Fausta",step="Le rituel a révélé le rôle d'Angof dans la résurrection de Falorch. Je devrais parler de ce que nous avons vu à Gloria Fausta.",text="dans la grotte au nord-est des quais de Métaye-la-Vieille.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3018,objective="Parlez avec Gloria Fausta 1",step="Le duc de Camlorn est mort. Je n'ai pas eu le choix, il s'est transformé en loup-garou. Je devrais discuter de la mort du duc avec Gloria Fausta.",text="à l'extérieur de la résidence du duc en Métaye-la-Vieille.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3018,objective="Parlez avec le duc Sébastien",step="Nous ne pouvons pas laisser Gloria se sacrifier pour sauver le duc. Je devrais retourner à Métaye-la-Vieille et affronter le duc avant qu'il se transforme en loup-garou.",text="devant sa résidence.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3019,objective="Parlez à Léon Milielle",step="J'ai assisté aux événements qui ont amené Léon à trahir Ouestrie. Léon a renoncé à Stendarr et a vendu son âme à Molag Bal sous les yeux de Rosalinde. Je devrais en parler à Léon.",text="dans sa maison au sud du cimetière de la ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3019,objective="Parlez à Léon Milielle",step="Léon Milielle suppose que je pourrais lever la malédiction en revivant les derniers moments de son épouse. Je devrais lui demander comment faire.",text="près de la route, au nord du lac.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3020,objective="Parlez à Léon Milielle",step="Léon et Rosalinde sont chez eux. Je devrais parler à Léon et lui dire ce que j'ai fait.",text="dans leur maison au sud du cimetière.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3020,objective="Retournez chez Léon et Rosalinde",step="J'ai libérer les esprits innocents de Ouestrie. Je devrais retournez chez Léon et Rosalinde, comme elle me l'avait demandé.",text="dans la grande maison au sud du cimetière.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3020,objective="Retournez chez Léon et Rosalinde",step="J'ai utilisé l'épée de Rosalinde pour vaincre les spectres de Ouestrie. Je devrais retourner chez Léon et Rosalinde, comme elle me l'a demandé.",text="dans la grande maison au sud du cimetière.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3035,objective="Parlez à Sibellec",step="Guy m'a conseillé de contacter la sorcière crevassaise Sibellec. Elle loge avec les wyresses au nord. Elle connaît peut-être un moyen d'arrêter Mère Ténèbres.",text="au camp au nord-ouest de l’oratoire du marais aux harfreuses.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3035,objective="Parlez à Sibellec",step="J'ai vaincu Mère Ténèbres. Je devrais retourner à l'enclave des wyresses au nord pour prévenir Sibellec.",text="au camp au nord-ouest de l’oratoire du marais aux harfreuses.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3049,objective="Parlez à Grahla",step="Je dois m'entretenir avec Grahla au plus vite pour lui faire part du point faible de Faolchu.",text="au camp à l’entrée du chemin des landes de Glénumbrie.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3049,objective="Retournez dans le présent",step="Le feu a fonctionné et Faolchu a été éliminé. L'esprit du chevalier dont j'ai pris la place m'est apparu et m'a dit d'emprunter le portail voisin afin de regagner le présent.",text="près du portail dans le repaire de Faolchu.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3049,objective="Retournez dans le présent",step="Le feu était la solution et Faolchu a été éliminé. L'esprit du chevalier dont j'ai pris la place m'est apparu et m'a dit d'emprunter le portail voisin afin de regagner le présent.",text="près du portail dans le repaire de Faolchu.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3064,objective="Parlez au général Gautier",step="J'ai fermé le portail principal de Camlorn. Je devrais annoncer au général Gautier que j'ai réussi.",text="dans la cour du sud de la ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3082,objective="Parlez à Gabrielle Bénèle",step="J'entends des cris dans la crypte. C'est probablement la mage Bénèle. Je devrais aller lui parler à l'intérieur.",text="à l’intérieur de la crypte.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3172,objective="Parlez à l’oncle Thakh gro-Ram",step="À en croire Casnar, le père de Tiéla aurait engagé des brigands prêts à lui broyer les rotules si jamais il ose se présenter devant l'autel. Je devrais parler au chef des brigands, l’oncle Thakh gro-Ram, et le convaincre de laisser Casnar se marier.",text="au casino local, le Chacal insolent, situé au nord-est de la ville, à l'est du lieu de mariage.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3172,objective="Parlez à l’oncle Thakh gro-Ram",step="Je devrais parler à nouveau à l’oncle Thakh gro-Ram. Peut-être sera-t-il plus enclin à m'écouter, à présent.",text="au casino local, le Chacal insolent, situé au nord-est de la ville, à l'est du lieu de mariage.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3172,objective="Parlez avec l'oncle Thakh gro-Ram",step="À en croire Casnar, le père de Tiéla aurait engagé des brigands prêts à lui broyer les rotules si jamais il ose se présenter devant l'autel. Je devrais parler au chef des brigands, l'oncle Thakh gro-Ram, et le convaincre de laisser Casnar se marier.",text="au casino local, le Chacal insolent, situé au nord-est de la ville, à l'est du lieu de mariage.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3172,objective="Parlez avec l'oncle Thakh gro-Ram",step="Je devrais parler à nouveau à l'oncle Thakh gro-Ram. Peut-être sera-t-il plus enclin à m'écouter, à présent.",text="au casino local, le Chacal insolent, situé au nord-est de la ville, à l'est du lieu de mariage.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3174,objective="Parlez à Darien",step="J'ai allumé le signal. Maintenant, je devrais descendre parler à Darien.",text="dans l'auberge à l'ouest de la fontaine centrale de la ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3174,objective="Parlez à Darien",step="J'ai récupéré des armes et des armures pour permettre aux habitants de se défendre. Je dois retrouver Darien pour que nous puissions enfin ouvrir les portes aux soldats de la garde du lion.",text="dans l'auberge à l'ouest de la fontaine centrale de la ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3191,objective="Parlez à la wyresse Gwen",step="J'ai ouvert un portail pour la wyresse Gwen. Je devrais lui demander si je peux encore me rendre utile pour sauver l'arbre du Wyrd.",text="à l'entrée du Wyrd Tree.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3191,objective="Parlez avec la wyresse Gwen",step="J'ai ouvert un portail pour la wyresse Gwen. Je devrais lui demander si je peux encore me rendre utile pour sauver l'arbre du Wyrd.",text="à l'entrée du Wyrd Tree.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3267,objective="Parlez à Darien Gautier",step="Maintenant que Faolchu est mort et que la garde du lion est dans Camlorn, je n'ai plus grand-chose à faire ici. Je devrais parler au capitaine Gautier avant de partir.",text="près de la fontaine centrale de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3277,objective="Parlez à Gabrielle Bénèle",step="Gabrielle et moi sommes arrivés sur l'ancien site du Wyrd. Je devrais parler à Gabrielle quand je serai prêt à commencer le rituel.",text="sur le site de wyrd sur une plage au nord au nord-ouest de Merovel's Folly.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3277,objective="Parlez à Gabrielle Bénèle",step="Gabrielle et moi sommes arrivés sur l'ancien site du Wyrd. Je devrais parler à Gabrielle quand je serai prête à commencer le rituel.",text="sur le site de wyrd sur une plage au nord au nord-ouest de Merovel's Folly.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3277,objective="Parlez à Gabrielle Bénèle",step="Gabrielle m'a suivi jusqu'au cercle du Wyrd. Maintenant que le talisman est purgé, je devrais lui parler.",text="au milieu du cercle de wyrd au nord de folie de Mérovec.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3277,objective="Parlez à Gabrielle Bénèle",step="Gabrielle m'a suivie jusqu'au cercle du Wyrd. Maintenant que le talisman est purgé, je devrais lui parler.",text="au milieu du cercle de wyrd au nord de folie de Mérovec.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3277,objective="Parlez à Gabrielle Bénèle",step="Quelque chose d'anormal a dû se produire pendant le rituel. Je devrais parler à Gabrielle.",text="sur le site de wyrd sur une plage au nord au nord-ouest de Merovel's Folly.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3280,objective="Parlez à la reine Arzhela",step="Le duc Renchant soutient qu'il a eu raison de remettre la ville aux Impériaux. J'ai décidé qu'il fallait mettre Renchant au pilori. Je devrais retrouver la reine Arzhela dehors.",text="près du puits au bas des escaliers du château, dans la partie sud-est de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3280,objective="Parlez à la reine Arzhela",step="Le duc Renchant soutient qu'il a eu raison de remettre la ville aux Impériaux, mais j'ai décidé que sa trahison était passible de mort. Je devrais retrouver la reine à l'extérieur.",text="près du puits au bas des escaliers du château, dans la partie sud-est de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3280,objective="Parlez à la reine Arzhela",step="Le duc Renchant soutient qu'il a eu raison de remettre la ville aux Impériaux, mais la reine l'a exécuté pour ses crimes. Je devrais la retrouver devant le donjon.",text="près du puits au bas des escaliers du château, dans la partie sud-est de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3280,objective="Retrouvez la reine au dehors",step="Le duc Renchant soutient qu'il a eu raison de remettre la ville aux Impériaux. J'ai décidé qu'il fallait mettre Renchant au pilori. Je devrais retrouver la reine Arzhela dehors.",text="près du puits au bas des escaliers du château, dans la partie sud-est de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3280,objective="Retrouvez la reine au dehors",step="Le duc Renchant soutient qu'il a eu raison de remettre la ville aux Impériaux, mais j'ai décidé que sa trahison était passible de mort.",text="près du puits au bas des escaliers du château, dans la partie sud-est de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3280,objective="Retrouvez la reine au dehors",step="Le duc Renchant soutient qu'il a eu raison de remettre la ville aux Impériaux, mais la reine l'a exécuté pour ses crimes. Je devrais la retrouver devant le donjon.",text="près du puits au bas des escaliers du château, dans la partie sud-est de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3285,objective="Parlez au sénéchal oublié",step="Le rituel du sénéchal oublié est terminé et le caveau des rois perdus est ouvert. Je devrais parler au sénéchal vers l'entrée du caveau.",text="à l'entrée de la crypte des rois perdus.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3286,objective="Parlez à Héloïse Menoit",step="Les Hinault se sont barricadés dans la ferme familiale. Ils refusent d'ouvrir la porte tant que je ne leur aurai pas procuré des armes pour se défendre. Héloïse semble avoir une idée. Je devrais lui parler.",text="au bas des escaliers menant à la maison Hinault.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3286,objective="Parlez au lieutenant Fairfax",step="J'ai rassemblé les fournitures de soin. À présent, il me faut les apporter au lieutenant Fairfax, à la vieille tour.",text="à l'extérieur de la tour, au bas de l'escalier menant à l'entrée.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3286,objective="Parlez au lieutenant Fairfax",step="J'ai sauvé tous les membres de la famille Hinault que je pouvais, et éliminé ceux qui s'étaient transformés en sangrebêtes. Il me faut à présent regagner la tour afin de m'entretenir avec le lieutenant Fairfax.",text="à la tour.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3286,objective="Parlez avec Héloïse Menoit",step="Les Hinault se sont barricadés dans la ferme familiale. Ils refusent d'ouvrir la porte tant que je ne leur aurai pas procuré des armes pour se défendre. Héloïse semble avoir une idée. Je devrais lui parler.",text="au bas des escaliers menant à la maison Hinault.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3303,objective="Parlez à dame Laurent",step="J'ai actionné le levier ouvrant la chambre du portail. Je dois rejoindre dame Laurent à l'intérieur pour commencer le rituel permettant de fermer le portail.",text="dans les ruines inférieures, la porte de la chambre du portail est juste à côté des escaliers d'entrée.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3303,objective="Parlez à dame Laurent",step="Je dois retrouver dame Laurent dans les ruines inférieures.",text="dans les ruines inférieures. Leur porte est à l’ouest du cristal situé au milieu des ruines.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3303,objective="Parlez à dame Laurent",step="Le portail s'est refermé et les troupes aldmeri ne devraient plus poser problème. Je dois parler à dame Laurent et m'assurer que ma mission ici est terminée.",text="dans les ruines inférieures, la porte de la chambre du portail est juste à côté des escaliers d'entrée.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3317,objective="Parlez à dame Laurent",step="À présent que dame Laurent a récupéré ses notes, je devrais lui demander comment elle compte dé-pétrifier son assistant.",text="à côté de l'incendie de son campement d'origine en ruine.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3317,objective="Parlez à dame Laurent",step="Dame Laurent a tous les ingrédients dont elle a besoin pour l'antidote à la pétrification des chairs. Je devrais aller voir s'il lui faut autre chose pour le préparer.",text="dans son camp.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3317,objective="Parlez à dame Laurent",step="J'ai mené dame Laurent à son campement de fouilles, et trouvé son assistant « perdu ». Il a été changé en pierre. Je devrais demander des explications à dame Laurent.",text="près du feu dans son camp d'origine.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3317,objective="Parlez à dame Laurent",step="L'antidote a fonctionné, et son assistant Stibbons est redevenu humain. Je devrais parler à dame Laurent et voir ce qu'elle compte faire à présent.",text="près de Stibbons, à côté du feu de camp.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3335,objective="Parlez à Théo",step="Maintenant que j'ai fini d'inspecter la maison de Médya Zurric, je devrais discuter avec l'écuyer Théo Rocque.",text="à la maison de Medya zurcric.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3335,objective="Parlez à Théo",step="Médya Zurric a été exécutée pour ses actes. Je devrais parler à l'écuyer Théo pour découvrir ce qui va se passer au hameau de Murcien.",text="à la maison de Medya.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3335,objective="Parlez à Théo",step="Médya Zurric sera jugée à Abondance pour ses actes. Je devrais demander à l'écuyer Théo ce qu'il va advenir du hameau de Murcien.",text="à la maison de Medya.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3353,objective="Parlez à Anjan",step="Pour démontrer la véracité de ses croyances, Anjan a lancé des osselets dans le sable et prédit que je sortirais vainqueur d'une course contre la tempête. Je dois courir à travers le désert en suivant le sillage de flammes bleues pour arriver au bout avant les éléments déchaînés.",text="derrière une petite maison, située à l'est du champs des capte-pluie ou au sud-ouest de Alezer Kotu.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3383,objective="Parlez à Samsi",step="L'esprit d'Haidar a laissé éclater sa colère quand je lui ai refusé mon aide, mais j'ai décidé de ne pas remettre les gemmes maudites à Samsi. Je lui rapporte juste le paquetage, comme convenu.",text="à l’extérieur de la mine en ruine.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3414,objective="Parlez à Claudie Thémond",step="Athel Bael est mort. Je devrais parler à Claudie.",text="au bord de la falaise surplombant le val des gardiennes.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3414,objective="Parlez à Claudie Thémond",step="Le fantôme de Claudie est apparu non loin. Je devrais lui parler.",text="au cimetière derrière la cathédrale de Daguefilante.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3416,objective="Parlez au capitaine Gilame",step="J'ai éteint les feux au sommet de la Tour de Longueveille. Je devrais trouver le capitaine Gilame au pied de la tour pour savoir s'ils ont pu repousser l'attaque du Domaine.",text="près de la tour de Longueveille, juste à l’ouest du camp du Domaine.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3437,objective="Parlez au fantôme ayléide",step="J'ai convaincu l'esprit ayléide d'aller explorer le Tamriel moderne. Il pourra ainsi voir ce qu'est devenue la Glénumbrie après la défaite des Alessiens. Je devrais lui parler une dernière fois et veiller à ce qu'il se mette en route.",text="dans la première cellule à gauche, à l’intérieur du donjon de Drèsan.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3437,objective="Parlez au fantôme ayléide",step="J'ai détruit les artefacts qui entravaient l'esprit ayléide. Je devrais retourner lui dire que j'ai réussi.",text="dans la première cellule à gauche, à l’intérieur du donjon de Drèsan.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3437,objective="Parlez au fantôme ayléide",step="J'ai trouvé un pendentif en forme de langue d'or. Il s'est désintégré dès que je l'ai touché, mais j'ai eu le temps d'entendre des chuchotements magiques tout autour de moi. Je devrais retourner auprès du fantôme et voir si je peux enfin communiquer avec lui.",text="dans la première cellule à gauche, à l’intérieur du donjon de Drèsan.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3437,objective="Parlez au fantôme ayléide",step="Un fantôme est apparu lorsque j'ai ouvert ce coffre antique. Je devrais parler à cet esprit et voir ce qu'il veut.",text="à l'intérieur de la première cellule à gauche de donjon de Drèsan.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3438,objective="Parlez à Herminius Sophus",step="Bien que l'épée soit maudite, j'ai décidé de la remettre à Herminius Sophus pour qu'il l'emporte à Cyrodiil.",text="au camp au sud d'un naufrage.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3438,objective="Parlez à Herminius Sophus",step="J'ai décidé de donner l'épée maudite au chante-épée Navid. Je vais devoir m'en expliquer auprès d'Herminius Sophus.",text="au camp au sud d'un naufrage.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3438,objective="Parlez avec Herminius Sophus",step="Bien que l'épée soit maudite, j'ai décidé de la remettre à Herminius Sophus pour qu'il l'emporte à Cyrodiil.",text="au camp au sud d'un naufrage.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3438,objective="Parlez avec Herminius Sophus",step="J'ai décidé de donner l'épée maudite au chante-épée Navid. Je vais devoir m'en expliquer auprès d'Herminius Sophus.",text="au camp au sud d'un naufrage.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3496,objective="Parlez à Mazrahil le Scarabée Rusé",step="J'ai récupéré quelques documents sur les soldats impériaux. Je devrais retrouver Mazrahil le Scarabée Rusé dans les ruines sous la porte de Raidelorn.",text="à la porte jusqu'à Raidelorn à l'est de vieille Tour.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3496,objective="Parlez avec Mazrahil le Scarabée Rusé",step="J'ai récupéré quelques documents sur les soldats impériaux. Je devrais retrouver Mazrahil le Scarabée Rusé dans les ruines sous la porte de Raidelorn.",text="à la porte jusqu'à Raidelorn à l'est de vieille Tour.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3533,objective="Parlez à dame Valyrie",step="À présent que les mausolées sont purifiés, je devrais retourner à l'église et parlez à dame Valyrie pour voir si cela a eu le moindre effet sur le prince.",text="à l'église, à l'ouest du cimetière principal.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3533,objective="Parlez à dame Valyrie",step="Le prince est mort et a retrouvé le repos. Je devrais demander à dame Valyrie et découvrir ce qu'elle compte faire à présent.",text="à l'intérieur de l'église sur le côté ouest du cimetière.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3533,objective="Parlez à dame Valyrie",step="Le prince est mort, il a été déposé dans la crypte. Je devrais parler à dame Valyrie, pour voir ce qu'elle compte faire à présent.",text="à l'intérieur de l'église sur le côté ouest du cimetière.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3533,objective="Parlez à dame Valyrie",step="Le prince ressuscité m'a demandé de parler au dernier chevalier resté avec lui, dame Valyrie. Il veut que je lui répète ce qu'a dit la voix dans la crypte.",text="à quelques pas de l’autel, au milieu du cimetière.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3533,objective="Parlez à dame Valyrie",step="On dirait que le père Quiston doute de la résurrection « sacrée » du prince. Je devrais parler avec dame Valyrie pour savoir ce qui s'est passé.",text="à l'église, à l'ouest du cimetière principal.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3533,objective="Parlez à dame Valyrie",step="Pendant que je noyais les flammes bleues sous l'eau bénie, dame Valyrie semble avoir trouvé un prêtre. Je devrais lui demander ce qu'il a dit.",text="dans la partie sud-ouest du cimetière, en haut d'une petite colline, à un immense monument avec deux statues tenant des épées.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3533,objective="Parlez au prince Adrien",step="J'ai détruit l'esprit maléfique qui a possédé le prince Adrien. Je devrais parler au prince pour savoir s'il se sent mieux.",text="à l'intérieur de l'église sur le côté ouest du cimetière.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3533,objective="Parlez au prince Adrien",step="Le prince revenu d'entre les morts est à genoux devant l'autel, et semble avoir été possédé par l'esprit maléfique qui m'a parlé précédemment. Je devrais demander au prince ce que je peux faire.",text="à l'intérieur de l'église sur le côté ouest du cimetière.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3533,objective="Parlez au prince Adrien",step="Le prince semble avoir été ressuscité. Le chevalier qui protégeait sa dépouille affirme que c'est un miracle. Je devrais parler avec le prince.",text="au milieu du cimetière de Pélin, près du vieil autel de pierre.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3533,objective="Parlez au prince Adrien",step="Une voix dans la crypte royale m'a dit que le prince avait été ressuscité par Arkay en personne, afin qu'il puisse mener une armée de morts-vivants contre ses ennemis. Je devrais rapporter ce message au prince.",text="à l'extérieur de la crypte royale, qui est nichée au milieu du cimetière, derrière l'autel.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3590,objective="Parlez à Furon Rii",step="J'ai lié un des soldats morts. Je dois mener l'esprit du soldat à Furon Rii.",text="au camp situé au nord des Plaines affamées.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3590,objective="Parlez à Furon Rii",step="Nous avons effectué le rituel et confronté général Radrathren. Je devrais retourner parler à Furon Rii.",text="sur la plate-forme des ruines daedriques, au centre des Plaines affamées.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3590,objective="Parlez à Furon Rii",step="Nous avons effectué le rituel et confronté le général Radrathren. Je devrais retourner parler à Furon Rii.",text="sur la plate-forme des ruines de Daedric au centre du Plaines affamées.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3590,objective="Parlez à furon Rii 1",step="Nous avons effectué le rituel et confronté le général Radrathren. Je devrais retourner parler à Furon Rii.",text="sur la plate-forme des ruines de Daedric au centre du Plaines affamées.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3590,objective="Parlez à Reesa",step="J'ai décidé d'aider l'armée spectrale à passer dans Ætherius. Je dois demander quoi faire à Reesa.",text="au camp situé au nord des Plaines affamées.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3590,objective="Parlez à Reesa",step="J'ai tenté le plan proposé par les frères Rii. Une Argonienne nommée Reesa a tenté d'attirer mon attention pendant que je me séparais de Furon. Je devrais l'écouter.",text="au camp situé au nord des Plaines affamées.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3590,objective="Parlez à Reesa",step="Je dois informer Reesa que le talisman argonien a pu libérer un esprit.",text="au camp nord du Plaines affamées.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
