{quest=3600,objective="Parlez à Svanhildr",step="J'ai incendié toutes les huttes à provisions des Orques. Il me faut retrouver Svanhildr près de la grande porte et l'en informer.",text="près de la grande porte du côté sud de gouffre de Malak.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3616,objective="Parlez à Mavos",step="J'ai invoqué les gardiens, comme le magistère Enuse me l'a demandé. Je dois parler avec Mavos.",text="à l'extrémité nord des ruines.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3616,objective="Parlez à Mavos",step="Une grande explosion s'est produite avant que je ne sois renvoyé vers le présent. Ce doit être ainsi que Mavos est mort.\r\n\r\nJe dois lui parler.",text="à sa tombe, dans la partie sud de Othrenis.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3616,objective="Parlez à Mavos",step="Une grande explosion s'est produite avant que je ne sois renvoyée vers le présent. Ce doit être ainsi que Mavos est mort.\r\n\r\nJe dois lui parler.",text="à sa tombe, dans la partie sud de Othrenis.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3617,objective="Parlez à Bala",step="Après avoir parlé à Eanen, je dois dire quelque chose à Bala.",text="à l'entrée du Othrenis.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3617,objective="Parlez à Bala",step="Eanen a feint ses sentiments pour Bala. Lui et sa femme ont trouvé son histoire très distrayante. Je dois dire... quelque chose, à Bala.",text="à l'entrée du Othrenis.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3626,objective="Parlez à Fafnyr",step="Quand je suis ressorti, j'ai découvert que Fafnyr et les autres gardes avaient été attaqués. Je ne trouve Gar nulle part, je devrais parler à Fafnyr pour découvrir ce qu'il s'est passé.",text="à l'extérieur de la maison principale le Hrogarheim.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3626,objective="Parlez à hrogar",step="Un ouvrier d'Hrogarheim m'a recommandé de parler à son maître, Hrogar, si je voulais les aider à combattre les gobelins.",text="à son manoir.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
