{quest=3632,objective="Parlez à Garyn Indoril",step="Une sentinelle m'a demandé de parler avec Garyn Indoril au camp de siège du Pacte.",text="au camp, situé au sud-ouest du chemin principal jusqu'en Fort Virak.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3632,objective="Parlez à Marche-cendre",step="Je dois parler avec Marche-cendre dans les ruines.",text="dans les Fort Virak ruines, sur le mur sud du fort.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3632,objective="Parlez à Marche-cendre",step="Nous sommes dans le fort, je dois parler avec Marche-cendre.",text="à la porte orientale des Fort Virak ruines.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3632,objective="Parlez avec Garyn Indoril",step="Une sentinelle m'a demandé de parler avec Garyn Indoril au camp de siège du Pacte.",text="au camp, situé au sud-ouest du chemin principal jusqu'en Fort Virak.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3639,objective="Parlez à Drathus Othral",step="J'ai convaincu les races de Cœurébène de coopérer pour défendre leur ville. On dirait que chacune était manipulée par un Elfe noir, un certain Rhavil Urano. Drathus Othral sera certainement intéressé par ses activités.",text="à la maison de Hlaalu, la mairie près du centre de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3639,objective="Parlez avec Drathus Othral",step="J'ai convaincu les races de Cœurébène de coopérer pour défendre leur ville. On dirait que chacune était manipulée par un Elfe noir, un certain Rhavil Urano. Drathus Othral sera certainement intéressé par ses activités.",text="à la maison de Hlaalu, la mairie près du centre de la ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3642,objective="Parlez à Merarii Telvanni",step="J'ai fabriqué le totem éthérique. Je dois parler avec Merarii Telvanni pour savoir ce qu'elle veut que j'en fasse.",text="sur la plate-forme sud du donjon.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3642,objective="Parlez à Merarii Telvanni",step="Parlez de nouveau à Merarii Telvanni",text="au niveau sud du donjon.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3642,objective="Parlez avec Merarii Telvanni",step="J'ai fabriqué le totem éthérique. Je dois parler avec Merarii Telvanni pour savoir ce qu'elle veut que j'en fasse.",text="sur la plate-forme sud du donjon.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3642,objective="Parlez avec Merarii Telvanni",step="Parlez de nouveau à Merarii Telvanni",text="au niveau sud du donjon.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3643,objective="Parlez au gardien Vildras",step="Le gardien Vildras et les mages qui ont créé la malédiction sont en position. Je dois parler avec le gardien Vildras.",text="dans la chambre occidentale du reliquaire de la tour d'Heimlyn, dans le terrain sud.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
