{quest=3645,objective="Parlez à Zasha-Ja",step="Biiril délirait à moitié sous l'effet de la sève d'Hist, mais il a bien identifié un Dunmer dénommé Rhavil. C'est lui qui lui a parlé des propriétés psychotropes de la sève. Cette révélation a enragé Zasha-Ja.",text="dans sa maison, directement au sud de l’arbre de Cœurébène.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3645,objective="Parlez avec Zasha-Ja",step="Biiril délirait à moitié sous l'effet de la sève d'Hist, mais il a bien identifié un Dunmer dénommé Rhavil. C'est lui qui lui a parlé des propriétés psychotropes de la sève. Cette révélation a enragé Zasha-Ja.",text="dans sa maison, directement au sud de l’arbre de Cœurébène.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3646,objective="Parlez à Ruvali",step="Je dois trouver Ruvali pour vérifier si la créature l'a copiée.",text="au deuxième étage de sa maison.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3646,objective="Pourchassez la créature",step="Après avoir tué le double du soldat, une forme répugnante s'est extraite du corps et a fui dans les étables. Je devrais la poursuivre avant qu'elle trouve un nouveau corps.",text="à travers la porte de la cave jusqu'à la grange.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3646,objective="Pourchassez la créature",step="La créature a fui à nouveau. Je dois la pourchasser avant qu'elle copie Ruvali.",text="hors de la cave et retour dans la maison.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3651,objective="Parlez à Bodani",step="J'ai décidé de soumettre la proposition de Tévynni à l'augure. Elle fera affaire avec le vallon et Raston sera libéré.",text="au campement d'Ashlander dans le vallon de l'Esprit du serpent.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3651,objective="Parlez à Bodani",step="J'ai décidé que les Mabrigash resteraient isolés. Le marchand sera au service de l'Esprit du serpent.",text="au campement d'Ashlander dans le vallon de l'Esprit du serpent.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3652,objective="Parlez à Madras",step="Madras ne me fait pas encore confiance, mais j'ai décidé de l'aider. Je devrais tenter de lui parler à nouveau pour découvrir la suite du plan.",text="à l'intérieur de la maison de Tédas en Narsis.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3652,objective="Parlez à Madras",step="On ma demandé d'aider Anguille-furtive et ses amis. Ils souhaitent venir en aide aux villageois capturés, mais ignorent tout de l'art de la guerre et de ce qui les attend.",text="à l'intérieur de la maison de Tédas en Narsis.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3660,objective="Parlez à Varon Davel",step="Je devrais informer Varon de cette découverte.",text="au bord du lac au nord de Narsis.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3660,objective="Parlez à Varon Davel",step="Varon et ses gardes m'attendent. Je dois retourner auprès de lui.",text="au bord du lac au nord de Narsis.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3661,objective="Parlez au défenseur Maéra",step="J'ai arrêté les pillards Drès. Je dois en informer le défenseur Maéra qui m'attend à l'entrée des ruines.",text="à l'entrée principale des ruines de Mzithumz.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3661,objective="Parlez au défenseur Maéra",step="J'ai interrogé Ithis Omalor et ai appris que la magistris Vox lui avait ordonné d'attaquer le convoi. J'ai refusé de l'absoudre de ses crimes et l'ai abandonné à son sort dans les profondeurs de Mzithumz.",text="à l'entrée principale de Mzithumz.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3666,objective="Parlez à Ragna Cime-foudre",step="Je devrais toucher deux mots à Ragna au sujet de ce nouveau domestique et de la rencontre que j'ai faite aux ruines situées aux abords de la rivière.",text="près de l'entrée dans le donjon de fort Tal'Deic.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3666,objective="Parlez à Ragna Cime-foudre",step="Ragna Cime-foudre n'a rien d'une espionne à mes yeux. Je devrais lui parler.",text="près de l'entrée dans le donjon de fort Tal'Deic.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3667,objective="Parlez au disciple Sildras",step="Comme on m'en avait averti, les trois Sanctuaires étaient dérangés par des alits carnassiers. Mais cela n'avait rien à voir avec la désapprobation du Tribunal. Quelqu'un a déposé des tas d'abats près de chaque sanctuaire pour les attirer. Je devrais aller apprendre la nouvelle au disciple Sildras.",text="au temple du Tribunal, la grande flèche dans la partie occidentale de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3667,objective="Parlez au disciple Sildras",step="J'ai parlé du message que m'a donné le Tribunal au disciple Sildras. Il l'a trouvé encourageant.",text="au temple du Tribunal, la grande flèche dans la partie occidentale de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3667,objective="Parlez avec le disciple Sildras",step="Comme on m'en avait averti, les trois Sanctuaires étaient dérangés par des alits carnassiers. Mais cela n'avait rien à voir avec la désapprobation du Tribunal. Quelqu'un a déposé des tas d'abats près de chaque sanctuaire pour les attirer. Je devrais aller apprendre la nouvelle au disciple Sildras.",text="au temple du Tribunal, la grande flèche dans la partie occidentale de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
