{quest=3678,objective="Parlez avec Chimatei",step="Il me faut m'adresser à Chimatei pour repasser l'épreuve du Cœur.",text="à l’angle nord-ouest de la pyramide d’Hissmir.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3678,objective="Parlez avec Chimatei",step="J'ai remporté l'épreuve de l'Esprit. Je devrais m'enquérir de l'épreuve suivante auprès de Chimatei.",text="à l’angle nord-ouest de la pyramide d’Hissmir.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3683,objective="Parlez au capitaine Valec Doronil",step="J'ai informé le capitaine Valec de ce que j'ai découvert dans les ruines courant sous le fort Tal'Deic. Je devrais lui demander s'il a encore besoin de mes services.",text="à l'intérieur du don de fort Tal'Deic.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3684,objective="Parlez au commandant Taldyn",step="Il me faut m'entretenir avec le commandant Taldyn dans la cour d'entraînement pour apprendre comment vaincre les Sentinelles.",text="dans la cour d'entraînement de fort Tal'Deic.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3684,objective="Parlez au commandant Taldyn",step="J'ai défié et triomphé des membres corrompus des Sentinelles Rédoran. Je devrais en aviser le commandant Taldyn.",text="dans la cour d'entraînement de fort Tal'Deic.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3685,objective="Parlez au chef Suhlak",step="Aucun des lieutenants du culte n'a accepté de se rendre. Je dois en informer le chef Suhlak.",text="dans sa hutte au centre du village.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3685,objective="Parlez au chef Suhlak",step="J'ai appris un secret stupéfiant. Les habitants d’Inondelle sont des squelettes animés ! Le chef Suhlak m'a demandé de ne pas m'alarmer. Il va me falloir approfondir cette conversation avec elle.",text="dans sa hutte au centre du village.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3685,objective="Parlez au chef Suhlak",step="J'ai récupéré l’éventail de pierres d'âme. Il me faut le rendre au chef Suhlak.",text="dans sa hutte au centre du village.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3685,objective="Parlez avec le chef Suhlak",step="Aucun des lieutenants du culte n'a accepté de se rendre. Je dois en informer le chef Suhlak.",text="dans sa hutte au centre du village.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3685,objective="Parlez avec le chef Suhlak",step="J'ai appris un secret stupéfiant. Les habitants d’Inondelle sont des squelettes animés ! Le chef Suhlak m'a demandé de ne pas m'alarmer. Il va me falloir approfondir cette conversation avec elle.",text="dans sa hutte au centre du village.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3685,objective="Parlez avec le chef Suhlak",step="J'ai récupéré l’éventail de pierres d'âme. Il me faut le rendre au chef Suhlak.",text="dans sa hutte au centre du village.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3695,objective="Parlez à Denu Faren",step="Le grand maître m'a dit de parler à son sénéchal, Denu Faren, s'il me fallait quoi que ce soit.",text="dans le grand maître, au nord de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3695,objective="Parlez avec Denu Faren",step="Le grand maître m'a dit de parler à son sénéchal, Denu Faren, s'il me fallait quoi que ce soit.",text="dans le grand maître, au nord de la ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3717,objective="Adressez-vous à Drillk",step="Drillk m'a nommé capitaine de son armée royale. Maintenant qu'il s'est « adressé » à ses sujets, je devrais aborder le sujet de la pierre-clef.",text="à la tour Ayleid cassée au nord du village en Zuuk.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3717,objective="Adressez-vous à Drillk",step="Drillk m'a nommée capitaine de son armée royale. Maintenant qu'il s'est « adressé » à ses sujets, je devrais aborder le sujet de la pierre-clef.",text="à la tour Ayleid cassée au nord du village en Zuuk.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3717,objective="Adressez-vous à Drillk",step="J'ai libéré les sujets de Zuuk qui ne sont autres que des esprits. Je dois en aviser Drillk.",text="à sa cabane en Zuuk.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3718,objective="Parlez à Lodyna Arethi",step="Drillk est mort. Il a donné sa vie pour me remettre la pierre-clef. Je devrais m'en retourner auprès de Lodyna Arethi pour l'en informer.",text="derrière une bûreau d'arbres tombé près du carrefour au sud de Zuuk",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3718,objective="Parlez à Lodyna Arethi",step="Je n'ai pas pu me résoudre à laisser Drillk se sacrifier pour moi. La pierre-clef sera en sécurité avec lui. Je dois en aviser Lodyna Arethi.",text="derrière une grue d'arbre tombée près du carrefour au sud de Zuuk.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3718,objective="Parlez avec Lodyna Arethi",step="Drillk est mort. Il a donné sa vie pour me remettre la pierre-clef. Je devrais m'en retourner auprès de Lodyna Arethi pour l'en informer.",text="derrière une bûreau d'arbres tombé près du carrefour au sud de Zuuk",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3718,objective="Parlez avec Lodyna Arethi",step="Je n'ai pas pu me résoudre à laisser Drillk se sacrifier pour moi. La pierre-clef sera en sécurité avec lui. Je dois en aviser Lodyna Arethi.",text="derrière une grue d'arbre tombée près du carrefour au sud de Zuuk.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3730,objective="Parlez à Parash",step="Je devrais m'en retourner auprès de Parash pour l'informer que les voyageurs sont désormais en sécurité.",text="aux Tombes profondes.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3730,objective="Parlez avec Parash",step="Je devrais m'en retourner auprès de Parash pour l'informer que les voyageurs sont désormais en sécurité.",text="aux Tombes profondes.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3731,objective="Parlez à Xijai-Teel",step="La lucereine a été capturée, toutefois Valrendil est tombé sous son charme. Je dois informer Xijai-Teel que la lucereine ne constitue plus une menace pour les Tombes profondes.",text="au camp de Valrendil derrière le xanmeer sud en Tombes profondes.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3731,objective="Parlez avec Xijai-Teel",step="La lucereine a été capturée, toutefois Valrendil est tombé sous son charme. Je dois informer Xijai-Teel que la lucereine ne constitue plus une menace pour les Tombes profondes.",text="au camp de Valrendil derrière le xanmeer sud en Tombes profondes.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3735,objective="Parlez à Mavos Siloreth",step="Le portail est ouvert. L'esprit de Mavos Siloreth est apparu à nouveau à l'entrée du portail. Je dois lui parler au cas où il aurait un conseil à me donner pour vaincre Balreth.",text="près de l'autel de liaison au bout du sentier nord.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3735,objective="Parlez à Mavos Siloreth",step="Mavos Siloreth est arrivé. Il m'a aidé à emprisonner définitivement Balreth, un Frère de la discorde. Je dois lui parler pour savoir s'il reste quelque chose à faire.",text="dans la caldeira du Mont cendreux.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3787,objective="Retrouvez Bétina à sa maison de famille",step="J'ai décidé de passer sous silence l'embuscade tendue par les Argoniens. Je dois retrouver Bétina devant sa maison familiale, au nord-ouest de l'auberge.",text="au nord-ouest du Soupente de luxe au Nix enflammé.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3787,objective="Retrouvez Bétina à sa maison de famille",step="J'ai informé Bétina de l'embuscade tendue par les Argoniens. Il faut à présent que je la retrouve devant sa maison familiale, au nord-ouest de l'auberge.",text="au nord-ouest du Soupente de luxe au Nix enflammé.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3789,objective="Parlez à Gai-Luron",step="J'ai pris des notes sur toute la représentation, et malgré les avertissements des frères Randoro, j'ai décidé de les donner à Gai-Luron. Je devrais aller lui parler à nouveau.",text="devant le palais du Grand-Maître, au nord de la lande de Kragen.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3789,objective="Parlez à Gai-Luron",step="Les Randoro ne m'ont pas caché ce qu'il adviendrait de Gai-Luron s'il jouait mal. J'ai préféré garder l'information secrète et me débarrasser des notes. Je devrais aller parler à Gai-Luron encore une fois.",text="devant le palais du Grand-Maître, au nord de la lande de Kragen.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3789,objective="Parlez avec Gai-Luron",step="J'ai pris des notes sur toute la représentation, et malgré les avertissements des frères Randoro, j'ai décidé de les donner à Gai-Luron. Je devrais aller lui parler à nouveau.",text="devant le palais du Grand-Maître, au nord de la lande de Kragen.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3789,objective="Parlez avec Gai-Luron",step="Les Randoro ne m'ont pas caché ce qu'il adviendrait de Gai-Luron s'il jouait mal. J'ai préféré garder l'information secrète et me débarrasser des notes. Je devrais aller parler à Gai-Luron encore une fois.",text="devant le palais du Grand-Maître, au nord de la lande de Kragen.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3795,objective="Parlez au sylvegarde Nexith",step="J'ai mis un terme au rituel de corruption de Namira. J'aperçois le sylvegarde Nexith, qui se tient au sommet d'un édifice avoisinant. Je devrais aller m'enquérir de la suite des événements auprès de lui.",text="au sommet de la montagne au sud-ouest de Xal Ithix.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3795,objective="Parlez au sylvegarde Nexith",step="Je devrais m'enquérir des résultats du rituel auprès du sylvegarde Nexith.",text="au sommet du xanmeer au sud de Xal Ithix.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3795,objective="Parlez avec le sylvegarde Nexith",step="J'ai mis un terme au rituel de corruption de Namira. J'aperçois le sylvegarde Nexith, qui se tient au sommet d'un édifice avoisinant. Je devrais aller m'enquérir de la suite des événements auprès de lui.",text="au sommet de la montagne au sud-ouest de Xal Ithix.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3795,objective="Parlez avec le sylvegarde Nexith",step="Je devrais m'enquérir des résultats du rituel auprès du sylvegarde Nexith.",text="au sommet du xanmeer au sud de Xal Ithix.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3799,objective="Allez trouver Mousse-Silencieuse",step="À présent que j'ai récupéré la pierre-clef de Relléis Lor, il me faut retourner auprès de Mousse-Silencieuse.\r\n\r\nIl m'attend sur le site de fouilles d'Obscuronde.",text="à l'est des ruines d'Ayleid situées à l'extrémité sud de Obscuronde.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3799,objective="Allez trouver Mousse-Silencieuse",step="J'ai répandu les sels de feu le long de la rivière. Il me faut maintenant retrouver Mousse-Silencieuse à l'Est du navire du Domaine.",text="à l’est du navire du Domaine.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3799,objective="Parlez à Cœur-Pâle",step="J'ai incendié les navires du Domaine et récupéré la pierre-clef de Relléis Lor. Je dois en aviser Cœur-Pâle à Obscuronde.",text="à son camp sur la colline près de l'extrémité sud de Obscuronde.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3799,objective="Parlez à Cœur-Pâle",step="J'ai participé à un rituel qui a lié la pierre-clef de Relléis Lor à moi. Je devrais m'enquérir de la suite des événements auprès de Cœur-Pâle.",text="à son camp sur la colline près de l'extrémité sud de Obscuronde.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3799,objective="Parlez avec Cœur-Pâle",step="J'ai incendié les navires du Domaine et récupéré la pierre-clef de Relléis Lor. Je dois en aviser Cœur-Pâle à Obscuronde.",text="à son camp sur la colline près de l'extrémité sud de Obscuronde.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3799,objective="Parlez avec Cœur-Pâle",step="J'ai participé à un rituel qui a lié la pierre-clef de Relléis Lor à moi. Je devrais m'enquérir de la suite des événements auprès de Cœur-Pâle.",text="à son camp sur la colline près de l'extrémité sud de Obscuronde.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3810,objective="Utilisez le cristal psychique pour plonger dans la mémoire de Vox",step="Il me faut synchroniser mon esprit au cristal psychique pour explorer les derniers souvenirs de Vox. Une fois que je m'y trouverai, il me faudra m'adresser à la projection d'Aspera.",text="au centre de Caverne creuse à l'extrémité nord-est de gouffre d'Eidolon.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3810,objective="Utilisez le cristal psychique pour plonger dans la mémoire de Vox",step="Il me faut synchroniser mon esprit au cristal psychique pour explorer les plus récents souvenirs de Vox. Une fois que je m'y trouverai, il me faudra m'adresser à la projection d'Aspera.",text="dans l'aile occidentale de Caverne creuse à l'extrémité nord-est de gouffre d'Eidolon.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3810,objective="Utilisez le cristal psychique pour plonger dans la mémoire de Vox",step="Il me faut synchroniser mon esprit au cristal psychique pour explorer les souvenirs suivants de Vox. Une fois que je m'y trouverai, il me faudra m'adresser à la projection d'Aspera.",text="dans l'aile est de Caverne creuse à l'extrémité nord-est de gouffre d'Eidolon.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3817,objective="Parlez à Almalexia",step="J'ai prié à l'autel d'Almalexia, il me faut à présent m'adresser à elle.",text="dans son cloître dans le temple du Tribunal en Longsanglot.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3817,objective="Parlez à Almalexia",step="J'ai vaincu Vanus Sathram et secouru le temple du Tribunal, mais Vox est parvenue à s'enfuir avec le Jugement de Véloth. Je dois en informer Almalexia.",text="à l'extérieur du temple du Tribunal en Longsanglot.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3817,objective="Parlez à Almalexia",step="Un Ordonnateur m'a informé qu'Almalexia avait demandé à me voir au temple.",text="au temple du Tribunal en Longsanglot.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3818,objective="Adressez-vous à saint Véloth",step="J'ai restauré l'oratoire de saint Véloth et reçu sa bénédiction en remerciement. Il est temps pour moi d'affronter la magistris Vox au gouffre d'Eidolon.",text="au sommet du sanctuaire de saint Véloth.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3818,objective="Adressez-vous à saint Véloth",step="Le reliquaire est de nouveau en état et l'esprit de saint Véloth a recouvré ses pouvoirs. Il me faut m'adresser à lui.",text="au sommet du sanctuaire de saint Véloth.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3820,objective="Parlez à l'Esseulé",step="L'Esseulé a partagé une vision du passé avec moi. Il me faut lui parler de ce que j'y ai vu.",text="à l'intérieur du temple de Selfora sur la colline.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3820,objective="Parlez à l'Esseulé",step="Maintenant que j'ai mis la main sur l'ampoule d'eau bénite, il me faut m'adresser à l'Esseulé, à l'entrée du temple.",text="à l'intérieur du temple de Selfora sur la colline.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3820,objective="Parlez à l'Esseulé",step="Un esprit surnommé l'Esseulé est apparu devant l'entrée du temple. Il semble vouloir me parler.",text="à l'intérieur du temple de Selfora sur la colline.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3827,objective="Parlez à la sylvegarde Deyapa",step="À présent que j'ai remis le bâton brisé au sylvegarde, je n'ai plus qu'à attendre de voir si elle parvient à soigner l'Hist... ou tout du moins, à rendre le repos éternel à ses esprits. Je lui parlerai quand elle en aura terminé.",text="près de l'arbre Hist au centre du Hamlet oublié.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3827,objective="Parlez à la sylvegarde Deyapa",step="Les cuves de raffinement du Domaine ont été vidées de leur sève. Les esprits argoniens doivent maintenant être apaisés, mais les soldats du Domaine savent d'où je viens. Il me faut m'en retourner au pied de l'Hist et m'entretenir avec la sylvegarde Deyapa.",text="à Manche oublié.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3827,objective="Parlez à la sylvegarde Deyapa",step="Les troupes du Domaine ont été mises en déroute. Le rituel de la sylvegarde Deyapa a fonctionné. Les esprits argoniens du hameau oublié peuvent maintenant retourner à l'Hist et reposer en paix.",text="près de l’Hist au centre du hameau abandonné.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3827,objective="Parlez avec la sylvegarde Deyapa",step="À présent que j'ai remis le bâton brisé au sylvegarde, je n'ai plus qu'à attendre de voir si elle parvient à soigner l'Hist... ou tout du moins, à rendre le repos éternel à ses esprits. Je lui parlerai quand elle en aura terminé.",text="près de l'arbre Hist au centre du Hamlet oublié.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3827,objective="Parlez avec la sylvegarde Deyapa",step="Les cuves de raffinement du Domaine ont été vidées de leur sève. Les esprits argoniens doivent maintenant être apaisés, mais les soldats du Domaine savent d'où je viens. Il me faut m'en retourner au pied de l'Hist et m'entretenir avec la sylvegarde Deyapa.",text="à Manche oublié.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3827,objective="Parlez avec la sylvegarde Deyapa",step="Les troupes du Domaine ont été mises en déroute. Le rituel de la sylvegarde Deyapa a fonctionné. Les esprits argoniens du hameau oublié peuvent maintenant retourner à l'Hist et reposer en paix.",text="près de l’Hist au centre du hameau abandonné.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3840,objective="Parlez à la sylvegarde Raleetal",step="J'ai trouvé un sac de couchage du Domaine, encore imprégné de l'odeur de son propriétaire. La sylvegarde Raleetal en a besoin pour déclencher le rituel au reliquaire, dans les ruines non loin de son campement.",text="près du reliquaire à proximité des ruines centrales Lisemère.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3840,objective="Parlez à la sylvegarde Raleetal",step="L'espion du Domaine qui usurpait la forme de Saervild est mort. Je dois apporter les reliques à la sylvegarde Raleetal.",text="à l'extérieur de la grotte Mudshallow, au sud de camp collet-de-soie.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3840,objective="Parlez à la sylvegarde Raleetal",step="Le dreugh semblait envoûté par l'odeur des troupes du Domaine. Je dois parler à la sylvegarde Raleetal avant de partir à la recherche du prévôt Saervild Vent-d'acier.",text="aux ruines centrales de Lisemère.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3840,objective="Parlez à la sylvegarde Raleetal 1",step="L'espion du Domaine qui usurpait la forme de Saervild est mort. Je dois apporter les reliques à la sylvegarde Raleetal.",text="à l'extérieur de la grotte Mudshallow, au sud de camp collet-de-soie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3840,objective="Parlez à Njorlund Vent-d'acier",step="Au moment où j'ai récupéré les dernières reliques, Njorlund Vent-d'acier est arrivé. Je dois lui dire de retourner au camp.",text="dans les ruines de Lisemère.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3840,objective="Parlez à Njorlund Vent-d'acier",step="Les sylvegardes sont absents de leur campement. Il faut que j'en avise Njorlund Vent-d'acier.",text="au camp d'ensemmades par la route au nord de Lisemère ruines.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3840,objective="Parlez avec la sylvegarde Raleetal",step="J'ai trouvé un sac de couchage du Domaine, encore imprégné de l'odeur de son propriétaire. La sylvegarde Raleetal en a besoin pour déclencher le rituel au reliquaire, dans les ruines non loin de son campement.",text="près du reliquaire à proximité des ruines centrales Lisemère.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3840,objective="Parlez avec la sylvegarde Raleetal",step="L'espion du Domaine qui usurpait la forme de Saervild est mort. Je dois apporter les reliques à la sylvegarde Raleetal.",text="à l'extérieur de la grotte Mudshallow, au sud de camp collet-de-soie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3840,objective="Parlez avec la sylvegarde Raleetal",step="Le dreugh semblait envoûté par l'odeur des troupes du Domaine. Je dois parler à la sylvegarde Raleetal avant de partir à la recherche du prévôt Saervild Vent-d'acier.",text="aux ruines centrales de Lisemère.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3840,objective="Parlez avec la sylvegarde Raleetal 1",step="L'espion du Domaine qui usurpait la forme de Saervild est mort. Je dois apporter les reliques à la sylvegarde Raleetal.",text="à l'extérieur de la grotte Mudshallow, au sud de camp collet-de-soie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3840,objective="Parlez avec Njorlund Vent-d'acier",step="Au moment où j'ai récupéré les dernières reliques, Njorlund Vent-d'acier est arrivé. Je dois lui dire de retourner au camp.",text="dans les ruines de Lisemère.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3840,objective="Parlez avec Njorlund Vent-d'acier",step="Les sylvegardes sont absents de leur campement. Il faut que j'en avise Njorlund Vent-d'acier.",text="au camp d'ensemmades par la route au nord de Lisemère ruines.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3846,objective="Parlez au prévôt Hernik",step="Je dois parler au prévôt Hernik au sujet de la pierre-clef.",text="sur la route est, à l'extérieur de prison de Blanche-rose.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3846,objective="Parlez au prévôt Hernik",step="Le prévôt Hernik s'est enfui de la prison dès que j'ai tué le général Raetus. Je vais le rejoindre à l'extérieur des murs.",text="près de la sortie sud de la prison de Blanche-rose.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3846,objective="Parlez avec le prévôt Hernik",step="Je dois parler au prévôt Hernik au sujet de la pierre-clef.",text="sur la route est, à l'extérieur de prison de Blanche-rose.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3846,objective="Parlez avec le prévôt Hernik",step="Le prévôt Hernik s'est enfui de la prison dès que j'ai tué le général Raetus. Je vais le rejoindre à l'extérieur des murs.",text="près de la sortie sud de la prison de Blanche-rose.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3850,objective="Parlez à Damrina",step="J'ai libéré Damrina. Je dois lui parler.",text="dans la première chambre entra, près de la collecte méridionale des tuyaux.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3850,objective="Parlez avec Damrina",step="J'ai libéré Damrina. Je dois lui parler.",text="dans la première chambre entra, près de la collecte méridionale des tuyaux.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3852,objective="Parlez à Élynisi Arthalen",step="J'ai secouru la femme et le jeune homme à qui l'esprit m'avait demandé de venir en aide. Il me faut à présent m'en retourner à l'auberge afin de m'assurer qu'il sont sains et saufs.",text="dans l'auberge au bord nord-est de Selfora.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3852,objective="Parlez à Élynisi Arthalen",step="Selfora est sauvée, à présent. Je devrais retourner à l'auberge pour informer Élynisi de ce qu'il est advenu de son père.",text="à l'auberge à la limite nord-est de Selfora.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3864,objective="Trouvez Kireth Vanos",step="Après plusieurs tentatives, je suis finalement parvenu à dompter une araignée dwemer. Voilà donc à quoi sert le tube ! Je devrais rejoindre Kireth Vanos, dans la salle adjacente pour lui en faire la démonstration.",text="à l'intérieur des ruines Dwemer de Bthanual.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3864,objective="Trouvez Kireth Vanos",step="Après plusieurs tentatives, je suis finalement parvenue à dompter une araignée dwemer. Voilà donc à quoi sert le tube ! Je devrais rejoindre Kireth Vanos, dans la salle adjacente pour lui en faire la démonstration.",text="à l'intérieur des ruines Dwemer de Bthanual.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3864,objective="Trouvez Kireth Vanos",step="Kireth est entrée dans les ruines sans son frère, blessé en tentant de la rejoindre. Il a mis au point un tube capable de prendre le contrôle des automates se trouvant à l'intérieur. Je dois le remettre à sa sœur.",text="à l'intérieur des ruines Dwemer de Bthanual.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3864,objective="Trouvez Kireth Vanos",step="Mon araignée a récupéré les pièces dont Kireth a besoin pour réparer l'émetteur. Il me faut m'en retourner auprès d'elle pour les lui remettre.",text="dans l'une des plus grandes chambres à l'intérieur des ruines Dwemer de Bthanual.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3888,objective="Parlez à Regarde-sous-les-Cailloux",step="En fait, les pierres sibyllines sont la clef d'Hist. Les clefs permettent de déverrouiller mais que cache la serrure ? Je dois parler à Regarde pour en savoir plus.",text="au sommet du plus haut bâtiment en grève de Solécaille, à l'ouest du bateau pirate.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3888,objective="Parlez à Regarde-sous-les-Cailloux",step="Je dois m'assurer que l'argonien au sommet du xanmeer connaît la pierre sibylline et son lien avec le xanmeer.",text="au sommet du plus haut bâtiment en grève de Solécaille, à l'ouest du bateau pirate.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3888,objective="Parlez avec Regarde-sous-les-Cailloux",step="En fait, les pierres sibyllines sont la clef d'Hist. Les clefs permettent de déverrouiller mais que cache la serrure ? Je dois parler à Regarde pour en savoir plus.",text="au sommet du plus haut bâtiment en grève de Solécaille, à l'ouest du bateau pirate.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3888,objective="Parlez avec Regarde-sous-les-Cailloux",step="Je dois m'assurer que l'argonien au sommet du xanmeer connaît la pierre sibylline et son lien avec le xanmeer.",text="au sommet du plus haut bâtiment en grève de Solécaille, à l'ouest du bateau pirate.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3889,objective="Parlez à Regarde-sous-les-Cailloux",step="Barvyn a succombé à l'enchantement du croc de Sithis mais il s'est repenti. Et surtout, je n'ai retrouvé qu'un seul croc. L'autre a disparu. Je dois en aviser Regarde-sous-les-Cailloux.",text="à l’entrée de la grotte au sud-est du xanmeer, sur la grève de Solécaille.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3889,objective="Parlez à regarde-sous-les-Cailloux",step="Barvyn n'a pas tenu compte des avertissement de son partenaire. Il a ouvert le xanmeer et il y est entré. J'espère qu'Regarde-sous-les-Cailloux pourra m'expliquer ce qui se cache dans ces ruines.",text="à la flèche occidentale du xanmeer, sur la grève de Solécaille.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
