{quest=3911,objective="Parlez à Maahi",step="J'ai rendu la chair aux prisonniers argoniens. Je dois parler à Maahi.",text="dans l'antichambre de Loriasel.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3911,objective="Parlez à Maahi",step="J'ai rendu la chair des victimes argoniennes. Je dois en aviser Maahi.",text="dans l'antichambre de Loriasel.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3911,objective="Parlez à Maahi",step="J'ai trouvé quatre des prisonniers disparus. Akeenus a dit que Maahi attendait un peu plus loin dans la caverne.",text="dans la caverne menant des grottes adjacentes aux salles de l'est de Loriasel.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3911,objective="Parlez avec Maahi",step="J'ai rendu la chair aux prisonniers argoniens. Je dois parler à Maahi.",text="dans l'antichambre de Loriasel.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3911,objective="Parlez avec Maahi",step="J'ai rendu la chair des victimes argoniennes. Je dois en aviser Maahi.",text="dans l'antichambre de Loriasel.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3911,objective="Parlez avec Maahi",step="J'ai trouvé quatre des prisonniers disparus. Akeenus a dit que Maahi attendait un peu plus loin dans la caverne.",text="dans la caverne menant des grottes adjacentes aux salles de l'est de Loriasel.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3912,objective="Parlez à un chevalier ayléide",step="L'esprit a chassé le fantôme de l'enchanteresse qui a assassiné le suzerain. Il m'a demandé de détruire l'Un phylactère ? de l'enchanteresse. L'esprit pense que cela mettra fin à la menace de l'enchanteresse.",text="dans les tombe du suzerain dans les halls ouest de Loriasel.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3912,objective="Parlez à un chevalier ayléide",step="L'esprit a chassé le fantôme de l'enchanteresse qui a assassiné le suzerain. Il m'a demandé de détruire le phylactère de l'enchanteresse. L'esprit pense que cela mettra fin à la menace de l'enchanteresse.",text="dans les tombe du suzerain dans les halls ouest de Loriasel.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3912,objective="Parlez à un chevalier ayléide",step="L'esprit a chassé le fantôme de l'Enchanteur qui a assassiné le suzerain. Il m'a demandé de détruire l'Un phylactère ? de l'Enchanteur. L'esprit pense que cela mettra fin à la menace de l'Enchanteur.",text="dans les tombe du suzerain dans les halls ouest de Loriasel.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3912,objective="Parlez à un chevalier ayléide",step="L'esprit a chassé le fantôme de l'Enchanteur qui a assassiné le suzerain. Il m'a demandé de détruire le phylactère de l'Enchanteur. L'esprit pense que cela mettra fin à la menace de l'Enchanteur.",text="dans les tombe du suzerain dans les halls ouest de Loriasel.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3916,objective="Explorez le gouffre",step="Haskill m'a dit de suivre le chemin qui mène au creux du Frometoneur. Les volumes que je recherche sont cachés là-bas.",text="au-delà du sanctuaire, en suivant le chemin qui s’enfonce dans le creux du Frometoneur.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3916,objective="Parlez à Haskill",step="Je devrais parler à Haskill de l'endroit où se trouvent ces volumes.",text="derrière le bureau de la salle d’entrée, parmi les livres.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3916,objective="Parlez à Haskill",step="Maintenant que j'ai refermé ce portail, je devrais parler à Haskill.",text="derrière le bureau de la salle d’entrée, parmi les livres.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3918,objective="Écoutez le discours de la reine Ayrenn",step="Shéogorath a écrit un discours pour Ayrenn, la chef du Domaine aldmeri. Je devrais écouter ce qu'elle a à dire.",text="dans l'imaginaire Domaine de foyer de Faneciel.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3918,objective="Récupérez le livre",step="Après m'être prêté à cette pénible mascarade, Shéogorath m'a donné l'autorisation de prendre le livre. Il est temps de m'en emparer et de sortir d'ici.",text="au-dessus de son piédestal, au bout de ce royaume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3918,objective="Récupérez le livre",step="Après m'être prêtée à cette pénible mascarade, Shéogorath m'a donné l'autorisation de prendre le livre. Il est temps de m'en emparer et de sortir d'ici.",text="au-dessus de son piédestal, au bout de ce royaume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3918,objective="Sauvez les membres de la guilde",step="Je dois sauver les acteurs incarnant des membres éminents de la guilde des mages afin de progresser.",text="dans la ville imaginaire de l'alliance de Dagaltevance.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3918,objective="Tuez la reine Ayrenn",step="L'actrice incarnant la reine Ayrenn est la dernière ennemie à me barrer la route. Je dois l'anéantir pour avancer.",text="dans l'imaginaire Domaine de foyer de Faneciel.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3918,objective="Tuez le haut-roi Émeric",step="Le seul adversaire qui se dresse encore devant moi est l'acteur censé incarner le haut-roi Émeric, chef de l'Alliance. Il me faut l'anéantir afin de terminer l'épreuve.",text="au centre de la ville imaginaire de Dagaltevance.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3921,objective="Parlez au contremaître Gandis",step="J'ai libéré tous les mineurs que j'ai pu trouver. Je dois trouver le contremaître Gandis et lui apprendre la bonne nouvelle.",text="près de la première intersection à l'intérieur de mine de la Pierre-de-Shor.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3921,objective="Parlez au contremaître Gandis",step="Je devrais retrouver le contremaître Gandis à la pierre de Shor pour le prévenir que j'ai sauvé autant de mineurs que possible.",text="près de la première intersection à l’intérieur de la mine de la Pierre-de-Shor.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3921,objective="Parlez avec le contremaître Gandis",step="J'ai libéré tous les mineurs que j'ai pu trouver. Je dois trouver le contremaître Gandis et lui apprendre la bonne nouvelle.",text="près de la première intersection à l'intérieur de mine de la Pierre-de-Shor.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3921,objective="Parlez avec le contremaître Gandis",step="Je devrais retrouver le contremaître Gandis à la pierre de Shor pour le prévenir que j'ai sauvé autant de mineurs que possible.",text="près de la première intersection à l’intérieur de la mine de la Pierre-de-Shor.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3923,objective="Parlez au centurion Gjakil",step="J'ai vaincu le chef géant. Je dois parler avec le centurion Gjakil.",text="à l'extérieur du camp du géant à crête du mammouth.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3923,objective="Parlez avec le centurion Gjakil",step="J'ai vaincu le chef géant. Je dois parler avec le centurion Gjakil.",text="à l'extérieur du camp du géant à crête du mammouth.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3928,objective="Parlez à Dajaheel",step="Les adeptes du Ver transforment les Crevassais suite à un accord entre Stral et le chef des adeptes. Je dois immédiatement prévenir Dajaheel.",text="dans une zone de toilette dans le camp bois de Vernim près de la mine de la Galerne oratoire.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3928,objective="Parlez à Dajaheel",step="On m'a demandé de parler avec Dajaheel à l'avant-poste du Pacte.",text="dans une zone de tentes en bois de Vernim, juste au large de la route, à l'ouest de la mine de la Galerne oratoire.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3953,objective="Entrez dans l'annexe du château",step="Shéogorath m'a demandé d'aller dans l'aile des invités de son Château, afin de renvoyer un de ses invités indisciplinés. Je devrais y aller.",text="à l'extrémité sud du chemin.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3953,objective="Entrez dans le portail",step="Shéogorath a « gentiment » ouvert un portail pour me permettre de continuer mon exploration. Il ne me reste plus qu'à l'emprunter.",text="aux jardins du château.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3953,objective="Explorez le presbytère",step="Le « presbytère » évoqué par Shéogorath est l'un des rares endroits que je n'ai pas encore explorés. Shéogorath veut que je m'y rende pour rencontrer ses proches et fureter dans ses souvenirs de famille.",text="au sud-est du château.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3953,objective="Expulsez le convive inopportun",step="Shéogorath compte sur moi pour expulser l'un des convives de l'annexe qui selon lui n'y aurait pas sa place. Il m'a également averti que certains d'entre eux avaient des tendances meurtrières. Je dois parler avec les invités et décider lequel je veux renvoyer.",text="dans le annexe du château.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3953,objective="Expulsez le convive inopportun",step="Shéogorath compte sur moi pour expulser l'un des convives de l'annexe qui selon lui n'y aurait pas sa place. Il m'a également avertie que certains d'entre eux avaient des tendances meurtrières. Je dois parler avec les invités et décider lequel je veux renvoyer.",text="dans le annexe du château.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3953,objective="Franchissez le portail",step="Shéogorath a « gentiment » ouvert un portail pour me permettre de continuer mon exploration. Il ne me reste plus qu'à l'emprunter.",text="aux jardins du château.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3953,objective="Parlez à Shéogorath",step="J'ai passé l'épreuve de Shéogorath. Il est temps de lui parler à nouveau. Avec un peu de chance, tout ça sera bientôt terminé.",text="près de la porte éclairée.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3953,objective="Parlez à Shéogorath",step="J'ai réussi à sortir du labyrinthe. Shéogorath est de retour pour discuter. Il est temps de reprendre notre causerie.",text="près des tables et des chaises de la réception dunmer.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3953,objective="Parlez à Shéogorath",step="J'ai survécu aux épreuves de Shéogorath. Avec un peu de chance, il va enfin me donner le dernier livre.",text="sur l’escalier qui mène à la chambre principale. Un tome flotte à ses côtés.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3953,objective="Parlez à Shéogorath",step="Je suppose que Shéogorath ne me laissera pas poursuivre avant que nous ayons eu une petite discussion. Je devrais lui parler.",text="près du portail où je suis entré.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3953,objective="Parlez à Shéogorath",step="Une chose est sûre : Shéogorath adore s'écouter parler. Il est temps de m'entretenir à nouveau avec lui.",text="au sommet de l’escalier, au sud du portail de l’annexe du château.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3953,objective="Passez le portail",step="Shéogorath a « gentiment » ouvert un portail pour me permettre de continuer mon exploration. Il ne me reste plus qu'à l'emprunter.",text="aux jardins du château.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3953,objective="Récupérez le tome",step="Shéogorath a accepté de me livrer le dernier tome. Il est temps de m'en emparer avant de retourner voir Valastë.",text="au-dessus du piédestal : le tome y flotte.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3953,objective="Traversez le portail",step="Shéogorath a « gentiment » ouvert un portail pour me permettre de continuer mon exploration. Il ne me reste plus qu'à l'emprunter.",text="aux jardins du château.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3953,objective="Trouvez la sortie du labyrinthe",step="J'ai allumé les braseros. Il s'agit à présent de me frayer un chemin jusqu'à la sortie du labyrinthe.",text="au sud-est et en haut de quelques escaliers.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3957,objective="Parlez avec Belron",step="Belron a quitté le camp en quête de plus d'informations sur les rituels. Je dois le chercher sur le champ de bataille.",text="dans l'enceinte de la culture du ver.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3957,objective="Parlez avec Belron",step="J'ai pris trois autres cœurs aux sépulcraux. Je dois retourner auprès de Belron au camp du Pacte.",text="dans sa tente dans le camp du Pacte près de mine de la Galerne oratoire.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3959,objective="Parlez au capitaine Jardirr",step="La Brèche est au courant du danger que représentent les Crevassais. Je dois me présenter au capitaine Jardirr. Elle a dit qu'elle ramènerait ses hommes à la tour.",text="à passe de l'Avalanche.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3959,objective="Parlez au capitaine Jardirr",step="Un des soldats du Pacte m'a dit que le capitaine Jardirr s'est réfugié dans une petite grotte près du champ de bataille. Je dois la trouver et la mettre en sécurité.",text="dans une petite grotte près du champ de bataille au sud-ouest de passe de l'Avalanche.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3959,objective="Parlez avec le capitaine Jardirr",step="La Brèche est au courant du danger que représentent les Crevassais. Je dois me présenter au capitaine Jardirr. Elle a dit qu'elle ramènerait ses hommes à la tour.",text="à passe de l'Avalanche.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3959,objective="Parlez avec le capitaine Jardirr",step="Un des soldats du Pacte m'a dit que le capitaine Jardirr s'est réfugié dans une petite grotte près du champ de bataille. Je dois la trouver et la mettre en sécurité.",text="dans une petite grotte près du champ de bataille au sud-ouest de passe de l'Avalanche.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3964,objective="Parlez à Paldeen",step="J'ai survécu aux dangers de la cité perdue avec Paldeen, et j'ai récupéré le cartulaire. Je dois à nouveau lui parler.",text="au sommet d'un petit escalier dans les Archives de la Cité Perdue.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3964,objective="Parlez à Paldeen",step="Paldeen a fini d'examiner la tablette. Il veut me parler.",text="près de l'ancienne tablette Yokudan près de l'entrée de la section principale des ruines.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3968,objective="Parlez avec Belron",step="J'ai bu la potion. Je dois parler avec Belron pour savoir quoi faire ensuite.",text="dans sa tente en bois de Vernim.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3968,objective="Présentez-vous au camp du Pacte",step="Stral est mort. Malheureusement, il a emporté Dajaheel et Belron avec lui. Je dois retourner au campement et rejoindre les survivants.",text="à l'ouest de la mine de la Galerne oratoire, où Orla se trouve sous une canopée.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3974,objective="Parlez à Vigrod Fauche-spectre",step="Je dois demander quoi faire ensuite à Vigrod Fauche-spectre.",text="dans le sous-sol hall de Rochebrune.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3974,objective="Parlez à Vigrod Fauche-spectre",step="Je dois dire à Vigrod Fauche-spectre que Wuuthrad n'est plus là.",text="à l'extérieur hall de Rochebrune.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3974,objective="Parlez à Vigrod Fauche-spectre",step="Je suis au hall de Rochebrune. Je dois me présenter à Vigrod Fauche-spectre.",text="sur le chemin menant du hall de Rochebrune oratoire jusqu'à la salle.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3974,objective="Parlez à vigrod Fauche-spectre 1",step="Je dois dire à Vigrod Fauche-spectre que Wuuthrad n'est plus là.",text="à l'extérieur hall de Rochebrune.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3974,objective="Parlez avec Vigrod Fauche-spectre",step="Je dois demander quoi faire ensuite à Vigrod Fauche-spectre.",text="dans le sous-sol hall de Rochebrune.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3974,objective="Parlez avec Vigrod Fauche-spectre",step="Je dois dire à Vigrod Fauche-spectre que Wuuthrad n'est plus là.",text="à l'extérieur hall de Rochebrune.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3974,objective="Parlez avec Vigrod Fauche-spectre",step="Je suis au hall de Rochebrune. Je dois me présenter à Vigrod Fauche-spectre.",text="sur le chemin menant du hall de Rochebrune oratoire jusqu'à la salle.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3974,objective="Parlez avec Vigrod Fauche-spectre 1",step="Je dois dire à Vigrod Fauche-spectre que Wuuthrad n'est plus là.",text="à l'extérieur hall de Rochebrune.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3986,objective="Parlez à Molla",step="Molla semble enfin prête à me parler. Je devrais écouter son histoire.",text="à la tente abandonnée en face du marchand de guilde, au nord du village.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3986,objective="Parlez avec Molla",step="Molla semble enfin prête à me parler. Je devrais écouter son histoire.",text="à la tente abandonnée en face du marchand de guilde, au nord du village.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3990,objective="Parlez à Rana",step="Le capitaine Rana m'a demandé de l'aider à trouver les villageois manquants. Je dois lui demander où commencer mes recherches.",text="au niveau supérieur de son bureau sur la place centrale.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3991,objective="Actionnez le levier",step="Le capitaine Rana m'a demandé d'actionner un levier dans cette pièce pour qu'elle puisse franchir la porte en surplomb.",text="entre les deux trônes, gardés par des guerriers du souciage.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3991,objective="Ouvrez la porte",step="Le capitaine Rana va déverrouiller une porte en bas des escaliers. Il me faudra passer de l'autre côté.",text="dans les halls inférieurs, en bas des escaliers sud.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3991,objective="Parlez au capitaine Rana",step="J'ai atteint les Éboulis avec le capitaine Rana et les réfugiés. Il me faut m'entretenir avec le capitaine.",text="à la lisière ouest du camp au plus petit quai en Bal Foyen.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3991,objective="Parlez au capitaine Rana",step="Je dois parler au capitaine Rana pour connaître la suite des événements.",text="à l'extrémité de la première salle.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3991,objective="Parlez au capitaine Rana",step="Je dois parler de son plan au capitaine Rana.",text="à l'entrée du Mornetombe.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3991,objective="Parlez au capitaine Rana",step="Nous sommes saufs ! Le capitaine Rana s'entretient avec quelqu'un sur l'un des navires de la crique. Je dois lui parler.",text="à bord d'un bateau pittoresque.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3991,objective="Utilisez l'interrupteur",step="Le capitaine Rana m'a demandé d'actionner un levier dans cette pièce pour qu'elle puisse franchir la porte en surplomb.",text="entre les deux trônes, gardés par des guerriers du souciage.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3991,objective="Utilisez le Switch",step="Le capitaine Rana m'a demandé d'actionner un levier dans cette pièce pour qu'elle puisse franchir la porte en surplomb.",text="entre les deux trônes, gardés par des guerriers du souciage.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3991,objective="Utilisez un interrupteur",step="Le capitaine Rana m'a demandé d'actionner un levier dans cette pièce pour qu'elle puisse franchir la porte en surplomb.",text="entre les deux trônes, gardés par des guerriers du souciage.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3991,objective="Utilisez un Switch",step="Le capitaine Rana m'a demandé d'actionner un levier dans cette pièce pour qu'elle puisse franchir la porte en surplomb.",text="entre les deux trônes, gardés par des guerriers du souciage.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3997,objective="Assistez à la confrontation",step="Après avoir défié Haskill, Shalidor a fait irruption dans la guilde. Je devrais assister à la confrontation entre l'archimage et Shéogorath.",text="à l'intérieur du Eyévéa maison de la guilde des mages.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3997,objective="Fermez le portail ouest",step="Shalidor m'a demandé de sceller les portails à la frontière d'Eyévéa. Cela devrait suffire à mettre un terme à l'invasion daedrique. Shéogorath m'a confié que pour ce faire, il me faudrait retirer les cristaux qui les alimentent.",text="derrière le guilde en prenant son cristal jaune.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3997,objective="Parlez à Shalidor",step="J'ai refermé les portails et placé les cristaux de puissance devant la guilde. Je devrais m'adresser de nouveau à Shalidor pour m'assurer que tout se passe comme prévu.",text="devant la maison de guilde d’Eyévéa.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3997,objective="Parlez à Shalidor",step="Shalidor souhaite que nous parlions de l'île. Je devrais entamer la conversation.",text="près de l’oratoire, sur l’île d’Eyévéa.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3997,objective="Parlez à Shalidor",step="Shéogorath nous a donné cette île, mais les Daedra affluent par les portails. Je dois m'enquérir de la suite des événements auprès de Shalidor.",text="en face de la maison de guilde, au centre d’Eyévéa.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=3997,objective="Parlez à Shéogorath",step="Shéogorath m'a fait une offre. Je peux choisir de laisser Valastë ici, ou de partir avec elle. Si elle reste, il guérira sa folie. Si elle part, il me remettra un livre d'une puissance égalant plusieurs éclats célestes. Il me faut maintenant faire un choix.",text="sur son dernier contrat.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3997,objective="Parlez à Valastë",step="À présent que Shéogorath s'en est allé et que Valastë a recouvré ses esprits, il semblerait que nous ayons repris le contrôle d'Eyévéa. Je devrais m'enquérir de l'état de Valastë.",text="à l'intérieur du Eyévéa maison de la guilde des mages.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=3997,objective="Retrouvez Shalidor à la guilde",step="L'île d'Eyévéa grouille de Daedra. Shalidor est furieux. Il s'est rendu à la grand-salle de l'île pour évaluer la situation. Je vais devoir me frayer un chemin parmi les Daedra pour le rejoindre.",text="au centre d’Eyévéa. Depuis l’oratoire, suivez la route centrale vers le sud-ouest, puis vers l’ouest.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4002,objective="Éteignez l'incendie de la maison",step="Aéra est retournée chez elle, espérant s'y protéger. Je dois éteindre l'incendie à l'extérieur du bâtiment pour pouvoir y entrer et la trouver.",text="au nord-est de la place du village.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4018,objective="Parlez à Eiraki Givre-vent",step="Eiraki Givre-vent m'a retrouvé au manoir. Je dois lui dire ce qui s'est passé.",text="dans le vieux manoir, juste derrière le camp de pêche en face de la rivière qui entoure Vendeaume.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4018,objective="Parlez à Eiraki Givre-vent",step="Eiraki Givre-vent m'a retrouvée au manoir. Je dois lui dire ce qui s'est passé.",text="dans le vieux manoir, juste derrière le camp de pêche en face de la rivière qui entoure Vendeaume.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4030,objective="Parlez au capitaine Alhana",step="J'ai rassemblé des indices quant au sort des gardiennes : un livre d'hymnes, le journal d'un soldat et les étranges radotages de Leifnar, la sorcière. Je dois aller en parler au capitaine Alhana.",text="au Gardien de la maison du gardien à la partie ouest de la ville, près d'un puits.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4034,objective="Parlez à Haraldar",step="Je me suis réveillé après avoir goûté un des nouveaux hydromels. Maintenant que la brasserie de Voljar est remise en route, j'espère qu'Haraldar considère qu'il a honoré la mémoire de sa femme. Je dois lui parler.",text="à l'intérieur hydromellerie de Voljar.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4034,objective="Parlez à Haraldar",step="Je me suis réveillée après avoir goûté un des nouveaux hydromels. Maintenant que la brasserie de Voljar est remise en route, j'espère qu'Haraldar considère qu'il a honoré la mémoire de sa femme. Je dois lui parler.",text="à l'intérieur hydromellerie de Voljar.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4034,objective="Parlez à Haraldar",step="Les frères Lacime ont accès à la brasserie. Une fois que je leur aurai donné le livre de recettes et les ingrédients, ils devraient pouvoir recommencer à faire de l'hydromel. Je dois demander à Haraldar s'il a encore besoin d'aide.",text="à l'intérieur hydromellerie de Voljar.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4056,objective="Parlez au capitaine Alhana",step="La gardienne Ormi a libéré les soldats. Je devrais retourner chez la Gardienne et parler au capitaine Alhana.",text="au Gardien's maison, tout droit à partir du Bosquet de Kyne oratoire, au nord-ouest du lac de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4069,objective="Parlez au prince Irnskar",step="Je dois dire au prince Irnskar ce que j'ai fait pour améliorer ses relations avec le général Yeveth Noramil et Œil-d'acier.",text="sur les créneaux au-dessus de la porte est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4071,objective="Parlez à la reine Nurnhilde",step="J'ai atteint le chambre funéraire de la reine Nurnhilde. Elle se tient près de son sarcophage de pierre et semble bouleversée. Je dois lui parler.",text="dans la dernière chambre funéraire des ruines du côté nord de la caserne du fort Morvunskar.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4089,objective="Parlez à Haron",step="Avec la mort de Cirithor les Cerbères seront moins organisés et il sera plus facile de se défendre. Je devrais aller voir si Haron et Lanwaën sont prêts à retourner au village.",text="à l’intérieur de la caverne au firmament.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4089,objective="Parlez au thane sylvestre Nilara",step="Lanwaën est de retour au village. Je devrais rendre visite au thane sylvestre Nilara pour lui dire qu'Haron et Lanwaën vont bien.",text="dans sa maison à Noirbois.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4089,objective="Parlez au thane sylvestre Nilara",step="Lanwaën est de retour au village. Je devrais rendre visite au thane sylvestre Nilara pour lui dire que Haron et Lanwaën vont bien.",text="dans sa maison à Noirbois.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4089,objective="Parlez avec Haron",step="Avec la mort de Cirithor les Cerbères seront moins organisés et il sera plus facile de se défendre. Je devrais aller voir si Haron et Lanwaën sont prêts à retourner au village.",text="à l’intérieur de la caverne au firmament.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4089,objective="Parlez avec le thane sylvestre Nilara",step="Lanwaën est de retour au village. Je devrais rendre visite au thane sylvestre Nilara pour lui dire qu'Haron et Lanwaën vont bien.",text="dans sa maison à Noirbois.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4089,objective="Parlez avec le thane sylvestre Nilara",step="Lanwaën est de retour au village. Je devrais rendre visite au thane sylvestre Nilara pour lui dire que Haron et Lanwaën vont bien.",text="dans sa maison à Noirbois.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4091,objective="Parlez à la trameuse Indinaël",step="Je devrais dire à la trameuse Indinaël que j'ai brûlé les cadavres des spriggans et que leur duramen ne tombera pas entre les mains du Culte du Ver.",text="au centre d’Ouze.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4091,objective="Parlez à la trameuse Indinaël",step="Je dois découvrir ce que fait le totem d'Y'ffre et comprendre pourquoi la trameuse Indinaël voulait que je l'obtienne.",text="au centre de Ouze.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4091,objective="Parlez à la trameuse Indinaël",step="Je dois découvrir ce que fait un totem d'Y'ffre et comprendre pourquoi la trameuse Indinaël voulait que je l'obtienne.",text="au centre de Ouze.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4091,objective="Parlez à la trameuse Indinaël",step="Le gardien Celonron n'avait pas l'air de m'en vouloir de lui avoir drainé une partie de son essence spirituelle. Cependant, il a insisté sur le fait que je devais retourner vers la trameuse Indinaël rapidement.",text="au centre d’Ouze.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4091,objective="Parlez avec la trameuse Indinaël",step="Je devrais dire à la trameuse Indinaël que j'ai brûlé les cadavres des spriggans et que leur duramen ne tombera pas entre les mains du Culte du Ver.",text="au centre d’Ouze.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4091,objective="Parlez avec la trameuse Indinaël",step="Je dois découvrir ce que fait le totem d'Y'ffre et comprendre pourquoi la trameuse Indinaël voulait que je l'obtienne.",text="au centre de Ouze.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4091,objective="Parlez avec la trameuse Indinaël",step="Je dois découvrir ce que fait un totem d'Y'ffre et comprendre pourquoi la trameuse Indinaël voulait que je l'obtienne.",text="au centre de Ouze.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4091,objective="Parlez avec la trameuse Indinaël",step="Le gardien Celonron n'avait pas l'air de m'en vouloir de lui avoir drainé une partie de son essence spirituelle. Cependant, il a insisté sur le fait que je devais retourner vers la trameuse Indinaël rapidement.",text="au centre d’Ouze.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4095,objective="Parlez à Aspéra l'amie des géants",step="Aspéra l'amie des géants m'attend à l'extérieur de l'arène. Je dois lui parler.",text="à l'extérieur de arène de Berceroc au centre de Berceroc.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4095,objective="Parlez à Aspéra l'amie des géants",step="Aspéra s'est débrouillée pour atteindre l'arène avant moi. Elle veut me parler.",text="à l'extérieur de l'arène au milieu de Berceroc.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4096,objective="Adressez-vous à Valding",step="Je sais que Valding n'avait nullement l'intention de blesser qui que ce soit, mais il doit prendre la responsabilité de ses actes. Je dois lui parler pour m'assurer qu'il en prenne conscience.",text="à l'extérieur grotte de Bourberoc.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4096,objective="Adressez-vous à Valding",step="Valding le barde n'est qu'un vulgaire voleur. Mais il a promis de revenir à Bourberoc pour s'expliquer. Les ouvriers royaux décideront de son sont. Au moins, le luth enchanté est détruit.",text="à l'extérieur grotte de Bourberoc.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4096,objective="Parlez à Arvild Gris-ciel",step="J'ai dû m'évanouir. Je dois découvrir ce qui s'est passé.",text="à l'étage dans la salle de festin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4096,objective="Parlez à Arvild Gris-ciel",step="Personne n'a de souvenir clair de ce qui s'est passé, mais tous ont entendu le barde jouer avant que les choses ne tournent mal. Mais ce dernier a disparu.",text="à l'extérieur de la salle de festin en Bourberoc.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4101,objective="Parlez à Dalaneth",step="J'ai assassiné le chef, mais elle a eu le temps de blesser Dalaneth. Je dois m'assurer qu'elle peut retourner dans la vallée.",text="dans la longue maison du chef sur les falaises au sud de la vallée de Peinesang.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4101,objective="Parlez à l’émissaire de Z'en",step="L'émissaire de Z'en a tué Mathragor. Je dois en comprendre les raisons.",text="dans le sanctuaire de l'en à l'extrémité nord-ouest de la rivière vallée de Peinesang.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4101,objective="Parlez à l’émissaire de Z'en",step="La mort de Mathragor a mit fin à la violence dans la vallée de Peinesang. Je dois interroger l’émissaire de Z'en sur ce qui s'est passé au sanctuaire.",text="dans le sanctuaire de l'en à l'extrémité nord-ouest de la rivière vallée de Peinesang.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4101,objective="Parlez à l’émissaire de Z'en",step="Un étrange esprit est apparu au sanctuaire de Z'en. Il me faut lui parler.",text="dans le sanctuaire de l'en à l'extrémité nord-ouest de la rivière vallée de Peinesang.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4101,objective="Parlez à Mathragor",step="J'ai réussi à persuader Mathragor de cesser les actes violents. Je dois lui parler pour savoir ce qu'il prévoit ensuite.",text="dans le sanctuaire de la vallée de Peinesang.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4101,objective="Parlez à Mathragor",step="Je dois dire à Mathragor que le chaman Yarnag et le fils du chef ont trépassé. Il attend sûrement à la vallée, du côté des Drublog.",text="au sud de la vallée de Peinesang.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4101,objective="Parlez à Mathragor",step="L’émissaire de Z'en m'a demandé de dissuader Mathragor de maudire les Drublog. Il faut que je trouve un moyen de négocier avec Mathragor.",text="dans le sanctuaire de l'en à l'extrémité nord-ouest de la rivière vallée de Peinesang.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4101,objective="Parlez à Mathragor 1",step="J'ai réussi à persuader Mathragor de cesser les actes violents. Je dois lui parler pour savoir ce qu'il prévoit ensuite.",text="dans le sanctuaire de l'en à l'extrémité nord-ouest de la rivière vallée de Peinesang.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4101,objective="Parlez avec Dalaneth",step="J'ai assassiné le chef, mais elle a eu le temps de blesser Dalaneth. Je dois m'assurer qu'elle peut retourner dans la vallée.",text="dans la longue maison du chef sur les falaises au sud de la vallée de Peinesang.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4101,objective="Parlez avec l’émissaire de Z'en",step="L’émissaire de Z'en a tué Mathragor. Je dois en comprendre les raisons.",text="dans le sanctuaire de l'en à l'extrémité nord-ouest de la rivière vallée de Peinesang.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4101,objective="Parlez avec l’émissaire de Z'en",step="La mort de Mathragor a mit fin à la violence dans la vallée de Peinesang. Je dois interroger l’émissaire de Z'en sur ce qui s'est passé au sanctuaire.",text="dans le sanctuaire de l'en à l'extrémité nord-ouest de la rivière vallée de Peinesang.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4101,objective="Parlez avec l’émissaire de Z'en",step="Un étrange esprit est apparu au sanctuaire de Z'en. Il me faut lui parler.",text="dans le sanctuaire de l'en à l'extrémité nord-ouest de la rivière vallée de Peinesang.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4101,objective="Parlez avec l'émissaire de Z'en 1",step="La mort de Mathragor a mit fin à la violence dans la vallée de Peinesang. Je dois interroger l'émissaire de Z'en sur ce qui s'est passé au sanctuaire.",text="dans le sanctuaire de l'en à l'extrémité nord-ouest de la rivière vallée de Peinesang.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4106,objective="Parlez à Valéric",step="Je devrais retourner parler à Valéric voir ce qu'il veut faire ensuite.",text="dans son manoir dans la région nord de Wittestadr.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4108,objective="Parlez à Oraneth",step="Nous avons atteint le second lieu essentiel à l'histoire de la Dame Verte, la cascade à l'extérieur du village.\r\n\r\nNous devons rester sur nos gardes, car des loups-garous et des Cerbères rôdent dans les parages.",text="à la cascade au sud-est de Noirbois.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4108,objective="Parlez à Oraneth",step="Nous sommes arrivés au terrain d'entraînement de tir à l'arc où Oraneth va poursuivre son histoire sur la Dame Verte du moment.",text="au rayon d'angle du tir à l'arc près de Dernière aventure de Matthilde situé à l'est à partir de Noirbois.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4108,objective="Parlez avec Oraneth",step="Nous avons atteint le second lieu essentiel à l'histoire de la Dame Verte, la cascade à l'extérieur du village.\r\n\r\nNous devons rester sur nos gardes, car des loups-garous et des Cerbères rôdent dans les parages.",text="à la cascade au sud-est de Noirbois.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4108,objective="Parlez avec Oraneth",step="Nous sommes arrivés au terrain d'entraînement de tir à l'arc où Oraneth va poursuivre son histoire sur la Dame Verte du moment.",text="au rayon d'angle du tir à l'arc près de Dernière aventure de Matthilde situé à l'est à partir de Noirbois.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4111,objective="Parlez à Élandora",step="La zone est en flammes à cause de quelques feux stratégiquement placés. Malheureusement, « Sal » n'a jamais fait son apparition. Il me faut aller aux quais pour demander à Élandora si elle a une autre idée pour le retrouver.",text="sur le quai à l'ouest.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4111,objective="Parlez avec Élandora",step="La zone est en flammes à cause de quelques feux stratégiquement placés. Malheureusement, « Sal » n'a jamais fait son apparition. Il me faut aller aux quais pour demander à Élandora si elle a une autre idée pour le retrouver.",text="sur le quai à l'ouest.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4117,objective="Parlez au prince Irnskar",step="Le Pacte de Cœurébène est scellé. Le haut-roi Jorunn m'a demandé de retourner à la Redoute de Jorunn et d'en faire le récit au prince Irnskar.",text="au sommet de la porte orientale.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4123,objective="Parlez à Jorunn le Roi-scalde",step="Jorunn le roi scalde est réveillé. Je dois lui parler.",text="à l'autel de pierre en Arquebrumes.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4123,objective="Parlez à Jorunn le Roi-scalde",step="L'esprit brisé du roi Jorunn a été libéré et fait à nouveau un. Je dois lui parler avant de sortir de son rêve.",text="sur l'autel sur la plate-forme la plus haute de Arquebrumes.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4123,objective="Parlez à Jorunn le Roi-scalde",step="Le roi Jorunn est réveillé. Je dois lui parler.",text="à l'autel de pierre en Arquebrumes.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
