{quest=4129,objective="Parlez au second Valion",step="Apparemment le second Valion a capturé un Maormer sur le bateau et le soumet à un interrogatoire. Il me faut découvrir ce qu'il a appris au sujet du capitaine.",text="à bord du Ronde du Faucon, le navire amarré au nord de poche de Jode.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4129,objective="Parlez au second Valion",step="Apparemment second Valion a capturé un Maormer sur le bateau et le soumet à un interrogatoire. Il me faut découvrir ce qu'il a appris au sujet du capitaine.",text="à bord du navire amarré au nord de la poche de Jode.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4129,objective="Parlez au second Valion",step="Les Maormers ont enfermé le second en cage, mais je l'ai libéré. Il saura peut-être où le capitaine se trouve.",text="à la cage au nord-est de poche de Jode.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4130,objective="Parlez au capitaine Seritenya",step="J'ai détruit la géode d'anima dont l'archi-sorcière maormer se servait pour puiser les souvenirs du capitaine. Il faut que je lui parle pour m'assurer qu'elle va bien.",text="à l'intérieur bâillement d'Ogrim.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4130,objective="Parlez au capitaine Seritenya",step="J'ai détruit le géode d'anima dont l'archi-sorcière maormer se servait pour puiser les souvenirs du capitaine. Il faut que je lui parle pour m'assurer qu'elle va bien.",text="à l’intérieur du bâillement d’Ogrim.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4130,objective="Parlez au capitaine Seritenya",step="J'ai secouru le capitaine Seritenya et une partie de son équipage des ravisseurs maormers. Je vais aller vérifier si le capitaine a encore besoin de moi.",text="au sommet du chemin au sud du bâillement d’Ogrim.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4135,objective="Parlez au centurion Andrin",step="J'ai terrassé l’anachorète Garmar, qui semblait diriger le Culte du Ver à Faillaise. Malgré cela, un autre adepte a fui avec un fragment de Wuuthrad. Le centurion Andrin doit être averti de ces événements.",text="dans la cour à fort clos de la Fighters Guilde, directement en face du canal depuis la salle de l'artisanat.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4135,objective="Parlez au centurion Andrin",step="Le Culte du Ver cherche un fragment de Wuuthrad à Faillaise. Le capitaine Vivéka m'a dit de parler avec son officier supérieur une fois que j'aurais appris ce qui se passe. Peut-être qu'elle peut m'aider.",text="dans la cour fortifiée de la Guilde des chasseurs.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4135,objective="Parlez avec le centurion Andrin",step="J'ai terrassé l'anachorète Garmar, qui semblait diriger le Culte du Ver à Faillaise. Malgré cela, un autre adepte a fui avec un fragment de Wuuthrad. Le centurion Andrin doit être averti de ces événements.",text="dans la cour à fort clos de la Fighters Guilde, directement en face du canal depuis la salle de l'artisanat.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4135,objective="Parlez avec le centurion Andrin",step="Le Culte du Ver cherche un fragment de Wuuthrad à Faillaise. Le capitaine Vivéka m'a dit de parler avec son officier supérieur une fois que j'aurais appris ce qui se passe. Peut-être qu'elle peut m'aider.",text="dans la cour fortifiée de la Guilde des chasseurs.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4139,objective="Parlez à Jorunn le Roi-scalde",step="Thallik Verarche est mort, mais il a fait fusionner son esprit avec le géant fantomatique Sunmur, et brisé la légendaire hache Wuuthrad. Je devrais tout raconter à Jorunn.",text="sous un store dans son camp de toiles.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4142,objective="Parlez à la gardienne de Sylvanhenge Lara",step="Finoriell m'a parlé des intentions du Culte du Ver d'utiliser son âme afin de corrompre toutes les matrones de Sylvanhenge.\r\n\r\nIl me faut en informer immédiatement la gardienne de Sylvanhenge Lara.",text="au centre de Sylvanhenge.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4142,objective="Parlez à la gardienne de Sylvanhenge Lara",step="Un lien magique emprisonne Finoriëll. Elle veut que je demande à la gardienne de Sylvanhenge Lara comment lui venir en aide.",text="au plus profond du centre de Sylvanhenge.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4142,objective="Parlez avec la gardienne de Sylvanhenge Lara",step="Finoriëll m'a parlé des intentions du Culte du Ver d'utiliser son âme afin de corrompre toutes les matrones de Sylvanhenge.\r\n\r\nIl me faut en informer immédiatement la gardienne de Sylvanhenge Lara.",text="au centre de Sylvanhenge.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4142,objective="Parlez avec la gardienne de Sylvanhenge Lara",step="Un lien magique emprisonne Finoriëll. Elle veut que je demande à la gardienne de Sylvanhenge Lara comment lui venir en aide.",text="au plus profond du centre de Sylvanhenge.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4142,objective="Parlez avec la gardienne de Sylvanhenge Lara 1",step="Finoriëll m'a parlé des intentions du Culte du Ver d'utiliser son âme afin de corrompre toutes les matrones de Sylvanhenge.\n\nIl me faut en informer immédiatement la gardienne de Sylvanhenge Lara.",text="au centre de Sylvanhenge.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4143,objective="Parlez au Silvenar",step="Les liens des trameurs sont brisés. Je peux retourner voir le Silvenar pour déterminer la suite des événements. Il doit m'attendre en bas du Grand arbre.",text="au milieu de Silvenar.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4146,objective="Adressez-vous à Séla",step="J'ai décidé que Séla ne serait pas en sécurité au camp.",text="au camp à l'intérieur du cryptes oubliées.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4146,objective="Adressez-vous à Séla",step="J'ai décidé que Séla peut rester au camp sans danger.",text="dans le camp à l'intérieur de la cryptes oubliées.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4146,objective="Parlez à Séla",step="Danus, le chef des réfugiés, dit que le mari de Séla a contracté le fléau et qu'il a dû être abandonné dans les cryptes.",text="dans le camp à l’intérieur des cryptes oubliées.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4146,objective="Parlez à Séla",step="J'ai décidé que Séla ne serait pas en sécurité au camp.",text="au camp à l'intérieur du cryptes oubliées.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
