{quest=4153,objective="Parlez avec Aéra",step="Golun semble avoir été tué. Je dois parler avec Aéra en dehors du hall du thane pour un savoir plus.",text="au sommet des escaliers au centre de Nimalten.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4155,objective="Mettez un terme au sombre rituel",step="Arithiel invoque un atronach de flamme pour m'aider à interrompre le rituel. Je dois tuer les invocateurs dans le sanctuaire de Mauloch avant qu'ils n'arrivent à créer un portail pour son royaume.",text="à l'intérieur du autel de Mauloch à l'intérieur des ruines d'Abamath.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4155,objective="Mettez un terme au sombre rituel",step="J'ai sacrifié l'âme d'Arithiel à la géode d'anima. Avec la bénédiction de Boéthia, je dois tuer les invocateurs dans le sanctuaire de Mauloch avant qu'ils n'arrivent à créer un portail pour son royaume.",text="à l'intérieur du autel de Mauloch à l'intérieur des ruines d'Abamath.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4155,objective="Parlez à Arithiel",step="J'ai débloqué la porte qui mène à Abamath en disposant les pierres de welkynd dans les appliques. Je dois discuter de nos plans avec Arithiel.",text="au centre de Abamath.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4155,objective="Parlez à Arithiel",step="J'ai empêché le rituel du Culte du Ver, ce dont Boéthia se réjouit, mais j'ai dû sacrifier Arithiel en contrepartie.\r\n\r\nL'esprit d'Arithiel est apparu hors de la sortie du sanctuaire. Il serait judicieux de lui parler pour savoir ce qu'elle veut.",text="à l'extérieur de Abamath, autour des ruines du sud-est.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4155,objective="Parlez à Arithiel",step="J'ai épargné la vie d'Arithiel et utilisé la géode d'anima sur un adepte. Je devrais demander à Arithiel quoi faire ensuite.",text="à l'intérieur des ruines d'Abamath.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4155,objective="Parlez à Arithiel",step="J'ai épargné la vie d'Arithiel et utilisé la géode d'anima sur un adepte. Je devrais demander à un Arithiel quoi faire ensuite.",text="à l'intérieur des ruines d'Abamath.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4155,objective="Parlez à Arithiel",step="J'ai interrompu le rituel du Culte du Ver, et épargné la vie d'Arithiel. Je devrais lui parler pour lui demander ce qu'elle compte faire, maintenant.",text="à l'extérieur Abamath.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4155,objective="Parlez à Arithiel",step="Une âme est requise pour briser la géode d'anima et dégager le chemin pour le sanctuaire. D'après Boéthia, Arithiel est une traîtresse, mais je devrais d'abord lui parler avant de la sacrifier à cette pierre.",text="à l'intérieur des ruines d'Abamath.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4155,objective="Parlez à Arithiel",step="Une âme est requise pour briser le géode d'anima et dégager le chemin pour le sanctuaire. D'après Boéthia, Arithiel est une traîtresse, mais je devrais d'abord lui parler avant de la sacrifier à cette pierre.",text="à l’intérieur des ruines d’Abamath.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4155,objective="Parlez à Arithiel",step="Une barrière d'énergie bloque l'entrée du sanctuaire dans lequel le Culte du Ver prépare un rituel pour invoquer Mauloch. Je devrais demander conseil auprès d'Arithiel.",text="à l'intérieur des ruines d'Abamath.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4160,objective="Parlez avec Hallfrida",step="J'ai récupéré Fracture, prouvant ainsi que Thorulf est un menteur et un traître. Je devrais prévenir Hallfrida.",text="à l’étage du manoir du thane, au fort du Heaume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4160,objective="Parlez avec Hallfrida",step="Le sergent Sjarakki a signalé le début d'un autre assaut des morts-vivants. Je dois parler avec Hallfrida.",text="à l’étage supérieur du manoir du thane, au fort du Heaume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4160,objective="Parlez avec Hallfrida",step="Une des femmes du hall a demandé à me parler à l'extérieur.",text="à l'extérieur du manoir du thane à fort du Heaume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4165,objective="Parlez à la gardienne de Sylvanhenge Lara",step="J'ai récupéré la graine depuis les racines de Sylvanhenge. Combinée avec la puissance de l'âme de Finoriëll, elle devrait permettre de renforcer Sylvanhenge contre les attaques du Culte du Ver.",text="au milieu de Sylvanhenge.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4165,objective="Parlez à la gardienne de Sylvanhenge Lara",step="J'ai retrouvé l'âme de Finoriëll, mais elle a été gravement affaiblie. Pour sa survie, je dois trouver un moyen de la guérir avant qu'il ne soit trop tard.",text="au milieu de Sylvanhenge.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4165,objective="Parlez avec la gardienne de Sylvanhenge Lara",step="J'ai récupéré la graine depuis les racines de Sylvanhenge. Combinée avec la puissance de l'âme de Finoriëll, elle devrait permettre de renforcer Sylvanhenge contre les attaques du Culte du Ver.",text="au milieu de Sylvanhenge.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4165,objective="Parlez avec la gardienne de Sylvanhenge Lara",step="J'ai retrouvé l'âme de Finoriëll, mais elle a été gravement affaiblie. Pour sa survie, je dois trouver un moyen de la guérir avant qu'il ne soit trop tard.",text="au milieu de Sylvanhenge.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4173,objective="Parlez avec Hallfrida",step="Hallfrida, à présent thane du Heaume, attend dans le hall du manoir pour me parler.",text="au manoir du thane de fort du Heaume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4173,objective="Parlez avec Hallfrida",step="Les envahisseurs sont vaincus. Je devrais sortir de la remise au plus tôt pour savoir pourquoi dame Hallfrida m'appelle.",text="près des escaliers de manoir du thane en fort du Heaume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4173,objective="Parlez avec Hallfrida",step="Thorulf est mort, mais le thane Unnvald s'est sûrement suicidé à présent. Je dois m'assurer que Hallfrida va bien.",text="au manoir du thane de fort du Heaume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4173,objective="Parlez avec Unnvald",step="Le thane Unnvald Main-de-fer croît que le fragment de Wuuthrad que Thorulf lui a donné est plus ou moins maudit. Dès qu'il me l'a donné, sa crainte des jarls est passée. Il veut me parler à nouveau.",text="dans sa chambre, au dernier étage du manoir du thane, au fort du Heaume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4173,objective="Parlez avec Unnvald",step="Pendant que je parlais avec le thane Unnvald, il était affligé d'une violente migraine. Je dois encore lui parler.",text="dans sa chambre au dernier étage du manoir du thane à fort du Heaume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4174,objective="Parlez à Tovisa",step="Il faut que je retourne voir Tovisa, et que je lui dise que je vais aller dans la mine.",text="au camp de prisonniers à côté de sanctuaire d'Alona ans, à mine de la Galerne.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4174,objective="Parlez à Tovisa",step="J'ai découvert que les Crevassais adorent une congrégation de harfreuses. Je dois prévenir Tovisa.",text="au camp de prisonniers à côté de sanctuaire d'Alona ans, à mine de la Galerne.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4174,objective="Parlez avec Tovisa",step="Il faut que je retourne voir Tovisa, et que je lui dise que je vais aller dans la mine.",text="au camp de prisonniers à côté de sanctuaire d'Alona ans, à mine de la Galerne.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4174,objective="Parlez avec Tovisa",step="J'ai découvert que les Crevassais adorent une congrégation de harfreuses. Je dois prévenir Tovisa.",text="au camp de prisonniers à côté de sanctuaire d'Alona ans, à mine de la Galerne.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4174,objective="Trouvez tovisa",step="Je dois trouver Tovisa et la sortir d'ici.",text="à l'intérieur de la mine de la Galerne.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4174,objective="Trouvez Tovisa",step="Je dois trouver Tovisa et la sortir de là avant qu'un drame ne se produise !",text="à l'intérieur de la mine de la Galerne.",source="Immersive Quests FR local : objectif et étape explicites"},
