{quest=4296,objective="Parlez à Lyris",step="La porte de la cellule du Prophète est fermée. Lyris saura peut-être ce qu'il convient de faire à présent.",text="près de la cellule du Prophète qui a une porte aux bords hérissés de pointes, et est située entre deux cristaux de flamme froide.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4296,objective="Parlez à Lyris",step="La porte de la cellule du Prophète est scellée. Je devrais voir si Lyris a une idée de ce que nous devons faire ensuite.",text="près de la cellule du Prophète qui a une porte aux bords hérissés de pointes, et est située entre deux cristaux de flamme froide.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4300,objective="Parlez à l’aldarque Colaste",step="Les Divins m'ont montré les ténèbres dans lesquelles Estre avait sombré. Je devrais m'adresser une dernière fois à Colaste.",text="dans le sanctuaire central, au cœur des ruines.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4300,objective="Parlez avec l’aldarque Colaste",step="Les Divins m'ont montré les ténèbres dans lesquelles Estre avait sombré. Je devrais m'adresser une dernière fois à Colaste.",text="dans le sanctuaire central, au cœur des ruines.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4326,objective="Assistez à la condamnation d'Éranamo",step="J'ai parlé à Rolancano et accepté de le laisser appliquer la sentence de mort d'Éranamo lui-même.",text="près de l'oratoire de Quendeluun.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4326,objective="Assistez à la condamnation d'Éranamo",step="J'ai parlé à Rolancano et l'ai convaincu d'épargner la vie de son fils.",text="près de l'oratoire de Quendeluun.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4329,objective="Parlez à Baham",step="Baham est arrivée en courant avec d'autres élèves. Je devrais lui reparler.",text="à l'avant-poste baandari au nord du complexe du collège.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4329,objective="Parlez à Baham",step="J'ai distribué les pansements et fournitures que Nurad m'a remis. Il est temps de retourner parler à Baham.",text="près du puits, à l'ouest du collège.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4329,objective="Parlez à Tanion",step="Baham m'a dit de commencer mon enquête en parlant à Tanion, le principal de l'école. J'imagine que je pourrais aussi poser à Baham quelques questions de détail.",text="sur les marches du bâtiment principal de l'école, au centre du complexe du collège.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4331,objective="Parlez à Ohmonir",step="J'ai répondu aux énigmes, et je devrais parler à Ohmonir pour savoir quoi faire désormais.",text="sur l'île d'Errinorne, juste à l'est du quai.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4331,objective="Parlez à Ohmonir",step="Je devrais parler à Ohmonir.",text="sur l'île d'Errinorne, juste à l'est du quai.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4331,objective="Parlez à Ohmonir",step="Pour ma première épreuve, je dois prouver mon intelligence. Je devrais aller parler à Ohmoni pour débuter cette épreuve.",text="sur l'île d'Errinorne, juste à l'est du quai.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4331,objective="Parlez à Varustantë",step="J'ai réussi la première épreuve d'endurance. Je devrais parler à Varustantë.",text="près des tentes au sud du centre de l'île d'Errinorne.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4331,objective="Parlez à Varustantë",step="Ma prochaine épreuve sera une épreuve d'endurance. Je dois parler à Varustantë pour commencer.",text="sur la plateforme nord-ouest de l'île d'Errinorne.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4337,objective="Parlez à Jurak-dar",step="Jurak-dar veut me parler avant que nous ne nous rendions dans les ruines.",text="à l’intérieur de Bëlarata.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4337,objective="Parlez à Jurak-dar",step="L'esprit qui hantait Belarata n'est plus. Je devrais parler à Jurak-dar.",text="à l’intérieur de Bëlarata.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4337,objective="Parlez à Jurak-dar",step="Les esprits qui hantaient Belarata ont trouvé le repos. Je devrais parler à Jurak-dar.",text="à l’intérieur de Bëlarata.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
