{quest=4341,objective="Parlez à dame Clarique",step="J'ai pu secourir Merien Sellan, avec l'aide de Tamien. Je devrais me présenter devant Dame Clarique et l'informer de ce qu'il s'est passé.",text="à leur place juste à l'extérieur des restes du village.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4341,objective="Parlez à Tamien Sellan",step="Merien Sellan a mis au point un plan pour arrêter le Culte de Sangrépine. Je devrais parler à son fils et découvrir ce qu'il en pense.",text="dans sa maison surplombant la mer.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4347,objective="Parlez à Bernt",step="À l'intérieur de la taverne, les villageois délivrés ont assailli le mystérieux thane, qui s'est révélé être un Daedra. Je dois trouver Bernt et lui parler.",text="dans l'étage dans le Pichet sans fond.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4347,objective="Parlez à Bernt",step="Je suis retourné au Pichet sans fond. Je devrais trouver Bernt, et lui demander ce qu'il compte faire à présent.",text="À l'étage.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4347,objective="Parlez à Bernt",step="Je suis retournée au Pichet sans fond. Je devrais trouver Bernt, et lui demander ce qu'il compte faire à présent.",text="À l'étage.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4347,objective="Parlez à Nelhilda",step="Il y a un problème à la taverne. J'ai rencontré un Nordique appelé Bernt, qui m'a poussé à parler à sa fille, Nelhilda. C'est feu son mari qui a écrit ce message. Je devrais la trouver à l'étage.",text="à l'étage dans la chambre.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4352,objective="Parlez à Télenger l'artificier",step="J'ai trouvé Télenger l'artificier enfermé dans une salle forte, au niveau inférieur de la bibliothèque. Je devrais lui parler.",text="dans la salle forte au niveau inférieur de la bibliothèque, derrière la grande porte ayléide tout au fond.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4352,objective="Trouvez Télenger l'artificier",step="Dame Clarisse Laurent m'a dit que Télenger l'artificier avait fait une découverte importante, mais elle ne se rappelle plus laquelle. Je dois trouver Télenger.",text="à l’intérieur de la bibliothèque, dans une des pièces au niveau du balcon.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4352,objective="Trouvez Télenger l'artificier",step="Télenger l'artificier s'est enfermé dans une salle forte au niveau inférieur de la bibliothèque, afin de ralentir les effets du sort qui assaillait son esprit. Je devrais aller le chercher là-bas.",text="au niveau inférieur de la bibliothèque, accessible par le tunnel au centre de la pièce principale.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4355,objective="Parlez au capitaine Landarë",step="Le sergent Artinairë a dit que les Daedra avaient repris leur attaque. Je devrais demander au capitaine Landarë ce qu'elle compte faire.",text="dans le manoir en ruines à l'extrémité ouest de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4355,objective="Parlez avec le capitaine Landarë",step="Le sergent Artinairë a dit que les Daedra avaient repris leur attaque. Je devrais demander au capitaine Landarë ce qu'elle compte faire.",text="dans le manoir en ruines à l'extrémité ouest de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4358,objective="Parlez au capitaine Un-Œil",step="Le capitaine Un-Œil est à la porte. Je devrais lui parler.",text="sur le Journal du Tsona-Ei que j'ai trouvé.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4361,objective="Parlez à Élanwë",step="Je devrais expliquer à Élanwë ce qu'il est advenu de son fils.",text="sur la plateforme centrale des ruines.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4364,objective="Parlez à Angof",step="J'ai décidé de sauver Angof du jeu de l'Observateur. C'était le choix logique, si je veux vaincre Molag Bal. Je devrais parler à Angof et l'envoyer à la Cité creuse.",text="au sud-ouest des Falaises du désastre.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4364,objective="Parlez à Angof",step="J'ai décidé de tenir tête à l'Observateur et faire sortir tous les participants du jeu. J'ai à présent les mages et Angof avec moi. Je devrais parler à Angof et les envoyer tous à la Cité creuse.",text="avec les mages, au sud-ouest des Falaises du désastre.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4369,objective="Parlez à Mim",step="En arrivant à l'entrée de la vigie de l'Observateur, j'ai remarqué Mim qui m'attendait. Je devrais aller lui parler.",text="à l'extrémité est des champs de bataille à l'intérieur du Falaises du désastre.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4369,objective="Parlez à Mim",step="J'ai décidé de sauver les membres de la guilde des Mages. Je devrais parler à Mim et les envoyer à la Cité creuse.",text="avec Juline et Relmus, au sud-ouest des Falaises du désastre.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4369,objective="Parlez à Thallik",step="J'ai décidé de sauver Thallik du jeu de l'Observateur. C'était le choix logique, si je veux vaincre Molag Bal. Je devrais parler à Thallik et l'envoyer à la Cité creuse.",text="au sud-ouest des Falaises du désastre.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4369,objective="Parlez à Thallik",step="J'ai décidé de tenir tête à l'Observateur et faire sortir tous les participants du jeu. J'ai à présent les mages et Angof avec moi. Je devrais parler à Thallik et les envoyer tous à la Cité creuse.",text="avec les mages, au sud-ouest des Falaises du désastre.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4370,objective="Parlez à Estre",step="J'ai décidé de sauver dame Estre du jeu de l'Observateur. C'était le choix logique, si je compte vraiment vaincre Molag Bal. Je devrais parler à Estre et l'envoyer à la Cité creuse.",text="au sud du Falaises du désastre.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4370,objective="Parlez à Estre",step="J'ai décidé de tenir tête à l'Observateur et faire sortir tous les participants du jeu. J'ai à présent les mages et Estre avec moi. Je devrais parler à Estre et les envoyer tous à la Cité creuse.",text="au sud du Falaises du désastre.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4370,objective="Parlez à Relmus",step="En arrivant à l'entrée de la vigie de l'Observateur, j'ai remarqué Relmus qui m'attendait. Je devrais aller lui parler.",text="devant l’antichambre du champ de bataille, à l’entrée de la vigie de l’Observateur.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4370,objective="Parlez à Relmus",step="J'ai décidé de sauver les membres de la guilde des Mages. Je devrais parler à Relmus et les envoyer à la Cité creuse.",text="au sud du Falaises du désastre.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4371,objective="Parlez à An-Jeen-Sakka",step="J'ai convaincu les érudits que ma décision était la bonne, et aidé à mettre fin au débat concernant le sort de l'Hist d'Haj Uxith. Je devrais parler à An-Keen-Sakka pour le prévenir que l'Hist restera en vie.",text="au sommet des escaliers, à l’extrémité ouest de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4371,objective="Parlez au sylvegarde Xohaneel",step="À présent que la gardienne Xohaneel a fini sa conversation avec An-Jeen-Sakka, je devrais lui parler pour savoir ce qu'on attend de moi.",text="au nord de l’oratoire de Haj Uxith, près des torches à l’est de l’Hist.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4371,objective="Parlez au sylvegarde Xohaneel",step="J'ai aidé à résoudre le différend concernant le sort de l'His d'Haj Uxith. J'ai détruit l'éclat vampirique, ce qui condamne l'Hist à mort. Je devrais parler à Xohaneel avant de partir.",text="sur le côté ouest de l'arbre Hist, au nord-ouest de la ville oratoire.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4371,objective="Parlez au sylvegarde Xohaneel",step="Je peux accomplir les épreuves d'Haj Uxith dans l'ordre qui me convient. Je devrais parler à la sylvegarde Xohaneel pour commencer l'épreuve de l'esprit, ou à An-Jeen-Sakka pour commencer l'épreuve du corps.",text="à l'est de l'arbre Hist, aux flambeaux au nord de l’oratoire.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4371,objective="Parlez au sylvegarde Xohaneel",step="Je peux accomplir les épreuves d'Haj Uxith dans l'ordre qui me convient. Je devrais parler à la sylvegarde Xohaneel pour commencer l'épreuve de l'esprit, ou à l'An-Jeen-Sakka pour commencer l'épreuve du corps.",text="à l'est de l'arbre Hist, aux flambeaux au nord de l’oratoire.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4371,objective="Parlez au sylvegarde Xohaneel",step="Je peux accomplir les épreuves d'Haj Uxith dans l'ordre qui me convient. Je devrais parler à la sylvegarde Xohaneel pour commencer l'épreuve de l'esprit, ou au An-Jeen-Sakka pour commencer l'épreuve du corps.",text="à l'est de l'arbre Hist, aux flambeaux au nord de l’oratoire.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4371,objective="Parlez au sylvegarde Xohaneel 1",step="J'ai aidé à résoudre le différend concernant le sort de l'His d'Haj Uxith. J'ai détruit l'éclat vampirique, ce qui condamne l'Hist à mort. Je devrais parler à Xohaneel avant de partir.",text="sur le côté ouest de l'arbre Hist, au nord-ouest de la ville oratoire.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4371,objective="Vainquez le champion",step="Je dois vaincre le champion des érudits pour les convaincre que j'ai raison.",text="dans l'extrémité ouest de la ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4371,objective="Vainquez le champion",step="Je dois vaincre le champion des guerriers pour les convaincre que j'ai raison.",text="dans l'extrémité ouest de la ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4371,objective="Vainquez le champion 1",step="Je dois vaincre le champion des érudits pour les convaincre que j'ai raison.",text="dans l'extrémité ouest de la ville.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4388,objective="Parlez à Aldyna",step="J'ai accepté de ramener à Aldyna ses objets volés : ses colifichets et son esclave, Suriel.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4388,objective="Parlez à Aldyna",step="J'ai accepté de rendre à Aldyna ses objets volés : je devrais lui parler avant son départ.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4388,objective="Parlez à Aldyna",step="J'ai acheté la liberté de Suriel. Je dois parler avec Aldyna pour m'assurer qu'il ne reviendra pas sur notre accord.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4388,objective="Parlez à Aldyna",step="Je pense avoir convaincu Aldyna d'oublier Suriel et de la laisser avec ses objets volés.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4388,objective="Parlez à aldyna 1",step="J'ai accepté de ramener à Aldyna ses objets volés : ses colifichets et son esclave, Suriel.",text="près du bateau amarré dans les marais du sud-est.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4388,objective="Parlez à Aldyna 1",step="J'ai accepté de rendre à Aldyna ses objets volés : je devrais lui parler avant son départ.",text="près du bateau amarré dans les marais du sud-est.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4388,objective="Parlez à Suriel",step="J'ai donné de l'argent à Suriel pour qu'elle achète sa liberté sans avoir besoin de voler son ancien maître. Aldyna n'appréciera sûrement pas la tournure des événements.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4388,objective="Parlez à Suriel",step="Je pense avoir convaincu Aldyna d'oublier son ancienne esclave. Je devrais parler à Suriel avant son départ.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4388,objective="Parlez avec Aldyna",step="J'ai accepté de ramener à Aldyna ses objets volés : ses colifichets et son esclave, Suriel.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4388,objective="Parlez avec Aldyna",step="J'ai accepté de rendre à Aldyna ses objets volés : je devrais lui parler avant son départ.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4388,objective="Parlez avec Aldyna",step="J'ai acheté la liberté de Suriel. Je dois parler avec Aldyna pour m'assurer qu'il ne reviendra pas sur notre accord.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4388,objective="Parlez avec Aldyna",step="Je pense avoir convaincu Aldyna d'oublier Suriel et de la laisser avec ses objets volés.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4388,objective="Parlez avec Aldyna 1",step="J'ai accepté de ramener à Aldyna ses objets volés : ses colifichets et son esclave, Suriel.",text="près du bateau amarré dans les marais du sud-est.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4388,objective="Parlez avec Aldyna 1",step="J'ai accepté de rendre à Aldyna ses objets volés : je devrais lui parler avant son départ.",text="près du bateau amarré dans les marais du sud-est.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4388,objective="Parlez avec Suriel",step="J'ai donné de l'argent à Suriel pour qu'elle achète sa liberté sans avoir besoin de voler son ancien maître. Aldyna n'appréciera sûrement pas la tournure des événements.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4388,objective="Parlez avec Suriel",step="Je pense avoir convaincu Aldyna d'oublier son ancienne esclave. Je devrais parler à Suriel avant son départ.",text="près du bateau amarré dans les marais du sud-est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4392,objective="Parlez à Skordo",step="J'ai survécu à la chute dans la Tour des mensonges. Maintenant, je devrais tâcher de trouver Skordo. Gwilir m'a laissé entendre qu'il pourrait me mettre au courant de ce qui se passe dans la prison.",text="près du petit pont de bois au-dessus de l’eau azurée, au nord-ouest du point de chute. Il s’appuie contre une poutre, sous une caisse suspendue.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4392,objective="Parlez à Skordo",step="Les membres de la guilde des Guerriers se sont évadés de la Tour des mensonges et comptent se réorganiser à la Cité creuse. Je devrais aller trouver Skordo, il veut me parler.",text="au rond-point du chemin qui part au nord-ouest de la Cité creuse.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4399,objective="Parlez à Faraniël",step="Autour d'un feu de camp encore allumé, j'ai trouvé l'un des membres de la guilde des Guerriers. Il était mort, et Faraniël se tenait penché sur son cadavre. Elle affirme que ce n'est pas elle qui l'a tuée. Je devrais lui parler, pour découvrir ce qu'elle sait.",text="au feu de camp en feu à mi-chemin entre le Oubliettes obscures et le camp abandonné sur la route juste après l’oratoire de la Bibliothèque crépusculaire.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4399,objective="Parlez à Faraniël",step="Le sergent Kamu essayait d'entrer dans la tour en lisière de cette sombre forêt. La lamie et l'Elfe des bois affirment tous les deux connaître une entrée. Je devrais décider auquel je préfère demander de l'aide.",text="juste à l’est des Oubliettes obscures.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4409,objective="Trouvez une grenouille",step="Je devrais obtenir une grenouille auprès d'une personne présente à la course.",text="À l'est de la forge du Veilleur, vous pourriez chercher les dresseurs rassemblés autour de la piste.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4409,objective="Trouvez une grenouille",step="Ma grenouille n'a pas gagné la course. Je devrais en trouver une autre.",text="À l'est de la forge du Veilleur, vous pourriez chercher les dresseurs rassemblés autour de la piste.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4431,objective="Parlez à Néramo",step="Je devrais parler du casse de Kaleen à Néramo. Il a une dette envers moi depuis que je l'ai aidé à Bthzark.",text="près des ponts et de l’entrée sud des ruines de Bthzark.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4431,objective="Parlez à Néramo",step="Maintenant que nous sommes à l'intérieur de Bthzark, Néramo souhaite me parler.",text="près de l’entrée principale des ruines de Bthzark.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4431,objective="Parlez à Néramo",step="Néramo recherche quelque chose dans ces ruines. Son assistant m'a dit d'aller lui parler pour en savoir plus. Je devrais aller le voir près de l'entrée.",text="à l’ouest de Port Hunding, près de la route du Port des saints.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Examinez le coffre",step="Shalidor a indiqué une sorte de couronne dans le coin de la pièce. Je devrais y jeter un œil.",text="dans un coin de la salle, du côté de l’estrade contre le mur : le coffre ouvragé y repose.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Explorez Vuldngrav",step="Après avoir survécu au Draugr, Korthor m'a appelé. Je devrais chercher son tombeau. Il a peut-être la fourchette que je recherche.",text="dans les profondeurs du tombeau, au-delà de la salle du coffre.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Explorez Vuldngrav",step="Après avoir survécu au Draugr, Korthor m'a appelée. Je devrais chercher son tombeau. Il a peut-être la fourchette que je recherche.",text="dans les profondeurs du tombeau, au-delà de la salle du coffre.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Parlez à Haskill",step="Après avoir obtenu la fourchette, Haskill est apparu. Je devrais écouter ce qu'il a à dire.",text="dans les profondeurs de Vuldngrav, aux abords du lieu où vous avez affronté Korthor.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Parlez à Haskill",step="Après avoir obtenu le bâton, Haskill est apparu. Je devrais lui parler.",text="aux abords de la tombe de Maleel.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Parlez à Haskill",step="Haskill attendait mon arrivée sur les îles. Je devrais lui parler et découvrir ce que Shéogorath m'a réservé.",text="dans la cour du domaine où le portail vous a conduit.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Parlez à Shalidor",step="J'ai activé les deux sceaux en face des ruines. Shalidor saura peut-être comment activer les deux qui se trouvent derrière.",text="dans la vallée, avant les statues encore inactives à l’arrière.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Parlez à Shalidor",step="Maintenant que je suis arrivé à Asakala, je devrais parler à Shalidor de cet endroit.",text="près de votre point d’arrivée à Asakala.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Parlez à Shalidor",step="Maintenant que je suis arrivée à Asakala, je devrais parler à Shalidor de cet endroit.",text="près de votre point d’arrivée à Asakala.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Parlez à Shéogorath",step="À mon retour sur les îles Trémensides, Shéogorath m'attendait. Je devrais lui parler.",text="dans la cour du domaine des îles Trémensides.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Parlez à Shéogorath",step="J'ai testé le bâton de Shéogorath. Je devrais lui parler.",text="dans la cour du domaine des îles Trémensides.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Récupérez des essences",step="Je dois collecter des essences que je déposerai dans le sceau du Scarabée de l'une des statues. Shalidor m'a appris un sort qui me permettra d'attirer les essences à moi, mais je ne peux en collecter que quatre à la fois.",text="dans la vallée, parmi les petites lueurs au-dessus du sable.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Récupérez le bâton",step="Le tombeau étant ouvert, je peux maintenant y entrer et tuer Maleel pour récupérer le bâton.",text="auprès de Maleel, dans sa sépulture.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Récupérez le livre",step="Shéogorath m'a dit de prendre le livre. Enfin ! Il est temps de tourner la page.",text="sur les piédestaux près de Shéogorath : le livre flotte au-dessus de son support.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4435,objective="Retrouvez la fourchette",step="J'ai rejoint la tombe de Korthor. Il est temps de récupérer la fourchette... coûte que coûte.",text="auprès de Korthor, au fond de la sépulture.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4441,objective="Parlez à Pirondil",step="Pirondil est ici, en train de menacer Byz. Je dois lui parler.",text="aux abords de la tanière du chef.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4449,objective="Parlez à Néramo",step="Je dois parler à Néramo pour savoir quoi faire.",text="au sanctuaire intérieur de Chute de Carzog, une ruine d'Ayleid dans le nord-est de Betnikh.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4449,objective="Parlez à Néramo",step="Les adeptes de Sangrépine sont dans les ruines. Ils ont libéré une armée spectrale qui décime les Orques. Pour les arrêter, il faut que j'arrive à savoir comment ils ont fait.",text="près du pont ayléide menant à la Chute de Carzog, dans le nord-est de Betnikh.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4452,objective="Parlez à la Dame Verte",step="Je dois parler à la dame Verte de ses plans. Avec le Silvenar peut-être captif, et sa ville occupée par le Limier, elle pourrait bien avoir à nouveau besoin de mon aide.",text="à l’entrée de l’arène de Dra’bul.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4452,objective="Parlez à la Dame Verte",step="Je dois parler à la dame Verte de son prochain plan d'attaque. Puisque le Silvenar est peut-être captif et que ce « limier » occupe sa ville, elle aura sans doute à nouveau besoin de mon aide.",text="à l’entrée de l’arène de Dra’bul.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4453,objective="Parlez à Naryu Virian",step="Je me suis emparé d'une bouteille de vin de la maison Drès. Il me faut maintenant l'apporter à Naryu pour pouvoir mettre son plan à exécution.",text="à l'intérieur Nix enflammé discothèques.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4453,objective="Parlez à Naryu Virian",step="Je me suis emparée d'une bouteille de vin de la maison Drès. Il me faut maintenant l'apporter à Naryu pour pouvoir mettre son plan à exécution.",text="à l'intérieur Nix enflammé discothèques.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4453,objective="Parlez à Naryu Virian",step="Naryu est arrivée alors que je découvrais une trappe dérobée sous un tapis, dans la propriété des Drès. Il me faut lui demander quoi faire de cette découverte.",text="dans la ferme ferme de la maison Drès.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4454,objective="Parlez à Jakarn",step="Jakarn est près de la sortie de la Tombe. Je devrais lui parler.",text="près de la sortie des tunnels.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4454,objective="Parlez à Jakarn",step="Je devrais parler à Jakarn.",text="près de la petite tour à l’est du palais, à côté du puits et de l’écurie.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4454,objective="Parlez à Jakarn",step="Je devrais parler à Jakarn. Il est à l'auberge.",text="à l’auberge.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4454,objective="Parlez à Jakarn",step="Je devrais parler à Jakarn pour savoir quoi faire ensuite.",text="dans les niveaux supérieurs des mines au nord de Port Hunding. Les torches ornées de crânes servent de repères.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4454,objective="Trouvez Jakarn",step="J'ai le trésor de Jakarn. Je devrais le retrouver sur la plage en face de la mine.",text="sur la plage en face de la mine.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4454,objective="Trouvez Jakarn",step="Maintenant que je suis dans la prison, je dois trouver Jakarn.",text="dans la prison.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4460,objective="Parlez à Shazah",step="Il faut que je parle à Shazah pour en savoir plus sur ce qui s'est passé au fort de la Veillée.",text="dans la chambre haute de l'arbre à droite, juste à l'intérieur des portes en ruines.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4460,objective="Parlez à Shazah",step="La première Grande Crinière m'a accordé sa bénédiction. Il faut que je reparle à Shazah.",text="dans l'arbre central.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4461,objective="Parlez à Khali",step="Nous avons coupé la source des Dro-m'Athra. Je dois parler à Khali.",text="dans l'évidement le plus profond de la crevasse à l'intérieur de fort de la Veillée.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4461,objective="Parlez à Khali",step="Une autre barrière bloque notre chemin. Je devrais parler à Khali.",text="à l’intérieur de Khaj Rawlith, au fort de la Veillée.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4461,objective="Parlez à Shazah",step="Nous avons coupé la source des Dro-m'Athra. Je dois parler à Shazah.",text="dans l'évidement le plus profond de la crevasse à l'intérieur de fort de la Veillée.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4461,objective="Purgez l'énergie des Dro-m'Athra",step="J'ai découvert la poche de ténèbres qui a permis aux Dro-m'Athra de pénétrer dans le fort. Il est temps de la sceller.",text="dans l'évidement le plus profond de la crevasse à l'intérieur de fort de la Veillée.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4466,objective="Parlez à Jakarn",step="J'ai trouvé Jakarn dans une cellule de prison du chef Bhosek. Si je le sors de là, il acceptera peut-être d'aider Kaleen pour son casse.",text="dans une cellule de la prison du chef Bhosek.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4466,objective="Parlez au capitaine Kaleen",step="Le capitaine Kaleen a besoin de talents particuliers pour le casse qu'elle prépare. Elle veut que je l'aide à recruter un ou plusieurs membres de cette équipe. Si je me lance, je serai engagé dans ce travail.",text="parmi les marins qui boivent au nord des quais de Port Hunding.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4468,objective="Parlez à Frédérique Lynielle",step="J'ai détruit les abominations et brisé le pouvoir du culte sur les morts brétons. Je dois trouver Frédérique Lynielle et lui parler.",text="à l'extrémité ouest de Sombrechamp, par une petite ruine sur la plage.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4468,objective="Parlez à Frédérique Lynielle",step="J'ai rechargé le bâton. Maintenant, je dois aller parler à Frédérique Lynielle dans le cimetière.",text="à l'entrée de la tombe centrale en Sombrechamp.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4468,objective="Parlez au roi Rénuic",step="Je dois découvrir le rapport entre la vision du roi Rénuic et le plan de conquête de Sangrépine sur l'île.",text="près des petites ruines sur la plage la plus occidentale de Sombrechamp.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4468,objective="Parlez au roi Rénuic",step="Le roi Rénuic m'a montré comment son royaume est tombé devant les Orques Montemer. Il m'a aussi parlé d'une vieille arme ayléide cachée quelque part sur l'île.",text="près des petites ruines sur la plage la plus occidentale de Sombrechamp.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4468,objective="Parlez au roi Rénuic 1",step="Je dois découvrir le rapport entre la vision du roi Rénuic et le plan de conquête de Sangrépine sur l'île.",text="près des petites ruines sur la plage la plus occidentale de Sombrechamp.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4468,objective="Parlez au roi Rénuic 1",step="Le roi Rénuic m'a montré comment son royaume est tombé devant les Orques Montemer. Il m'a aussi parlé d'une vieille arme ayléide cachée quelque part sur l'île.",text="près des petites ruines sur la plage la plus occidentale de Sombrechamp.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4468,objective="Parlez avec Frédérique Lynielle",step="J'ai détruit les abominations et brisé le pouvoir du culte sur les morts brétons. Je dois trouver Frédérique Lynielle et lui parler.",text="à l'extrémité ouest de Sombrechamp, par une petite ruine sur la plage.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4468,objective="Parlez avec Frédérique Lynielle",step="J'ai rechargé le bâton. Maintenant, je dois aller parler à Frédérique Lynielle dans le cimetière.",text="à l'entrée de la tombe centrale en Sombrechamp.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4468,objective="Parlez avec le roi Rénuic",step="Je dois découvrir le rapport entre la vision du roi Rénuic et le plan de conquête de Sangrépine sur l'île.",text="près des petites ruines sur la plage la plus occidentale de Sombrechamp.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4468,objective="Parlez avec le roi Rénuic",step="Le roi Rénuic m'a montré comment son royaume est tombé devant les Orques Montemer. Il m'a aussi parlé d'une vieille arme ayléide cachée quelque part sur l'île.",text="près des petites ruines sur la plage la plus occidentale de Sombrechamp.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4468,objective="Parlez avec le roi Rénuic 1",step="Je dois découvrir le rapport entre la vision du roi Rénuic et le plan de conquête de Sangrépine sur l'île.",text="près des petites ruines sur la plage la plus occidentale de Sombrechamp.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4468,objective="Parlez avec le roi Rénuic 1",step="Le roi Rénuic m'a montré comment son royaume est tombé devant les Orques Montemer. Il m'a aussi parlé d'une vieille arme ayléide cachée quelque part sur l'île.",text="près des petites ruines sur la plage la plus occidentale de Sombrechamp.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4478,objective="Parlez à Laganakh",step="Je devrais informer Laganakh des plans de Vardan.",text="sur la route près de l’oratoire des Collines gravées.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4478,objective="Parlez à Laganakh",step="Je devrais parler à Laganakh.",text="à l’extérieur d’une des longères de la forteresse, près des marchands de la guilde.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4478,objective="Parlez à Laganakh",step="Je dois trouver Laganakh et lui dire que les adeptes peuvent maintenant pénétrer dans le royaume des esprits.",text="sur la route près de l’oratoire des Collines gravées, juste au nord de la sortie des ruines ayléides.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4482,objective="Parlez à Tazia",step="La caverne a brûlé de fond en combles et j'ai réussi à sortir aux côtés de Tazia. Il faut que je lui parle.",text="derrière la grange d'Ezzag, dans la partie sud-est de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4482,objective="Parlez à Tazia",step="On dirait que le puits donne sur une caverne. Une Khajiit était accroupie près de l'endroit où je suis tombé à l'eau et m'a fait signe de venir lui parler",text="à l'intérieur du puits, à côté de la maison Yeux-voilés dans la ville de S'ren-ja.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4482,objective="Parlez à Tazia",step="On dirait que le puits donne sur une caverne. Une Khajiit était accroupie près de l'endroit où je suis tombée à l'eau et m'a fait signe de venir lui parler",text="à l'intérieur du puits, à côté de la maison Yeux-voilés dans la ville de S'ren-ja.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4482,objective="Parlez à Yeux-voilés",step="Il faut que je dise à Yeux-voilés ce qui se passe vraiment dans son puits.",text="dans sa maison confortable sur le côté est de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4482,objective="Parlez à Yeux-voilés",step="Il faut que je parle à Yeux-voilés dans sa maison pour savoir ce qui se passe vraiment.",text="dans sa maison confortable sur le côté est de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4482,objective="Parlez à Yeux-voilés",step="Il faut que je parle à Yeux-voilés une dernière fois.",text="dans sa maison confortable sur le côté est de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4482,objective="Parlez avec Yeux-voilés",step="Il faut que je dise à Yeux-voilés ce qui se passe vraiment dans son puits.",text="dans sa maison confortable sur le côté est de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4482,objective="Parlez avec Yeux-voilés",step="Il faut que je parle à Yeux-voilés dans sa maison pour savoir ce qui se passe vraiment.",text="dans sa maison confortable sur le côté est de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4482,objective="Parlez avec Yeux-voilés",step="Il faut que je parle à Yeux-voilés une dernière fois.",text="dans sa maison confortable sur le côté est de S'ren-ja.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4483,objective="Parlez à Ezzag",step="Il faut que je parle à Ezzag pour découvrir ce qui se passe.",text="dans sa grange dans la partie sud-est de la ville de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4483,objective="Parlez à Ezzag",step="Il faut que je parle à Ezzag une dernière fois.",text="dans sa grange dans la partie sud-est de la ville de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4483,objective="Parlez à Ezzag",step="Je me suis occupé des bandits et de leur chef, d'une manière ou d'une autre. Je ferais mieux de retourner voir Ezzag pour lui annoncer la bonne nouvelle.",text="dans sa grange dans la partie sud-est de la ville de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4483,objective="Parlez avec Ezzag",step="Il faut que je parle à Ezzag pour découvrir ce qui se passe.",text="dans sa grange dans la partie sud-est de la ville de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4483,objective="Parlez avec Ezzag",step="Il faut que je parle à Ezzag une dernière fois.",text="dans sa grange dans la partie sud-est de la ville de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4483,objective="Parlez avec Ezzag",step="Je me suis occupé des bandits et de leur chef, d'une manière ou d'une autre. Je ferais mieux de retourner voir Ezzag pour lui annoncer la bonne nouvelle.",text="dans sa grange dans la partie sud-est de la ville de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4484,objective="Parlez à Kalari",step="J'ai décidé de dire la vérité à Kalari. Peut-être qu'elle sait ce que je pourrais faire maintenant pour aider la ville.",text="à l'extérieur de sa maison dans la ville de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4484,objective="Parlez à Kalari",step="J'ai décidé de mentir à Kalari. Autant qu'elle pense que Mathal est en sécurité quelque part. Peut-être qu'elle sait ce que je pourrais faire maintenant pour aider la ville.",text="à l'extérieur de sa maison dans la ville de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4484,objective="Parlez à Kalari",step="J'ai découvert la preuve que le frère de Kalari et son oncle décédé faisaient du trafic de skouma dans la région, sur ordres de l'ancien assistant de la matriarche, Rakhad. Il faut que j'en parle à Kalari.",text="à l'extérieur de sa maison dans la ville de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4484,objective="Parlez à Kalari",step="Je dois dire à Kalari ce qui s'est passé. Ou peut-être que non ? Je pourrais aussi lui mentir en lui disant que Mathal a quitté la ville. Je dois me décider.",text="à l'extérieur de sa maison dans la ville de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4484,objective="Parlez à Kalari",step="Je dois parler à Kalari pour découvrir ce qui se passe.",text="à l'extérieur de sa nouvelle maison dans la ville de S'ren-ja.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4484,objective="Parlez à Kalari",step="Je dois parler à nouveau à Kalari.",text="à l'extérieur de sa maison dans la ville de S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4485,objective="Parlez à la matriarche Shazura",step="Il faut que j'aille annoncer à la matriarche Shazura tout ce qui s'est passé.",text="à son manoir en S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4485,objective="Parlez à la matriarche Shazura",step="J'ai fait ce que j'ai pu pour la ville. Il est temps de revenir parler à Shuzura.",text="à son manoir en S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4485,objective="Parlez avec la matriarche Shazura",step="Il faut que j'aille annoncer à la matriarche Shazura tout ce qui s'est passé.",text="à son manoir en S'ren-ja.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4485,objective="Parlez avec la matriarche Shazura ",step="J'ai fait ce que j'ai pu pour la ville. Il est temps de revenir parler à Shuzura.",text="à son manoir en S'ren-ja.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4487,objective="Parlez à Télenger",step="Méphala affirme que Télenger lui a autorisé à prendre certains des fidèles de Falinesti comme adeptes. Il faut que je lui parle de tout cela.",text="au temple intérieur de Daedra, à l'intérieur des profondeurs du salles de l'Ichor.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4503,objective="Escortez Dariel en lieu sûr",step="J'ai trouvé Dariel à l'arrière des ruines et récupéré la sève de plante qui devrait guérir Daine. Je dois maintenant escorter Dariel vers l'entrée des ruines.",text="à l’intérieur des ruines de Roncenoire.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4503,objective="Escortez Dariel en lieu sûr",step="J'ai trouvé Dariel à l'arrière des ruines. Je dois maintenant l'escorter à l'entrée.",text="à l’intérieur des ruines de Roncenoire.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4503,objective="Parlez à Dariel",step="J'ai trouvé Dariel à l'arrière des ruines et j'ai réussi à l'escorter à l'entrée. Je devrais parler à Dariel et lui demander ce qu'il compte faire ensuite.",text="à l’intérieur des ruines de Roncenoire.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4503,objective="Parlez à Dariel",step="J'ai trouvé Dariel à l'arrière des ruines. Il semble blessé. Je devrais lui parler et voir s'il peut marcher.",text="à l’est des ruines de Roncenoire.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4503,objective="Parlez à Dariel",step="J'ai trouvé Dariel à l'arrière des ruines, récupéré la sève de plante qui devrait guérir Daine, et escorté Dariel en lieu sûr. Je devrais parler à Dariel et lui demander ce qu'il compte faire ensuite.",text="à l’intérieur des ruines de Roncenoire, près de l’entrée.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4503,objective="Parlez avec Dariel",step="J'ai trouvé Dariel à l'arrière des ruines et j'ai réussi à l'escorter à l'entrée. Je devrais parler à Dariel et lui demander ce qu'il compte faire ensuite.",text="à l’intérieur des ruines de Roncenoire.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4503,objective="Parlez avec Dariel",step="J'ai trouvé Dariel à l'arrière des ruines. Il semble blessé. Je devrais lui parler et voir s'il peut marcher.",text="à l’est des ruines de Roncenoire.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4503,objective="Parlez avec Dariel",step="J'ai trouvé Dariel à l'arrière des ruines, récupéré la sève de plante qui devrait guérir Daine, et escorté Dariel en lieu sûr. Je devrais parler à Dariel et lui demander ce qu'il compte faire ensuite.",text="à l’intérieur des ruines de Roncenoire, près de l’entrée.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4508,objective="Parlez à Shazim",step="J'ai retrouvé les affaires de Shazim. Je devrais les lui rapporter et voir ce qui se passera.",text="près du puits au nord-est du pont, sur la route qui quitte Port Hunding vers le nord.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4508,objective="Parlez à Shazim",step="Shazim est heureux d'avoir retrouvé ses affaires. Je devrais lui parler.",text="près du puits au nord-est du pont, sur la route qui quitte Port Hunding vers le nord.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4510,objective="Parlez au capitaine Kaleen",step="Je dois trouver le capitaine Kaleen à la Sirène hurlante et la convaincre de m'intégrer dans l'équipe de son casse.",text="à la taverne de la Sirène hurlante, à l’est de Port Hunding.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4510,objective="Parlez au capitaine Kaleen",step="Le capitaine Kaleen a accepté de partager ses profits si j'arrivais à recruter de l'aide pour son casse.",text="à la taverne de la Sirène hurlante, à l’est de Port Hunding.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4515,objective="Parlez à l'ombre d'Ulthorn",step="Après avoir parlé avec l'ombre d'Ulthorn, j'ai été transporté dans une clairière. Je devrais discuter avec l'ombre d'Ulthorn et déterminer ce que nous pouvons faire pour trouver les soldats.",text="près d'un autel sur le site rituel à l'ouest de Cours bondissant, dans la région nord-est de Malabal Tor.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4515,objective="Parlez à l’ombre d'Ulthorn",step="Le lieutenant est blessé et le capitaine Trelano semblait hypnotisé par une sorte d'esprit. Il ne semble pas hostile. Je devrais lui demander ce qu'il veut.",text="sur le site rituel des falaises occidentales de Cours bondissant.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4525,objective="Parlez à Azlakha",step="J'ai décidé de garder le cor de chasse de Targoth, au cas où nous aurions besoin de faire appel aux esprits pour combattre le Culte de Sangrépine.",text="devant l’entrée de Moriseli.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4525,objective="Parlez à Azlakha",step="J'ai libéré les esprits orques de leur sortilège. Il sont à nouveau en paix. Je devrais parler à Azlakha de ce qui s'est passé ici.",text="devant l’entrée de Moriseli.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4525,objective="Parlez au fantôme de Targoth",step="Targoth est apparu, enfin délivré du sortilège de Drusilla. Voyons ce qu'il a à me dire.",text="dans la chambre d'inhumation de Moriseli.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4525,objective="Parlez au fantôme de Targoth",step="Un Orque est enchaîné à l'entrée de Moriseli. Je devrais lui parler.",text="dans la petite chambre nord-ouest de Moriseli.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4526,objective="Parlez à Angrel, au Guet de Vulkhel",step="Je devrais encore parler à Angrel.",text="à la guilde des mages, dans le quartier ouest.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4535,objective="Allez parler à Bumnog",step="Je dois m'arrêter pour savoir de quoi Bumnog veut parler.",text="à la périphérie du camp des Daggers.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4535,objective="Allez parler à Bumnog",step="Le seigneur Diel s'est fait tuer par une des harpies qu'il prévoyait de vendre sur le marché. C'est Gelvin qui l'avait libérée. Les Dagues n'ont plus rien à faire ici, et ils ne seront pas payés. Je devrais raconter à Bumnog ce qui s'est passé.",text="près de la maison de pêche sur l'île à l'ouest de Sillon hurlant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4535,objective="Allez parler à Gelvin",step="Bumnog a réussi à subtiliser un petit sac de gemmes dans le camp du seigneur Diel. Leur valeur ne couvre pas le montant promis aux Dagues, mais cela devrait les convaincre de continuer. Je devrais parler à Gelvin.",text="à la rive continentale, à l'ouest de Sillon hurlant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4535,objective="Allez parler au seigneur Diel",step="Bumnog me dit qu'il compte bien que les Dagues soient payées, quelques soient les intentions du seigneur Diel. De retour au camp, je devrais parler au seigneur Diel et lui faire savoir que ses recherches ont été fructueuses.",text="au cœur du camp des Daggers, à l'est de Sillon hurlant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4535,objective="Allez parler au seigneur Diel",step="J'ai accepté d'aider Gelvin à s'occuper du seigneur Diel. Je dois parler à Diel afin de l'occuper pendant que Gelvin cherche un moyen de faire payer sa Seigneurie.",text="à l'extérieur de la maison de pêche sur l'île à l'ouest de Sillon hurlant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4535,objective="Allez parler au seigneur Diel",step="J'ai convaincu Gelvin d'ignorer les preuves contre le seigneur Diel et de finir le travail afin que les Dagues soient payés. Je le retrouverai dehors lorsque j'aurai apporté un cinquième œuf de harpie au seigneur Diel.",text="sur la jetée à l'extérieur de la maison de pêche, sur l'île à l'ouest de Sillon hurlant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4535,objective="Parlez à Gelvin",step="Bumnog a réussi à subtiliser un petit sac de gemmes dans le camp du seigneur Diel. Leur valeur ne couvre pas le montant promis aux Dagues, mais cela devrait les convaincre de continuer. Je devrais parler à Gelvin.",text="à la rive continentale, à l'ouest de Sillon hurlant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4535,objective="Parlez au seigneur Diel",step="Bumnog me dit qu'il compte bien que les Dagues soient payées, quelques soient les intentions du seigneur Diel. De retour au camp, je devrais parler au seigneur Diel et lui faire savoir que ses recherches ont été fructueuses.",text="au cœur du camp des Daggers, à l'est de Sillon hurlant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4535,objective="Parlez au seigneur Diel",step="J'ai accepté d'aider Gelvin à s'occuper du seigneur Diel. Je dois parler à Diel afin de l'occuper pendant que Gelvin cherche un moyen de faire payer sa Seigneurie.",text="à l'extérieur de la maison de pêche sur l'île à l'ouest de Sillon hurlant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4535,objective="Parlez au seigneur Diel",step="J'ai convaincu Gelvin d'ignorer les preuves contre le seigneur Diel et de finir le travail afin que les Dagues soient payés. Je le retrouverai dehors lorsque j'aurai apporté un cinquième œuf de harpie au seigneur Diel.",text="sur la jetée à l'extérieur de la maison de pêche, sur l'île à l'ouest de Sillon hurlant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4541,objective="Parlez à Suronii",step="J'ai atteint le perchoir. Je dois parler à Suronii.",text="dans le surplomb du surveillant à l'intérieur de la montagne centrale jusqu'au nord.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4541,objective="Parlez à Suronii",step="Je suis mort pour alimenter le sort de Suronii. Son image est apparue. Je devrais peut-être lui parler.",text="à l'entrée du Village des perdus.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4541,objective="Parlez à Suronii",step="Je suis morte pour alimenter le sort de Suronii. Son image est apparue. Je devrais peut-être lui parler.",text="à l'entrée du Village des perdus.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4541,objective="Parlez avec Suronii",step="J'ai atteint le perchoir. Je dois parler à Suronii.",text="dans le surplomb du surveillant à l'intérieur de la montagne centrale jusqu'au nord.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4541,objective="Parlez avec Suronii",step="Je suis mort pour alimenter le sort de Suronii. Son image est apparue. Je devrais peut-être lui parler.",text="à l'entrée du Village des perdus.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4541,objective="Parlez avec Suronii",step="Je suis morte pour alimenter le sort de Suronii. Son image est apparue. Je devrais peut-être lui parler.",text="à l'entrée du Village des perdus.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4546,objective="Parlez à Indaenir",step="J'ai vaincu le serviteur de Næmon et j'ai pu fuir du bois des ombres. Je dois parler à Indaenir pour savoir quoi faire ensuite.",text="au milieu de col de Driladan.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4546,objective="Parlez à Indaenir",step="La crinière Akkhuz-ri retourne à Marbruk pour y apporter son soutien et a suggéré que je me joigne à Indaenir pour tenter de déterminer la véritable raison de l'attaque de Marbruk par les forces de l'Ombre.",text="dans les tunnels en direction du sentier nord à partir de Marbruk.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4550,objective="Fermez le portail",step="Le croc crépite d'énergie daedrique. Je ferais mieux de l'utiliser pour fermer le portail.",text="près du centre des zones résidentielles de Dune habitants.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4550,objective="Parlez à la Championne",step="J'ai vaincu l'Ancre noire. Je dois parler à la Championne pour voir si elle va bien.",text="à l'intérieur du sanctuaire de Lorkhaj dans le district du temple du sud-est de Dune.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4550,objective="Parlez à la Championne",step="Le portail est fermé. Je dois parler à la Championne pour savoir ce que je dois faire ensuite.",text="près du centre des zones résidentielles de Dune habitants.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4550,objective="Refermez le portail",step="Le croc crépite d'énergie daedrique. Je ferais mieux de l'utiliser pour fermer le portail.",text="près du centre des zones résidentielles de Dune habitants.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4551,objective="Parlez à Marius",step="J'ai donné à Marius le récipient magique renfermant le poison. Il en était très reconnaissant. Je dois lui parler au sujet de ma récompense.",text="au fossé de la déversée des poisons, près du bassin obscur au sud de Zuuk, à l'ouest de ruines de Gandranen.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4551,objective="Parlez à Marius",step="Rhéa a enchanté l'enveloppe de guêpe et m'a enjoint d'interroger Marius sur ses desseins.",text="au camp impérial près de la route au-delà des marécages au sud de bassins d'incubation.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4556,objective="Parlez à Mozgosh",step="L’élixir de Sérisie aurait complètement soigné Mozgosh. Je vais aller voir comment elle se sent.",text="près de sa tente sur la plate-forme nord-est de Hissmir.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4556,objective="Parlez à Mozgosh",step="Lorsque l’élixir de Xthari a sorti Mozgosh de son coma, elle était sévèrement affaiblie. Il faut que je détermine dans quel état elle se trouve.",text="près de sa tente sur la plate-forme nord-est de Hissmir.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4556,objective="Parlez avec Mozgosh",step="L’élixir de Sérisie aurait complètement soigné Mozgosh. Je vais aller voir comment elle se sent.",text="près de sa tente sur la plate-forme nord-est de Hissmir.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4556,objective="Parlez avec Mozgosh",step="Lorsque l'élixir de Xthari a sorti Mozgosh de son coma, elle était sévèrement affaiblie. Il faut que je détermine dans quel état elle se trouve.",text="près de sa tente sur la plate-forme nord-est de Hissmir.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4559,objective="Parlez à Lokra",step="Lokra, la fille du chef Tazgol, cause des problèmes. Sa famille veut la marier afin de forger une alliance avec un autre clan. Mais elle souhaite d'abord aller voir le monde.",text="sur les quais de la forteresse.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4566,objective="Parlez à sieur Lanis Shaldon",step="Je dois informer sieur Lanis Shaldon que les Orques de Montemer rejoignent l'Alliance.",text="près des écuries de Daguefilante.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4573,objective="Parlez au thane sylvestre",step="J'ai planté des graines de Kollopi pour qu'elles fassent pousser des gardiens dans le camp des Orques des bois, et j'ai tué leur chef pour les mettre en fuite. Je devrais retourner parler au thane sylvestre des Roncebrèche.",text="dans le chambre du thane sylvestre.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4574,objective="Adressez-vous à Razum-dar",step="Comme prévu, l'officier du Thalmor a tenté d'assassiner la reine Razum-dar alors qu'il se faisait passer pour la reine. Son attaque l'a jeté au sol. Je devrais lui parler pour m'assurer qu'il va bien.",text="dans le souterrain impérial, sous la tour de guet, au nord de Cinq Griffes.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4574,objective="Adressez-vous à Razum-dar",step="J'ai trouvé des ordres donnés par le vice-chanoine Pélidil dans les vieux tunnels impériaux ; ils suggèrent que l'Héritage voilé aurait une force armée plus grande stationnée près de Foyeraie. Je dois ramener ces ordres à Razum-dar.",text="dans le souterrain impérial, sous la tour de guet, au nord de Cinq Griffes.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4574,objective="Adressez-vous à Razum-dar",step="Je dois parler à Razum-dar pour découvrir ce qu'il a appris sur les plans de Pélidil.",text="à l'intérieur du quartier général du Thalmor en Foyeraie.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4574,objective="Adressez-vous à Razum-dar",step="Pour démasquer les traîtres qui travaillent avec Pélidil, je dois escorter Razum-dar déguisé en reine Ayrenn, vers les vieux tunnels impériaux, où quelqu'un devrait tenter de l'assassiner. je dois lui parler quand je serai prêt à partir.",text="à l'intérieur du quartier général du Thalmor en Foyeraie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4574,objective="Adressez-vous à Razum-dar",step="Pour démasquer les traîtres qui travaillent avec Pélidil, je dois escorter Razum-dar déguisé en reine Ayrenn, vers les vieux tunnels impériaux, où quelqu'un devrait tenter de l'assassiner. je dois lui parler quand je serai prête à partir.",text="à l'intérieur du quartier général du Thalmor en Foyeraie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4574,objective="Adressez-vous à Razum-dar 1",step="Comme prévu, l'officier du Thalmor a tenté d'assassiner la reine Razum-dar alors qu'il se faisait passer pour la reine. Son attaque l'a jeté au sol. Je devrais lui parler pour m'assurer qu'il va bien.",text="dans le souterrain impérial, sous la tour de guet, au nord de Cinq Griffes.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4574,objective="Adressez-vous à Razum-dar 1",step="J'ai trouvé des ordres donnés par le vice-chanoine Pélidil dans les vieux tunnels impériaux ; ils suggèrent que l'Héritage voilé aurait une force armée plus grande stationnée près de Foyeraie. Je dois ramener ces ordres à Razum-dar.",text="dans le souterrain impérial, sous la tour de guet, au nord de Cinq Griffes.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4574,objective="Parlez à Razum-dar",step="Comme prévu, l'officier du Thalmor a tenté d'assassiner la reine Razum-dar alors qu'il se faisait passer pour la reine. Son attaque l'a jeté au sol. Je devrais lui parler pour m'assurer qu'il va bien.",text="dans le souterrain impérial, sous la tour de guet, au nord de Cinq Griffes.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
