{quest=4574,objective="Trouvez Razum-dar au détroit de l'Aigle 1",step="J'ai trouvé des ordres donnés par le vice-chanoine Pélidil dans les vieux tunnels impériaux ; ils suggèrent que l'Héritage voilé aurait une force armée plus grande stationnée près de Foyeraie. Je dois ramener ces ordres à Razum-dar.",text="dans le souterrain impérial, sous la tour de guet, au nord de Cinq Griffes.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4575,objective="Parlez à Orthenir",step="Maintenant que la protection est rétablie, je dois parler à Orthenir dans le bosquet d'Aigueracine.",text="au centre de la bosquet.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4580,objective="Parlez à Oromin",step="C'est inexplicable. Astéril, l'espionne de Pélidil, semble être morte depuis plusieurs jours. Je devrais en discuter avec Oromin.",text="à l'intérieur du résidence du Thalmor en Foyeraie.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4580,objective="Parlez à Oromin",step="Pour trouver Pélidil, je dois me confronter à Astéril, l'officier du Thalmor qui espionne pour le compte de Pélidil. Je dois parler à Oromin pour qu'il nous accompagne à la résidence du Thalmor.",text="à l'intérieur du quartier général du Thalmor en Foyeraie.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4586,objective="Observez la démonstration d'Aranias",step="Aranias fera bientôt la démonstration de son pouvoir à l'Héritage voilé. Je dois l'atteindre avant qu'elle ne la fasse.",text="dans les manoirs à l'intérieur de l'histoire du Spinner Maruin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4586,objective="Observez la démonstration d'Aranias",step="Aranias va commencer sa démonstration pour l'Héritage voilé. je dois regarder pour savoir si elle tient compte de mes paroles.",text="dans les manoirs à l'intérieur de l'histoire du Spinner Maruin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4586,objective="Parlez à Aranias",step="Après avoir tué un bandit dans la ferme en feu, Aranias a paru plus fébrile. Je devrais m'assurer qu'elle va bien.",text="dans l'histoire du Spinner Maruin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4586,objective="Parlez à Aranias",step="Des ronces ont agrippé mes jambes pour me ralentir, et Aranias a facilement remporté la course. Je dois lui demander si elle est impliquée là-dedans.",text="au phare à l'extrémité sud de l'île à l'intérieur de l'histoire de Spinner Maruin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4586,objective="Parlez à Aranias",step="J'ai été envoyé dans le passé d'Aranias, quand elle vivait chez ses parents sur une île près du Couchant. Maruin m'a dit de lui parler et de devenir son ami.",text="dans l'histoire du Spinner Maruin.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4586,objective="Parlez à Aranias",step="J'ai été envoyée dans le passé d'Aranias, quand elle vivait chez ses parents sur une île près du Couchant. Maruin m'a dit de lui parler et de devenir son amie.",text="dans l'histoire du Spinner Maruin.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4586,objective="Parlez à Maruin",step="Aranias a perdu son calme, mais elle s'est aussitôt montrée contrite. elle m'a dit de la retrouver dans le manoir, mais Maruin est apparu dans l'histoire. Je dois lui parler d'abord.",text="à la ferme à l'intérieur de l'histoire de Spinner.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4586,objective="Parlez à Maruin",step="Aranias était fière de sa capacité à sculpter le sol, ses parents étaient moins satisfaits. Je devrais parler à Marun de l'importance de cette histoire.",text="sur l'île du lac sur Silatar à l'intérieur du maisonnette du trameur.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4586,objective="Parlez à Maruin",step="L'Héritage voilé projette d'utiliser une Bosmer comme cible pour le pouvoir d'Aranias. Je dois parler à Maruin pour savoir comment empêcher ce meurtre insensé.",text="à l'ouest du manoir à l'intérieur de l'histoire dans le maisonnette du trameur.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4586,objective="Parlez à Maruin",step="Maruin peut m'expliquer comment changer l'histoire d'Aranias.",text="dans le maisonnette du trameur.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4587,objective="Parlez à Ukatsei",step="J'ai épargné Ukatsei du destin réservé à ses compagnons. Il a fui vers la caverne où se trouvent les vice-chanoines.\r\n\r\nJe dois le suivre pour savoir s'il sait où le vice-chanoine Hrondar se trouve.",text="dans la grotte au centre de la ruine.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4587,objective="Parlez à Ukatsei",step="Ukatsei a confirmé la mort du vice-chanoine Hrondar, il y a plusieurs heures de cela. Cela signifie qu'un voleur de peau est à la tête du régiment !",text="dans le pavillon daédrique au nord-est du centre de Ten-Maur-Wolk.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4587,objective="Parlez à Ukatsei",step="Ukatsei est en état de choc après avoir vu le cadavre de son commandant. Il serait intéressant de lui parler du mystérieux décès du vice-chanoine Hrondar.",text="dans le pavillon daédrique au nord-est du centre de Ten-Maur-Wolk.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4587,objective="Parlez avec Ukatsei",step="J'ai épargné Ukatsei du destin réservé à ses compagnons. Il a fui vers la caverne où se trouvent les vice-chanoines.\n\nJe dois le suivre pour savoir s'il sait où le vice-chanoine Hrondar se trouve.",text="dans la grotte au centre de la ruine.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4587,objective="Parlez avec Ukatsei",step="Ukatsei a confirmé la mort du vice-chanoine Hrondar, il y a plusieurs heures de cela. Cela signifie qu'un voleur de peau est à la tête du régiment !",text="dans le pavillon daédrique au nord-est du centre de Ten-Maur-Wolk.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4587,objective="Parlez avec Ukatsei",step="Ukatsei est en état de choc après avoir vu le cadavre de son commandant. Il serait intéressant de lui parler du mystérieux décès du vice-chanoine Hrondar.",text="dans le pavillon daédrique au nord-est du centre de Ten-Maur-Wolk.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4590,objective="Parlez à Lyranth",step="J'ai vaincu le voleur de peau responsable de la mort du vice-chanoine Hrondar. Je devrais parler à Lyranth avant de partir.",text="dans l’Antre du voleur de peau, au plus profond du complexe à travers le portail au-dessus de Ten-Maur-Wolk.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4590,objective="Parlez à Lyranth",step="J'ai vaincu le voleur de peau responsable de la mort du vice-chanoine Hrondar. Je devrais parler à un Lyranth avant de partir.",text="dans le Antre du voleur de peau, au plus profond du complexe à travers le portail au-dessus de Ten-Maur-Wolk.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4590,objective="Parlez à Lyranth",step="Je suis tombé sur un Drémora emprisonné dans le repaire du Domaine. Elle veut que je lui parle. Elle a peut-être des informations au sujet du voleur de peau.",text="à l'intérieur du portail au sommet de la grande colline en Ten-Maur-Wolk.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4590,objective="Parlez à Lyranth",step="Je suis tombée sur un Drémora emprisonné dans le repaire du Domaine. Elle veut que je lui parle. Elle a peut-être des informations au sujet du voleur de peau.",text="à l'intérieur du portail au sommet de la grande colline en Ten-Maur-Wolk.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4593,objective="Parlez au Roi-Nature",step="J'ai invoqué et vaincu une apparition de feu le conseiller Norion, membre de l'Héritage voilé. Je dois parler avec le Roi-nature pour savoir s'il reconnaît que nous avons les mêmes ennemis.",text="à la pierre de la pétition, au sud de Roncebrèche.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4593,objective="Parlez au Roi-Nature",step="J'ai touché la pierre de pétition, et le Roi-nature est apparu. Je devrais lui parler.",text="à la pierre de la pétition, au sud de Roncebrèche.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4593,objective="Parlez au Roi-Nature",step="La vision m'a révélé que l'Héritage voilé a envoyé Aranias et Andur ici pour tuer le Roi-nature, et pourtant il ne les traite pas en ennemis. Je dois lui en parler.",text="à la pierre de la pétition, au sud de Roncebrèche.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4596,objective="Parlez à Benduin",step="J'ai rassemblé les ingrédients demandés. Je dois maintenant parler à Benduin pour savoir quoi faire ensuite.",text="dans sa clairière au nord de l’oratoire du Labyrinthe.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4596,objective="Parlez à Benduin",step="Mon gardien a vaincu deux des autres gardiens. Je devrais parler à Benduin.",text="dans sa clairière au nord de l’oratoire du Labyrinthe.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4599,objective="Parlez à Halindor",step="Il faut que je dise à Halindor ce que j'ai trouvé dans les maisons de ses amis.",text="devant sa maison.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4599,objective="Parlez à Halindor",step="Je dois retrouver Halindor et lui dire ce que j'ai découvert dans la maison de Gonlas.",text="au nord de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4599,objective="Parlez à l'halindor",step="Il faut que je dise à Halindor ce que j'ai trouvé dans les maisons de ses amis.",text="devant sa maison.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4599,objective="Parlez à un Halindor",step="Il faut que je dise à Halindor ce que j'ai trouvé dans les maisons de ses amis.",text="devant sa maison.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4599,objective="Parlez avec Halindor",step="Il faut que je dise à Halindor ce que j'ai trouvé dans les maisons de ses amis.",text="devant sa maison.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4599,objective="Parlez avec l'Halindor",step="Il faut que je dise à Halindor ce que j'ai trouvé dans les maisons de ses amis.",text="devant sa maison.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4601,objective="Parlez à Indaenir",step="On m'a dit qu'Indaenir avait un plan pour renvoyer les guerriers du clan Noiresouche dans la tombe. Je dois lui parler.",text="au camp au sud de Vullain l'effroi.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4602,objective="Parlez au roi Laloriaran Dynar",step="J'ai libéré le roi Laloriaran Dynar de l'énergie obscure qui le retenait. Je devrais lui parler pour être sûr qu'il va bien.",text="dans sa prison, juste après les cristaux à l'intérieur du passage en ruines près de l’oratoire de l'Étendue asélène.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4602,objective="Parlez au roi Laloriaran Dynar",step="Je suis de retour à la Cité creuse. Je devrais retrouver le roi Laloriaran Dynar, pour vérifier qu'il est bien arrivé.",text="à la Cité creuse.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4605,objective="Parlez à la Gouvernante",step="Je devrais parler à la Gouvernante. Elle me suggérera peut-être une façon de faire.",text="sur les marches du temple.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4605,objective="Parlez à la Gouvernante",step="Je devrais parler à la Gouvernante pour en apprendre davantage sur la Cité creuse.",text="près de Vive étoile.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4605,objective="Parlez à la Gouvernante",step="La Gouvernante semble avoir fini la visite de la Cité creuse. Je devrais lui parler.",text="sur les marches du temple.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4606,objective="Parlez au gardien Uxith-Ei",step="J'ai allumé les braseros et j'ai retrouvé Assistant Telixith. Je dois retourner voir le gardien Uxith-Ei pour lui faire part de mes découvertes au sujet des projets du Domaine.",text="sur l'escalier avant l'Histère à l'intérieur du bassins d'incubation.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4606,objective="Parlez au gardien Uxith-Ei",step="J'ai allumé les braseros et j'ai retrouvé l’assistante Telixith. Je dois retourner voir le gardien Uxith-Ei pour lui faire part de mes découvertes au sujet des projets du Domaine.",text="sur l'escalier avant l'Histère à l'intérieur du bassins d'incubation.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4606,objective="Parlez au gardien Uxith-Ei",step="Le rituel d'éclosion s'est mal déroulé. Ahaht-Ei, l'assistant du gardien Uxith-Ei, est mort au cours du rituel, il semble avoir souffert. Je dois découvrir ce qui s'est passé.",text="sur l'escalier avant l'Histère à l'intérieur du bassins d'incubation.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4606,objective="Parlez avec le gardien Uxith-Ei",step="J'ai allumé les braseros et j'ai retrouvé Assistant Telixith. Je dois retourner voir le gardien Uxith-Ei pour lui faire part de mes découvertes au sujet des projets du Domaine.",text="sur l'escalier avant l'Histère à l'intérieur du bassins d'incubation.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4606,objective="Parlez avec le gardien Uxith-Ei",step="J'ai allumé les braseros et j'ai retrouvé l'assistante Telixith. Je dois retourner voir le gardien Uxith-Ei pour lui faire part de mes découvertes au sujet des projets du Domaine.",text="sur l'escalier avant l'Histère à l'intérieur du bassins d'incubation.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4606,objective="Parlez avec le gardien Uxith-Ei",step="Le rituel d'éclosion s'est mal déroulé. Ahaht-Ei, l'assistant du gardien Uxith-Ei, est mort au cours du rituel, il semble avoir souffert. Je dois découvrir ce qui s'est passé.",text="sur l'escalier avant l'Histère à l'intérieur du bassins d'incubation.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4607,objective="Allez à la citerne",step="Je dois trouver la citerne du château et retrouver Cadwell.",text="le canal d’écoulement de la citerne et remontez-le jusqu’à sa porte : Cadwell vous y a donné rendez-vous.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4607,objective="Trouvez l'entrée du Château",step="Nous devons trouver un moyen d'entrer dans le Château du Ver. Lyris m'a suggéré de chercher quelqu'un qui pourrait nous aider.",text="parmi les maisons du village au pied du château. Les esclaves connaissent peut-être un passage.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4608,objective="Parlez à Indaenir",step="J'ai vaincu le serviteur de Næmon et j'ai pu fuir du bois des ombres. Je dois parler à Indaenir.",text="près du antre de l'aîné au large du chemin au nord de fondrière du Verrant.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4610,objective="Parlez au roi Laloriaran Dynar",step="Nous avons détruit les Grands Fers, mais la Coalescence se poursuit. Le conseil de guerre a décidé que nous mènerions l'assaut contre l'Abîme, pour nous frayer un chemin jusqu'au vortex planaire. Alors seulement, nous serons à même de sceller ce lien, et de sauver Nirn de la Coalescence.",text="à l'intérieur de la chapelle de la Lumière dans la cité creuse.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4611,objective="Parlez à Breduin",step="D'après les habitants de Longuehalte, des gens disparaissent dans le brouillard qui recouvre les landes. On m'a suggéré de m'adresser à Breduin pour de plus amples informations.",text="dans sa maison en Longuehalte, un village au nord-est de landes d'Ombrume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4611,objective="Parlez à Breduin",step="J'ai dissipé l'enchantement qui attirait les habitants dans la brume. Je dois informer Breduin de mon succès.",text="dans sa maison en Longuehalte, un village au nord-est de landes d'Ombrume.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4623,objective="Parlez à Gadris",step="J'ai décidé de sauver Gadris. Je devrais lui parler et voir s'il s'est remis de la Coalescence d'âme.",text="à côté de la machinerie Dwarven à l'intérieur du atelier du surveillant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4623,objective="Parlez à Gadris",step="Je devrais retrouver Gadris devant le Laboratoire infâme et lui parler.",text="à l'extérieur du Laboratoire infâme, à l'extrémité de la route menant au sud.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4623,objective="Parlez à Zur",step="J'ai décidé de sauver Zur. Je devrais lui parler et voir s'il s'est remis de la Coalescence d'âme.",text="à côté de la machinerie Dwarven à l'intérieur du atelier du surveillant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4623,objective="Parlez à Zur",step="Je devrais retrouver Zur devant le Laboratoire infâme et lui parler.",text="à l'extérieur du Laboratoire infâme, à l'extrémité de la route menant au sud.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4623,objective="Quittez le laboratoire",step="À présent que j'ai ce cristal, je devrais trouver la sortie et quitter ce Laboratoire infâme.",text="à travers la porte à l'extrémité d'un petit passage à côté d'une étagère contre un mur gravé de runes.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4623,objective="Quittez le laboratoire",step="À présent que j'ai la lumière de Méridia, je devrais trouver la sortie et quitter ce Laboratoire infâme.",text="à travers la porte à l'extrémité d'un petit passage à côté d'une étagère contre un mur gravé de runes.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4623,objective="Retrouvez le mage aux âmes jointes",step="J'ai forgé les tiges antipodales pour l'engin dwemer dont le mage aux âmes jointes m'a parlé. Je devrais aller à l'atelier du Surveillant et retrouver Gadris ou Zur.",text="à l’atelier du Surveillant, plus loin dans le laboratoire. La porte est près des grands tuyaux ; au carrefour du couloir, prenez à droite.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4623,objective="Retrouvez le mage aux âmes jointes",step="J'ai trouvé un étrange appareil dwemer. Sans doute la machine qui peut inverser la Coalescence d'âmes et libérer Gadris et Zur. Je devrais parler au mage pour obtenir les dernières instructions.",text="à côté du dispositif nain contre la paroi ouest du atelier du surveillant.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4626,objective="Parlez à l'essence de Galérion",step="À l'intérieur de la Forge noire, j'ai trouvé Vanus Galérion. Ou au moins, une partie du grand mage. Je devrais parler à son essence.",text="à l’intérieur de la Forge noire.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4626,objective="Parlez à l'essence de Galérion",step="J'ai brisé les sceaux magiques qui retenaient l'essence de Galérion. Je devrais parler à l'essence du mage, pour voir s'il peut se libérer.",text="à l'intérieur de la fonderie, au-delà de la porte sous l'écoulement de la lave et au fond de la quartiers des esclaves.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4626,objective="Parlez à l'essence de Galérion",step="J'ai récupéré l'énergie prélevée sur la vigueur de Galérion. Je devrais parler à l'essence du mage et lui rendre cette énergie.",text="à l'intérieur du quartiers des esclaves plus loin dans le complexe, au-delà de la porte sous l'écoulement de la lave.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4626,objective="Trouvez Vanus Galérion",step="À présent que j'ai réuni toutes les essences de Vanus, je dois trouver le corps du grand mage.",text="dans le tunnels de la chaudière, au-delà de la porte sous l'écoulement de la lave et au fond des passages de la Forge Noire.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4626,objective="Trouvez Vanus Galérion",step="Je devrais entrer dans la Forge noire et y chercher Vanus Galérion. Le message me suggérait d'entrer par la porte de service.",text="dans la Forge noire. Le message indique la porte de service.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4638,objective="Parlez à la milicienne Ebarah",step="J'ai décidé de livrer Fadeel aux autorités.",text="près des stocks de Kozanset.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4638,objective="Parlez à la milicienne Ebarah",step="Je dois livrer Fadeel aux autorités pour qu'il soit traduit en justice.",text="près des stocks de Kozanset.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4642,objective="Parlez à Malkur Valos",step="J'ai trouvé les mages sur la route, près de la Cour de l'outrage. Ils ont déjà ouvert un portail. Je devrais parler à Malkur Valos et m'assurer qu'ils vont bien.",text="au sud de la Cour.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4642,objective="Parlez avec Malkur Valos",step="J'ai trouvé les mages sur la route, près de la Cour de l'outrage. Ils ont déjà ouvert un portail. Je devrais parler à Malkur Valos et m'assurer qu'ils vont bien.",text="au sud de la Cour.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4642,objective="Retrouvez les mages à l'extérieur",step="Les mages secourus sont sortis rejoindre Malkur. Je devrais les rejoindre.",text="à l’extérieur des cellules, après la porte dans la partie nord-est des ruines.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4651,objective="Parlez à Ishalga",step="Il faut que je parle à Ishalga, la grande championne, afin qu'elle m'autorise à l'affronter lors du grand championnat.",text="à l'extérieur de l'Arena principale, le plus grand, le plus bruyant et le plus prestigieux.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4651,objective="Parlez à Ishalga",step="Je dois revenir voir Ishalga et lui dire que j'ai trouvé le skouma qu'elle voulait dans le bureau de Feluni.",text="à l'extérieur de l'Arena principale, le plus grand, le plus bruyant et le plus prestigieux.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4652,objective="Parlez à Cariël",step="Lavinia est morte. Je dois aller retrouver Cariël et Kazirra pour leur parler.",text="au centre-ville de Arenthia.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4652,objective="Parlez à Kazirra",step="J'ai écouté le discours de Lavinia aux Arenthiens. Cariël m'a dit de me rendre à une des huttes du marché afin de rencontrer les membres de la résistance. C'est celle qui a une statue de lion en bas des marches.",text="à l'intérieur de la base de résistance.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4652,objective="Parlez à Kazirra",step="Je suis de retour chez auprès de la résistance. Je dois demander à Kazirra ce que nous allons faire de Gavo.",text="à l'intérieur de la cabane sur le marché avec une statue de lion à la base de l'escalier.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4652,objective="Parlez à Kazirra",step="Maintenant que nous avons enregistré la confession de Gavo, je dois demander à Kazirra ce qu'elle compte en faire.",text="à l'intérieur de la cabane sur le marché avec une statue de lion à la base de l'escalier.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4654,objective="Parlez à la projection du roi Laloriaran Dynar",step="J'ai récupéré la lumière de Méridia. Je devrais aller parler à la projection du roi ayléide, pour voir ce qu'il me reste à faire.",text="à l'intérieur du passage en ruines près de l’oratoire de l'Étendue asélène.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4659,objective="Parlez à Tamien",step="J'ai accepté de remettre les outils à Tamien. Je dois retourner le voir.",text="au sommet de l’échafaudage en bois, dans la partie nord-est des ruines.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4659,objective="Parlez à Tamien",step="Stibbons m'a suggéré d'aller trouver Tamien.",text="au sommet de l’échafaudage en bois, dans la partie nord-est des ruines.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4672,objective="Parlez à Marimah",step="Marimah, le chef des Ash'abah, souffre d'un empoisonnement, mais il souhaite me parler.",text="au camp d'Ash'abah en manne de Morwha.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4672,objective="Parlez à Marimah",step="Marimah m'a révélé que les ingrédients rassemblés précédemment n'étaient pas destinés à la préparation d'un antidote, mais à mon initiation au sein de la tribu Ash'abah. Je dois le prévenir quand je serai prêt à commencer la cérémonie.",text="dans sa tente dans le camp d'Ash'abah en manne de Morwha.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4672,objective="Parlez à Marimah",step="Marimah m'a révélé que les ingrédients rassemblés précédemment n'étaient pas destinés à la préparation d'un antidote, mais à mon initiation au sein de la tribu Ash'abah. Je dois le prévenir quand je serai prête à commencer la cérémonie.",text="dans sa tente dans le camp d'Ash'abah en manne de Morwha.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4679,objective="Parlez à Faraniël",step="Faraniël est revenue, apparemment avec de bonnes nouvelles. Je devrais aller lui parler.",text="dans la marche sans lune près de la pierre du portail par le feu de camp.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4679,objective="Parlez à Faraniël",step="Je devrais discuter de la décision du conseil avec Faraniël.",text="près du feu de camp central, dans l’Étendue asélène.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4679,objective="Parlez à Faraniël",step="Je devrais raconter à Faraniël mon entrevue avec le conseil des aînés.",text="sous la plate-forme du conseil, près du camp central de l’Étendue asélène.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4679,objective="Parlez à Faraniël",step="Lorsque j'ai atteint le pont, Faraniël a couru vers moi. Je devrais lui parler.",text="sur la portée de bois dans la Marche sans Lune.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4681,objective="Parlez à la prêtresse Sendël",step="Le rituel est terminé et le serpent de mer est à nouveau entravé. Je devrais reparler à la prêtresse Sendël.",text="au bassin d'entrave qui se trouve sur la rive à l'ouest de grotte au serpent.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4686,objective="Parlez à Talia",step="J'ai vécu une réminiscence du passé dans laquelle un prince yokudan était banni pour avoir abattu son père mort-vivant. À présent, je dois parler à la fille du chef Ash'abah, Talia.",text="dans le camp d'Achafa en manne de Morwha.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4686,objective="Parlez à Talia",step="Je dois parler à Talia pour obtenir la potion rituelle.",text="dans le camp d'Achafa en manne de Morwha.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4686,objective="Parlez au prince Haqmir",step="Je me trouve dans une réminiscence du passé. Un prince nommé Haqmir vient de me réveiller. Je dois lui parler pour découvrir ce qu'il a à me dire.",text="dans sa tente à côté de la fontaine dans le camp du sud de Ra Gada.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4686,objective="Parlez au prince Haqmir",step="Je me trouve dans une réminiscence du passé. Une nécromancienne elfe a tué mon père, le roi Xakhwan, avant de le ressusciter. L'abattre serait le comble du déshonneur. Je dois parler à mon frère.",text="près de la fontaine du palais, dans la réminiscence du passé.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4686,objective="Parlez au vizir",step="Je me trouve dans une réminiscence du passé. J'ai tué un chef de guerre elfe qui prétend avoir envoyé des assassins tuer mon père. J'ai regagné le château et il me faut à présent interroger le vizir pour découvrir ce qui s'est passé.",text="près de la fontaine du palais, dans la réminiscence du passé.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4686,objective="Parlez au vizir",step="Je me trouve dans une réminiscence du passé. Une nécromancienne elfe a tué mon père, le roi Xakhwan, avant de le ressusciter. Malgré le déshonneur qui s'ensuivra, j'ai pris la décision de l'abattre. À présent, il me faut parler à mon frère, le prince Haqmir.",text="près de la fontaine du palais, dans la réminiscence du passé.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4687,objective="Parlez à Cariël",step="J'ai aidé Cariël à se débarrasser d'un Krin Ren-dro. Je devrais lui parler.",text="à l'extérieur de la repaire de Ren-dro, dans le côté ouest de Pa'alat.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4687,objective="Parlez à Cariël",step="J'ai aidé Cariël à se débarrasser de Krin Ren-dro. Je devrais lui parler.",text="à l’extérieur du repaire de Ren-dro, dans la partie ouest de Pa’alat.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4689,objective="Parlez à Kauzanabi-jo",step="La première Grande Crinière est apparue et a confirmé que je suis l'élu des Lunes. Je devrais reparler avec la prêtresse pour savoir ce qu'elle en pense.",text="dans le claironnement au nord de Sénalana.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4689,objective="Parlez à Kauzanabi-jo",step="La première Grande Crinière est apparue et a confirmé que je suis l'élue des Lunes. Je devrais reparler avec la prêtresse pour savoir ce qu'elle en pense.",text="dans le claironnement au nord de Sénalana.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4689,objective="Parlez à Kauzanabi-jo",step="Une prêtresse lunaire du nom d'un Kauzanabi-jo se trouvait dans la clairière à mon arrivée. Je devrais aller lui parler.",text="dans le claironnement au nord de Sénalana.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4689,objective="Parlez à Kauzanabi-jo",step="Une prêtresse lunaire du nom de Kauzanabi-jo se trouvait dans la clairière à mon arrivée. Je devrais aller lui parler.",text="dans le claironnement au nord de Sénalana.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4690,objective="Adressez-vous à la reine Ayrenn",step="Je dois faire part de ce qui s'est passé à la reine Ayrenn.",text="hors de Hectahame.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4690,objective="Adressez-vous à la reine Ayrenn",step="Je dois parler à la reine Ayrenn.",text="hors de Hectahame.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4690,objective="Parlez à Indaenir",step="Indaenir s'est servi de son lien avec le Vert pour nous projeter dans le bois des ombres. Il espère ainsi passer outre les défenses de l'Ombre dans ce domaine. Je dois lui parler avant que nous y allions.",text="à la porte de Hectahame.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4690,objective="Parlez à la reine Ayrenn",step="Je dois faire part de ce qui s'est passé à la reine Ayrenn.",text="hors de Hectahame.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4690,objective="Parlez à la reine Ayrenn",step="Je dois parler à la reine Ayrenn.",text="hors de Hectahame.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4699,objective="Parlez à Érunor",step="J'ai convaincu Érunor de regagner le royaume sylvestre avec sa femme Laniriël et les autres villageois. Je dois le retrouver au sud du Val funèbre.",text="au village de Val funèbre.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4699,objective="Parlez à Érunor",step="Laniriël m'a demandé de convaincre son mari Érunor de rentrer au village, puisqu'elle est enceinte. Je devrais aller à un L'Arbre évanescent pour savoir ce qu'il a décidé.",text="à Val funèbre, Arbre évanescent, et lui apportent la nouvelle qu'il sera bientôt père.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4699,objective="Parlez à Érunor",step="Un Laniriel m'a demandé de convaincre son mari Érunor de rentrer au village, puisqu'elle est enceinte. Je devrais aller à un L'Arbre évanescent pour savoir ce qu'il a décidé.",text="à Val funèbre, Arbre évanescent, et lui apportent la nouvelle qu'il sera bientôt père.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4699,objective="Parlez à Érunor",step="Une villageoise, Laniriël, m'a un peu parlé de son étrange village, et m'a dit que son mari Érunor pourrait répondre à mes questions. Il se trouve à un L'Arbre évanescent pour la cérémonie du village.",text="sur le site de la cérémonie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4699,objective="Parlez à Érunor",step="Une villageoise, un Laniriel, m'a un peu parlé de son étrange village, et m'a dit que son mari Érunor pourrait répondre à mes questions. Il se trouve à un L'Arbre évanescent pour la cérémonie du village.",text="sur le site de la cérémonie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4699,objective="Parlez à Érunor 1",step="Laniriël m'a demandé de convaincre son mari Érunor de rentrer au village, puisqu'elle est enceinte. Je devrais aller à un L'Arbre évanescent pour savoir ce qu'il a décidé.",text="à Val funèbre, Arbre évanescent, et lui apportent la nouvelle qu'il sera bientôt père.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4699,objective="Parlez à Érunor 1",step="Un Laniriel m'a demandé de convaincre son mari Érunor de rentrer au village, puisqu'elle est enceinte. Je devrais aller à un L'Arbre évanescent pour savoir ce qu'il a décidé.",text="à Val funèbre, Arbre évanescent, et lui apportent la nouvelle qu'il sera bientôt père.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4699,objective="Parlez à Érunor 2",step="J'ai convaincu Érunor de regagner le royaume sylvestre avec sa femme Laniriël et les autres villageois. Je dois le retrouver au sud du Val funèbre.",text="au village de Val funèbre.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4699,objective="Parlez à Laniriël",step="Laniriël m'a confié qu'elle est enceinte. Elle l'a récemment découvert, et doit encore le dire à son mari. Elle m'a demandé de convaincre Érunor de retourner dans le royaume du Roi-nature avec le reste du village.\r\n\r\nÉrunor reste à l’Arbre évanescent pour prendre ses fonctions de gardien.",text="au village de Val funèbre.",source="Immersive Quests FR local : objectif et étape explicites"},
