{quest=4732,objective="Parlez à Nethrin",step="Nethrin est arrivé sur le site de fouilles et veut me parler",text="près du site de creuse.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4735,objective="Parlez au capitaine Sarandil",step="Je dois m'adresser au capitaine Sarandil, à la guilde des mages pour m'enquérir de la disparition du bâton.",text="dans la guilde des Mages.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4735,objective="Parlez au capitaine Sarandil",step="Je suis revenu à la grande salle. le capitaine Sarandil s'y trouve, il interroge les soldats de garde.",text="dans la Mages Guilde.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4735,objective="Parlez au capitaine Sarandil",step="Je suis revenue à la grande salle. le capitaine Sarandil s'y trouve, il interroge les soldats de garde.",text="dans la Mages Guilde.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4735,objective="Parlez au capitaine Sarandil",step="Le bâton de Magnus dans le caveau était un faux ! Le capitaine Sarandil en saura sûrement plus sur ce larcin.",text="à l’intérieur de la crypte principale de la guilde des Mages.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4735,objective="Parlez avec le capitaine Sarandil",step="Je dois m'adresser au capitaine Sarandil, à la guilde des mages pour m'enquérir de la disparition du bâton.",text="dans la guilde des Mages.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4735,objective="Parlez avec le capitaine Sarandil",step="Je suis revenu à la grande salle. le capitaine Sarandil s'y trouve, il interroge les soldats de garde.",text="dans la Mages Guilde.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4735,objective="Parlez avec le capitaine Sarandil",step="Je suis revenue à la grande salle. le capitaine Sarandil s'y trouve, il interroge les soldats de garde.",text="dans la Mages Guilde.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4735,objective="Parlez avec le capitaine Sarandil",step="Le bâton de Magnus dans le caveau était un faux ! Le capitaine Sarandil en saura sûrement plus sur ce larcin.",text="à l’intérieur de la crypte principale de la guilde des Mages.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4740,objective="Parlez à Pircalmo",step="J'ai empêché Ranneth de tuer Alanya. Elle m'a informé que Pircalmo était enfermé chez elle.",text="à l'intérieur de la maison à deux cannelures de thane sylvestre Ranneth.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4740,objective="Parlez à Pircalmo",step="J'ai empêché Ranneth de tuer Alanya. Elle m'a informée que Pircalmo était enfermé chez elle.",text="à l'intérieur de la maison à deux cannelures de thane sylvestre Ranneth.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4740,objective="Parlez à Pircalmo",step="J'ai récupéré les ingrédients rituels. Je devrais parler à Pircalmo, dans la forêt qui surplombe la ville",text="en haut de la colline.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4740,objective="Parlez à Pircalmo",step="J'ai trouvé une note adressée à Pircalmo, de la part de Télenger. Il expose en détails un rituel et fait planer un doute sur les prouesses magiques de Pircalmo. Le mage est arrivé derrière moi pendant que je lisais ces papiers. Je devrais lui en parler.",text="dans sa tente dans le sud Folbosque.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4740,objective="Parlez à Pircalmo",step="On dirait que le rituel n'a pas fonctionné comme il fallait. Je dois parler à Pircalmo.",text="sur la colline au sud de Folbosque.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4740,objective="Parlez à Pircalmo",step="Pircalmo continue de maintenir le sort. Je devrais lui parler, maintenant que j'ai les noyaux dont il a besoin.",text="sur la colline au sud de Folbosque.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4740,objective="Parlez à Ranneth",step="Les atronachs sont dociles, et la forêt guérit rapidement. La ville est rassemblée autour d'un autel. Je dois arrêter Ranneth avant qu'elle tue Alanya.",text="à l'autel en Folbosque.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4740,objective="Parlez à Ranneth",step="Pircalmo est libre, Alanya ne risque plus rien, et Ranneth a présenté ses excuses aux deux. Je devrais aller lui parler.",text="dans sa maison de deux cannelures en Folbosque.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4750,objective="Escaladez la tour",step="Le Roi-nature agonise et Aranias a accepté d'endosser ses responsabilités. Elle m'a demandé de placer la couronne du Roi-nature au sommet de la tour pour permettre sa transformation.",text="au sommet de la montagne en Vercors, à travers le tunnels du trône dans le manoir et au-delà du feu sur le chemin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4750,objective="Escaladez la tour",step="Le Roi-Nature dit qu'il sera bientôt mort, et qu'Aranias doit accepter de le remplacer. Je devrais gravir la tour pour lui parler.",text="au sommet de la montagne en Vercors, à travers le tunnels du trône dans le manoir et au-delà du feu sur le chemin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4750,objective="Parlez à Aranias",step="Le Roi-Nature dit qu'il sera bientôt mort, et qu'Aranias doit accepter de le remplacer. Je devrais gravir la tour pour lui parler.",text="au sommet de la tour du trône au sommet de la montagne en Vercors, à travers le tunnels du trône dans le manoir et au-delà du feu sur le chemin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4750,objective="Parlez au Roi-Nature",step="Je dois parler au Roi-Nature",text="dans la tour du trône au sommet de la montagne en Vercors, à travers le tunnels du trône dans le manoir et au-delà du feu sur le chemin.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4750,objective="Parlez au Roi-Nature",step="Le Roi-nature est apparu sur le chemin. Je dois lui parler.",text="à l’oratoire de Vercors.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4750,objective="Parlez au Roi-Nature",step="Le Roi-nature est apparu sur mon chemin. Je dois lui parler.",text="dans le manoir en ruine en Vercors.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4751,objective="Parlez à Jéromec",step="Je dois parler à Jéromec Lemal.",text="à l’écurie au sud des quais, le long de la route ouest de la colonie.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4751,objective="Parlez à Jéromec",step="Je dois remettre les plans des navires à Jéromec Lemal.",text="à l’écurie au sud des quais, le long de la route ouest de la colonie.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4754,objective="Parlez à la préceptrice Fadalia",step="En entrant dans les quartiers de la préceptrice, j'ai assisté à une scène étrange, la préceptrice Fadalia aux prises avec son légendaire prédécesseur. Je devrais l'interroger pour savoir de quoi il retourne.",text="dans ses chambres, au sommet des escaliers du côté nord de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4754,objective="Parlez à la préceptrice Fadalia",step="En entrant dans les quartiers de la préceptrice, j'ai assisté à une scène étrange, maîtresse Fadalia aux prises avec son légendaire prédécesseur. Je devrais l'interroger pour savoir de quoi il retourne.",text="dans ses chambres, au sommet des escaliers du côté nord de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4754,objective="Parlez à la préceptrice Fadalia",step="Je dois trouver la préceptrice Fadalia, elle m'attend à l'entrée. Ensuite, je passerai à la dernière étape du rite de la lame de Léki.",text="à l'entrée sud de la ville.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
