{quest=4757,objective="Parlez à Fatahala",step="Alors que je me rendais au bassin, Fatahala est apparue. Je devrais lui parler.",text="aux bassins de l'est.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4757,objective="Parlez à Stibbons",step="Fatahala connaît un moyen de sortir du manoir, mais Stibbons refuse de partir avant d'avoir récupéré les bijoux de sa maîtresse. Je devrais parler à Stibbons.",text="dans la salle de la porte-starif au deuxième étage du manoir.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4757,objective="Parlez à Stibbons",step="Fatahala connaît un moyen de sortir du manoir, mais Stibbons refuse de partir avant d'avoir récupéré les bijoux de sa maîtresse. Je devrais parler au Stibbons.",text="dans la salle de la porte-starif au deuxième étage du manoir.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4757,objective="Parlez à Stibbons",step="J'ai récupéré les bijoux volés à dame Laurent. Et maintenant, je devrais me rendre aux bassins, pour retrouver Stibbons à l'entrée du tunnel secret.",text="aux bassins, à l’entrée du tunnel secret, quelque part à l’est du manoir.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4757,objective="Parlez à Stibbons 1",step="Je devrais aller m'assurer que le Stibbons va bien.",text="près de la sortie de la caverne du manoir aux réjouissances, au sud du Manoir lui-même.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4757,objective="Parlez à Stibbons 1",step="Je devrais aller m'assurer que Stibbons va bien.",text="près de la sortie de la caverne du manoir aux réjouissances, au sud du Manoir lui-même.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4757,objective="Parlez avec Fatahala",step="Alors que je me rendais au bassin, Fatahala est apparue. Je devrais lui parler.",text="aux bassins de l'est.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4758,objective="Entrez dans la prochaine zone",step="J'ai utilisé l'appareil et ouvert la porte vers la section suivante du Labyrinthe. Je devrais franchir la porte et continuer de chercher le vortex planaire.",text="dans les Labyrinthe à Escalier infini ci-dessus.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4758,objective="Entrez dans la prochaine zone",step="Je dois continuer de m'enfoncer dans le Labyrinthe, si je veux trouver le vortex planaire.",text="dans l'intérieur du Labyrinthe, au-delà du pont surplombant Escalier infini.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4758,objective="Parlez à Gabrielle",step="Je devrais parler à Gabrielle, elle aura peut-être des conseils à m'apporter sur la meilleure façon de progresser dans ce Labyrinthe.",text="dans le Labyrinthe qui conduit à Escalier infini.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4758,objective="Parlez à Gabrielle",step="Je dois parler à Hahnin et Gabrielle pour qu'ils m'exposent le plan de bataille de la guilde des Guerriers et de la guilde des Mages.",text="près de l’oratoire de l'Escalier infini.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4758,objective="Parlez à Méridia",step="Il semble que nous ayons réussi. La Coalescence a été vaincue, et on dirait que je suis en vie. Je devrais aller parler à Méridia et lui demander ce qu'il s'est passé.",text="dans la cité creuse chapelle de la Lumière.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4758,objective="Parlez à Vanus Galérion",step="J'ai déverrouillée l'entrée du Labyrinthe, et à ce moment-là, Vanus Galérion a ouvert un portail derrière moi.",text="près de l'entrée à Escalier infini.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4758,objective="Parlez au roi Dynar",step="J'ai choisi qui m'accompagnera pour ma percée dans le domaine de Molag Bal. Je devrais prévenir le roi Dynar que je suis prêt à partir.",text="près de l’oratoire de l'Escalier infini.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4758,objective="Parlez au roi Dynar",step="J'ai choisi qui m'accompagnera pour ma percée dans le domaine de Molag Bal. Je devrais prévenir le roi Dynar que je suis prête à partir.",text="près de l’oratoire de l'Escalier infini.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4758,objective="Parlez au roi Dynar",step="Nous avons interrompu la Coalescence et sauvé Nirn, mais à quel prix ? Le roi Dynar agonise devant moi. Je devrais lui parler avant qu'il soit trop tard.",text="dans la cité creuse chapelle de la Lumière.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4758,objective="Parlez au roi Dynar",step="Nous avons stoppé la Coalescence, mais il semble que le roi Dynar ait été mortellement blessé. Je devrais lui parler avant qu'il ne soit trop tard.",text="dans la cité creuse chapelle de la Lumière.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4764,objective="Parlez à Abnur Tharn",step="Une petite créature daedrique m'a dit de rejoindre Abnur Tharn à la guilde des mages de Daguefilante. On dirait que c'était un serviteur de Tharn.",text="à la guilde des mages de Daguefilante.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4764,objective="Parlez à Abnur Tharn",step="Une petite créature daedrique m'a dit de rejoindre Abnur Tharn à la guilde des mages du Guet de Davon. On dirait que c'était un serviteur de Tharn.",text="à la guilde des mages du Guet de Davon.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4764,objective="Parlez à Abnur Tharn",step="Une petite créature daedrique m'a dit de rejoindre Abnur Tharn à la guilde des mages du Guet de Vulkhel. On dirait que c'était un serviteur de Tharn.",text="à la guilde des mages du Guet de Vulkhel.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4766,objective="Parlez à Arienne Kerbol",step="D'après Kerbol, la mort de Draven était regrettable mais nécessaire pour sauver la ville et ses habitants.",text="près de l'autel du sanctuaire supérieur au bout du sentier menant au village à travers une porte sud-ouest.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4766,objective="Parlez à Arienne Kerbol 1",step="D'après Kerbol, la mort de Draven était regrettable mais nécessaire pour sauver la ville et ses habitants.",text="près de l'autel du sanctuaire supérieur au bout du sentier menant au village à travers une porte sud-ouest.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=4766,objective="Parlez à Resnoît",step="Je devrais demander à Resnoît ce que Draven et lui vont faire, à présent que Kerbol ne peut plus guérir Draven.",text="sur un rocher près de Draven, sur le chemin qui part de la porte sud-ouest du village vers le sanctuaire.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4766,objective="Parlez à Resnoît Léoncièle",step="Kerbol a admis que le village est atteint de lycanthropie. L'interruption du rituel de Draven a perturbé leur contrôle, ce qui devrait transformer tous les villageois en bêtes sanguinaires. Je devrais prévenir Resnoît.",text="dans le village.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=4766,objective="Parlez à Resnoît Léoncièle",step="Les villageois ont un secret, ça ne fait aucun doute. C'est une histoire de lycanthropie. Personne n'a voulu me répondre franchement. Je devrais prévenir Resnoît qu'il a raison de s'inquiéter.",text="devant la maison d'hôtes.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
