{quest=5057,objective="Adressez-vous à Aérona",step="J'ai décidé de laisser Déthisam Bérendas mettre son plan en œuvre. Je dois convaincre Aérona de l'abandonner et d'aller s'abriter.",text="à l’intérieur des catacombes de la maladrerie, dans le cimetière.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=5068,objective="Parlez à Nilynë",step="Aérona veut que j'aide Nilynë l'alchimiste. Je dois lui parler.",text="à l'intérieur de la maison Vérobar en zone de quarantaine du Serk.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=5068,objective="Parlez à Nilynë",step="J'ai mélangé les ingrédients ensemble. Je dois apporter la concoction à Nilynë.",text="à l'intérieur de la maison Vérobar en zone de quarantaine du Serk.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=5068,objective="Parlez à Nilynë",step="J'ai rassemblé les ingrédients que Nilynë demandait, je dois retourner dans la maison d'Ornis pour les lui apporter.",text="à l'intérieur de la maison Vérobar en zone de quarantaine du Serk.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=5071,objective="Parlez à Curinure",step="Je dois apprendre ce que je peux à propos de la guilde des mages, et voir si elle est faite pour moi.",text="dans l'une des Mages Guildes dans sa portée.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5071,objective="Parlez à Curinure",step="Je dois parler à Curinure pour lui confirmer que je souhaite rejoindre la guilde des mages.",text="dans l'une des Mages Guildes dans sa portée.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5074,objective="Parlez à Rudrasa",step="Je dois apprendre ce que je peux à propos de la guilde des mages, et voir si elle est faite pour moi.",text="à l’étage de la guilde des mages du Guet de Davon, en Éboulis.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=5074,objective="Parlez à Rudrasa",step="Je dois parler à Rudrasa pour lui confirmer que je souhaite rejoindre la guilde des mages.",text="à l'étage supérieur de la Guet de Davon Mages Guilde en Éboulis, en bas du hall à partir de l'entrée.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5076,objective="Parlez à Nemarc",step="Je dois apprendre ce que je peux à propos de la guilde des mages, et voir si elle est faite pour moi.",text="au rez-de-chaussée par l'escalier.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5076,objective="Parlez à Nemarc",step="Je dois parler à Rudrasa pour lui confirmer que je souhaite rejoindre la guilde des mages.",text="près de l'escalier dans la Daguefilante Mages Guilde en Glénumbrie.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5747,objective="Parlez à Hara",step="Hara m'a demandé de rejoindre les Astromanciens et de l'aider à résoudre les problèmes que rencontre Raidelorn. Je dois accepter de l'aider avant que nous puissions nous mettre au travail.",text="au sein de l'Observatoire Belkarth et je lui décide si je souhaite faire face aux Célestes.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5747,objective="Parlez à Hara",step="J'ai été accepté au sein des Astromanciens. Je dois compléter mon initiation en parlant à Hara.",text="dans l'Observatoire Belkarth pour devenir un Étoile-Gazer proprement dit et discuter des prochaines étapes.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5747,objective="Parlez à Hara",step="J'ai été acceptée au sein des Astromanciens. Je dois compléter mon initiation en parlant à Hara.",text="dans l'Observatoire Belkarth pour devenir un Étoile-Gazer proprement dit et discuter des prochaines étapes.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5747,objective="Parlez à Hara",step="J'ai trouvé Hara au quartier général des Astromanciens à Belkarth. Elle pourrait sans doute m'en dire plus au sujet des événements qui se déroulent à Raidelorn et me renseigner sur les Astromanciens.",text="au quartier général des Astromanciens, à Belkarth.",source="Indication géographique FR vérifiée : objectif et étape actuels"},
{quest=5748,objective="Parlez à la Voleuse",step="La Voleuse m'est subitement apparue après la défaite de Tarish-Zi. Je devrais lui parler.",text="dans la crypte de Tarish-Zi à l'intérieur du tombes des Na-Totambu.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5761,objective="Parlez à Kelmen",step="J'ai vaincu l'atronach d'air du Serpent. Je devrais parler à Kelmen Locke.",text="à l'extérieur de palais de Balamath dans les ruines de Balamath.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5761,objective="Parlez à Kelmen",step="Les souverains m'ont confirmé qu'il existe un quatrième atronach, créé par le Serpent. Je devrais en parler à Kelmen Locke.",text="au site rituel au sud de Forteresse d'Épervine.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5761,objective="Parlez à la Voleuse",step="Je devrais parler à la Voleuse pour apprendre où se trouve Kelmen Locke.",text="à dolmen du terrain des épreuves.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5761,objective="Parlez à la Voleuse",step="La Céleste Voleuse m'est apparue à un dolmen du terrain des épreuves, à Raidelorn. Je devrais lui parler.",text="à dolmen du terrain des épreuves.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5761,objective="Parlez à la Voleuse",step="La Céleste Voleuse m'est apparue au dolmen du terrain des épreuves, à Raidelorn. Je devrais lui parler.",text="à dolmen du terrain des épreuves.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5763,objective="Discutez avec Valla",step="Je suis arrivé au chai. Je devrais Discuter avec Valla.",text="à l'intérieur chai d'Ogondar.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5763,objective="Discutez avec Valla",step="Je suis arrivée au chai. Je devrais Discuter avec Valla.",text="à l'intérieur chai d'Ogondar.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5763,objective="Parlez à Ahlora",step="Je devrais parler de la Vision du Sourcier à Ahlora.",text="au-dessus du chai d'Ogondar.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5771,objective="Parlez à la Voleuse",step="Le rituel a fonctionné. Il nous a montré la régente Cassipia, qui serait donc la source de la perturbation magique. Elle a tué Kelmen lorsqu'il a essayé de l'arrêter. Je ferais mieux de parler à la Voleuse pour voir ce qu'elle en pense.",text="sur la vision que nous avons vue dans le Sanctuaire de clairvoyance en sépulcres hurlants.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=5771,objective="Parlez à la Voleuse",step="Maintenant que la Vipère exaltée a été vaincue et que nous sommes de retour à Belkarth, je devrais parler à la Voleuse.",text="à l'étage supérieur de l'Observatoire",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=6373,objective="Parlez à Shéogorath",step="Je dois parler à Shéogorath pour en savoir plus sur Volendrung.",text="à l'entrée de creux du Frometonneur, près des piles de fromage.",source="Immersive Quests FR local : objectif et étape explicites"},
{quest=6373,objective="Parlez à Shéogorath",step="Shéogorath se propose de me laisser utiliser Volendrung pendant la Guerre des Trois étendards en Cyrodiil, mais cela me coûtera mon âme. Je dois lui parler pour conclure notre affaire.",text="à l'entrée de creux du Frometonneur, près des piles de fromage.",source="Immersive Quests FR local : objectif et étape explicites"},
}
